window.IQ={"topics":[["gaze","Gaze & desire","غض البصر والشهوة"],["sin","Sins & their harm","الذنوب وآثارها"],["tawba","Repentance","التوبة والرجوع"],["sabr","Patience","الصبر"],["nafs","The self & Shaytan","النفس والشيطان"],["qalb","The heart","القلب"],["waqt","Time & life","الوقت والعمر"],["dhikr","Remembrance & duʿa","الذكر والدعاء"],["salah","Prayer & Qurʾan","الصلاة والقرآن"],["hubb","Love of Allah","محبة الله"],["hamm","Worry & joy","الهم والسرور"],["akhira","Death & the Hereafter","الموت والآخرة"]],"books":[["الداء والدواء","الداء والدواء = الجواب الكافي - ط عطاءات العلم"],["الوابل الصيب","الوابل الصيب - ط دار الحديث"],["الفوائد لابن القيم","الفوائد لابن القيم - ط عطاءات العلم"],["الرسالة التبوكية زاد المهاجر إلى ربه","الرسالة التبوكية زاد المهاجر إلى ربه - ط عطاءات العلم"],["رسالة ابن القيم إلى أحد إخوانه","رسالة ابن القيم إلى أحد إخوانه - ط عطاءات العلم"],["عدة الصابرين وذخيرة الشاكرين","عدة الصابرين وذخيرة الشاكرين - ط دار ابن كثير"],["جلاء الأفهام","جلاء الأفهام - ت الأرنؤوط"],["إغاثة اللهفان في مصايد الشيطان","إغاثة اللهفان في مصايد الشيطان - ط عطاءات العلم"],["حادي الأرواح إلى بلاد الأفراح","حادي الأرواح إلى بلاد الأفراح - ط المدني"],["روضة المحبين ونزهة المشتاقين","روضة المحبين ونزهة المشتاقين - ط العلمية"],["الكلام على مسألة السماع","الكلام على مسألة السماع"],["مفتاح دار السعادة ومنشور ولاية العلم والإرادة","مفتاح دار السعادة ومنشور ولاية العلم والإرادة - ط عطاءات العلم"],["طريق الهجرتين وباب السعادتين","طريق الهجرتين وباب السعادتين - ط عطاءات العلم"],["مدارج السالكين","مدارج السالكين - ط الكتاب العربي"],["زاد المعاد في هدي خير العباد","زاد المعاد في هدي خير العباد - ط عطاءات العلم"],["بدائع الفوائد","بدائع الفوائد - ط عطاءات العلم"]],"q":[["قلةُ التوفيق، وفسادُ الرأي، وخفاءُ الحقِّ، وفسادُ القلبِ، وخُمولُ الذِّكْر، وإضاعةُ الوقت، ونفرةُ الخلق، والوحشةُ بين العبد وبين ربِّه، ومنع إجابة الدعاء، وقسوة القلب، ومحقُ البركة في الرزق والعمر، وحرمان العلم،، ولباس الذُّلِّ، وإدالةُ العدوِّ، وضيقُ الصدر، والابتلاءُ بقُرَناءِ السَّوءِ الذين يفسدون القلب ويضيعون الوقت، وطول الهمِّ والغمِّ، وضنْكُ المعيشة، وكسفُ البال: تتولَّدُ من المعصية والغفلة عن ذكر الله كما يتولَّدُ الزرعُ عن الماء والإحراقُ عن النار. وأضدادُ هذه تتولَّدُ عن الطاعة.",2,47,"/edition/37/section/9177#page-54",3298,50],["أجمع السائرون إلى الله أنّ القلوب لا تعطَى مُناها حتّى تصل إلى مولاها ، ولا تصل إلى مولاها حتى تكون صحيحة سليمة، ولا تكون صحيحة سليمة حتى ينقلب داؤها فيصير نفس دوائها. ولا يصحّ لها ذلك إلا بمخالفة هواها، فهواها مرضها، وشفاؤها مخالفته، فإن استحكم المرضُ قتَلَ أو كاد.\nوكما أنّ من نهى نفسه عن الهوى كانت الجنّة مأواه، فكذا يكون قلبه في هذه الدار في جنة عاجلة لا يشبه نعيمَ أهلها نعيمٌ البتة، بل التفاوت الذي بين النعيمين كالتفاوت الذي بين نعيم الدنيا والآخرة. وهذا أمر لا يصدّق به إلا من باشر قلبه هذا وهذا.",0,76,"/edition/19/section/6273#page-69",3121,39],["مفاسد العشق الدينية والدنيوية\nأحدها: الاشتغال بحب المخلوق وذكره عن حب الرب تعالى وذكره.\nالثاني: عذاب قلبه بمعشوقه.\nالثالث: أن العاشق قلبه أسير في قبضة معشوقه، يسومه الهوانَ.\nالرابع: أنه يشتغل به عن مصالح دينه ودنياه.\nالخامس: أن آفات الدنيا والآخرة أسرع إلى عشاق الصور من النار في يابس الحطب.\nالسادس: أنه إذا تمكن من القلب واستحكم وقوي سلطانه أفسد الذهنَ، وأحدث الوسواسَ. وربما التحق صاحبه بالمجانين الذين فسدت عقولهم فلا ينتفعون بها.\nالسابع: أنه ربما أفسد الحواس أو بعضها إمَّا فسادًا معنويًا أو صُوريًّا.\nالثامن: [اشتغال] النفس عن استخدام القوى الحيوانية والنفسانية، فتتعطل تلك القوى، فيحدث بتعطلها من الآفات على البدن والروح ما يعِزّ دواؤه أو يتعذّر.",0,495,"/edition/20/section/6536#page-561",3121,38],["والمقصود:\nأن العبد إذا وقع في شدة أو كربة أو بلية خانه قلبُه ولسانُه وجوارحُه عما هو أنفع شيء له، فلا ينجذب قلبه للتوكّل على الله، والإنابة إليه، والجمعية عليه، والتضرع والتذلل والانكسار بين يديه.\nولا يطاوعه لسانه لذكره، وإن ذكره بلسانه لم يجمع بين قلبه ولسانه، فينحبسَ القلب على اللسان بحيث يؤثّر الذكر، ولا ينحبسُ القلب واللسان على المذكور، بل إن ذكَرَ أو دعا ذكَرَ بقلب لاهٍ ساهٍ غافل.\nولو أراد من جوارحه أن تعينه بطاعة تدفع عنه لم تنقَدْ له، ولم تطاوعه.\nوهذا كله أثر الذنوب والمعاصي، كمن له جند يدفعون عنه الأعداء، فأهمل جنده، وضيعهم، وأضعفهم، وقطع أخبارهم، ثم أراد منهم عند هجوم العدو عليه أن يستفرغوا وسعَهم في الدفع عنه بغير قوة!",0,215,"/edition/20/section/6433#page-281",167,36],["أصولُ المعاصي كلِّها -كبارها وصغارها- ثلاثةٌ: تعلُّقُ القلبِ بغير الله، وطاعةُ القوة الغضبيَّة، والقوة الشهوانيَّةِ.\nوهي: الشركُ، والظلمُ، والفواحشُ.\nفغايةُ التعلُّق بغير الله: الشركُ وأن يُدْعى معه إلهٌ آخرُ، وغايةُ طاعة القوَّة الغضبيَّة: القتلُ، وغايةُ طاعة القوَّةِ الشهوانيَّة: الزِّنى.\nوهذه الثلاثةُ يدعو بعضُها إلى بعضٍ: فالشركُ يدعو إلى الظُّلم والفواحش؛ كما أنَّ الإخلاص والتوحيد يَصْرِفُهما عن صاحبه، وكذلك الظلمُ يدعو إلى الشرك والفاحشة؛ فإنَّ الشرك أظلمُ الظلم؛ كما أنَّ أعدل العدل التوحيدُ؛ فالعدلُ قرينُ التوحيد، والظلمُ قرينُ الشِّرْكِ، والفاحشةُ تدعو إلى الشرك والظُّلم، ولا سيَّما إذا قَويتْ إرادتُها ولم تحصُلْ إلا بنوع من الظُّلم والاستعانة بالسحر والشيطان، فهذه الثلاثةُ يَجُرُّ بعضُها إلى بعض ويأمُرُ بعضُها ببعضٍ.",2,116,"/edition/37/section/9227#page-123",179,36],["الطريق المانع من حصول هذا الداء [داء العشق]، فأمران:\nأحدهما: غضّ البصر.\nفإنّ النظرة سهم مسموم من سهام إبليس. ومَن أطلق لحظاتِه دامت حسراتُه.\nوالثاني: اشتغال القلب بما يصدّه عن ذلك، ويحول بينه وبيّن الوقوع فيه، وهو إمّا خوفٌ مقلِق، أو حبٌّ مزعِج.\nفمتى خلا القلب من خوف ما فواتُه أضرُّ عليه من حصول هذا المحبوب، أو خوفِ ما حصولُه أضرُّ عليه من ذوات هذا المحبوب، أو محبةِ ما هو أنفع له وخير له من هذا المحبوب وفواتُه أضرّ عليه من ذوات هذا المحبوب = لم يجد بدًّا من عشق الصور.",0,422,"/edition/20/section/6506#page-488",561,35],["عشرةُ أشياء ضائعةٌ لا يُنتفع بها:\n\nعلمٌ لا يُعمَل به،\nوعملٌ لا إخلاصَ فيه ولا اقتداء،\nومالٌ لا يُنْفَقُ منه فلا يَستمتِعُ به جامعُه في الدُّنيا ولا يُقدِّمُه أمامَه إلى الآخرة، وقلبٌ فارغٌ من محبة الله والشوق إليه والأنس به،\nوبدنٌ معطَّلٌ من طاعته وخدمته،\nومحبةٌ لا تتقيَّدُ برِضىَ المحبوب وامتثال أوامره،\nووقتٌ معطَلٌ عن استدراك فارطٍ أو اغتنام برٍّ وقُربةٍ،\nوفكرٌ يجولُ فيما لا ينفعُ،\nوخدمةُ من لا تُقرِّبُك خدمتُه إلى الله ولا تعودُ عليك بصلاح دُنياك،\nوخوفُك ورجاؤُك لمن ناصيته بيد الله وهو أسيرٌ في قبضته ولا يَملِك لنفسه ضرًّا ولا نفعًا ولا موتًا ولا حياةً ولا نشورًا.\n\nوأعظمُ هذه الإضاعات إضاعتان هُما أصلُ كلِّ إضاعةٍ: إضاعةُ القلب وإضاعةُ الوقت؛ فإضاعة القلب من إيثار الدُّنيا على الآخرة، وإضاعةُ الوقت من طول الأمل.\n\nفاجتمع الفسادُ كلُّه في اتباع الهوى وطول الأمل، والصلاحُ كلُّه في اتِّباع الهدى والاستعداد للِّقاء. والله المستعانُ.",2,162,"/edition/37/section/9265#page-169",2673,35],["عمُرُكَ هو وقتُك الحاضرُ بين ما مَضَى وما يُستقبَلُ:\nفالذي مضى تُصلِحه بالتوبة والنَّدم والاستغفار، وذلك شيءٌ لا تعبَ عليك فيه ولا نصبَ ولا معاناةَ عملٍ شاق، إنما هو عملُ قلبٍ.\nوتمتنع فيما يُستَقبل من الذُّنوب، وامتناعُك تركٌ وراحةٌ، ليس هو عملًا بالجوارح يَشُقُّ عليك معاناتُه، وإنما هو عزمٌ ونيَّةٌ جازمةٌ تُريحُ بدنَك وقلبَك وسرَّك.\n\nفما مضى تُصلِحُهُ بالتوبة، وما يُستقبل تُصلِحُه بالامتناع والعزم والنية، وليس للجوارح في هذين نصبٌ ولا تعبٌ، ولكن الشأن في عمرك، وهو وقتك الذي بين الوقتين؛ فإن أضعتَه أضعتَ سعادتَك ونجاتك، وإن حفظتَه مع إصلاح الوقتين اللَّذين قبله وبعده بما ذُكِرَ نجوتَ وفُزتَ بالراحة واللَّذَّةِ والنعيم، وحفظُهُ أشقُّ من إصلاح ما قبله وما بعده؛ فإن حفظه أن تُلزِمَ نفسَك بما هو أولى بها وأنفعُ لها وأعظمُ تحصيلًا لسعادتها، وفي هذا تفاوت الناس أعظم تفاوتٍ.",2,169,"/edition/37/section/9271#page-176",1094,34],["الكريم يصبر في طاعة الرحمن، واللئيم يصبر في طاعة الشيطان؛ فاللئام أصبر الناس في طاعة أهوائهم وشهواتهم، وأقل الناس صبرًا في طاعة ربهم؛ فيصبر على البذل في طاعة الشيطان أتم صبر، ولا يصبر على البذل للَّه في أيسر شيء، ويصبر على تحمّل المشاق لهوى نفسه في مرضاة عدوه، ولا يصبر على أدنى المشاق في مرضاة ربه، ويصبر على ما يُقال في عِرضِه في المعصية، ولا يصبر على ما يقال في عرضه إذا أوذي في اللَّه.",5,95,"/edition/67/section/16030#page-139",26,33],["الصبر على الشهوة أسهل من الصبر على ما توجبه الشهوة؛\nفإنها إما أن توجب ألما وعقوبة،\nوإما أن تقطع لذة أكمل منها،\nوإما أن تضيع وقتا إضاعته حسرة وندامة،\nوإما أن تثلم عرضا توفيره أنفع للعبد من ثلمه،\nوإما أن تذهب مالا بقاؤه خير له من ذهابه،\nوإما أن تضع قدرا وجاها قيامه خير من وضعه،\nوإما أن تسلب نعمة بقاؤها ألذ وأطيب من قضاء الشهوة،\nوإما أن تطرق لوضيع إليك طريقا لم يكن يجدها قبل ذلك،\nوإما أن تجلب هما وغما وحزنا وخوفا لا يقارب لذة الشهوة،\nوإما أن تنسي علما ذكره ألذ من نيل الشهوة،\nوإما أن تشمت عدوا وتحزن وليا،\nوإما أن تقطع الطريق على نعمة مقبلة،\nوإما أن تحدث عيبا يبقى صفة لا تزول؛ فإن الأعمال تورث الصفات والأخلاق.",2,202,"/edition/37/section/9293#page-209",1033,33],["مجمل عقوبات الذنوب\n- الختم على القلوب والأسماع، والغشاوة على الأبصار.\n- التثبيط عن الطاعة، والإقعاد عنها.\n- جعل القلب أصم لا يسمع الحق، أبكم لا ينطق به، أعمى لا يراه.\n- الخسف بالقلب، كما يخسف بالمكان وما فيه.\n- مسخ القلب، فيُمسَخ كما تمسخ الصورة.\n- مكر الله بالماكر، ومخادعته للمخادع، واستهزاؤه بالمستهزئ، وإزاغته لقلب الزائغ عن الحق.\n- نكسُ القلبِ حتى يرى الباطل حقًّا والحق باطلًا، والمعروف منكرًا والمنكرَ معروفًا.\n- حجاب القلب عن الربّ في الدنيا، والحجاب الأكبر يوم القيامة.\n- المعيشة الضَّنْك في الدنيا وفي البرزخ، والعذاب في الآخرة.",0,278,"/edition/20/section/6459#page-344",2083,32],["بين المذنب والمبتدع\n\nومعلوم أن المذنب إنما ضرره على نفسه، وأما المبتدع فضرره على النوع.\nوفتنة المبتدع في أصل الدين، وفتنة المذنب في الشهوة.\nوالمبتدع قد قعد للناس على صراط الله المستقيم يصدَّهم عنه، والمذنب ليس كذلك.\nوالمبتدع قادح في أوصاف الرب وكماله، والمذنب ليس كذلك.\nوالمبتدع مناقض لما جاء به الرسول ﷺ، والعاصي ليس كذلك.\nوالمبتدع يقطع على الناس طريقَ الآخرة، والعاصي بطيء السير بسبب ذنوبه.",0,332,"/edition/20/section/6488#page-398",2067,32],["وإذا جمع الدعاءُ حضورَ القلب وجمعيتَه بكلّيته على المطلوب، وصادف وقتًا من أوقات الإجابة الستة وهي: الثلث الأخير من الليل، وعند الأذان، وبين الأذان والإقامة، وأدبار الصلوات المكتوبات، وعند صعود الإِمام يوم الجمعة على المنبر حتى تقضى الصلاة، وآخر ساعة بعد العصر من ذلك اليوم؛ وصادف خشوعًا في القلب، وانكسارًا بين يدي الربّ، وذلًاّ له، وتضرّعًا ورِقّةً؛ واستقبل الداعي القبلة، وكان على طهارة، ورفع يديه إلى الله تعالى، وبدأ بحمد الله والثناء عليه، ثم ثنّى بالصلاة على محمَّد عبده ورسوله ﷺ، ثم قدّم بين يدي حاجته التوبة والاستغفار، ثم دخل على الله، وألحّ عليه في المسألة، وتملّقه، ودعاه رغبة ورهبة، وتوسّل إليه بأسمائه وصفاته وتوحيده، وقدّم بين يدي دعائه صدقة، فإنّ هذا الدعاء لا يكاد يُرَدّ أبدًا، ولا سيما إن صادف الأدعية التي أخبر النبي ﷺ أنها مظنة الإجابة، أو أنها متضمنة للاسم الأعظم.",0,16,"/edition/20/section/6368#page-82",420,31],["وأما الخطرات فشأنها أصعب، فإنّها مبدأ الخير والشرّ، ومنها تتولّد الإرادات والهمم والعزائم.\nفمن راعى خطراتِه ملَكَ زمامَ نفسه، وقهر هواه.\nومن غلبته خطراتُه فهواه ونفسه له أغلَب، ومن استهان بالخطرات قادته قسرًا إلى الهلكات.",0,353,"/edition/20/section/6493#page-419",1041,31],["العبد فيه داعيان: داع يدعوه إلى الدنيا وشهواتها ولذاتها، وداعٍ يدعوه إلى اللَّه والدار الآخرة وما أعد فيها لأوليائه من النعيم المقيم، فعصيان داعي الشهوة والهوى هو الصبر، وإجابة داعي اللَّه والدار الآخرة هو الشكر.",5,208,"/edition/67/section/16045#page-252",3209,31],["كبائر الذنوب\nقال أبو طالب المكي: جمعتُها من أقوال الصحابة، فوجدتها:\nأربعة في القلب، وهي: الشرك، والإصرار على المعصية، والقنوط من رحمة الله، والأمن من مكر الله.\nوأربعة في اللسان، وهي: شهادة\nالزور، وقذف المحصنات، واليمين الغَموس، والسحر.\nوثلاث في البطن: شرب الخمر، وأكل مال اليتيم، وأكل الربا.\nواثنان في الفرج، وهما: الزنا، واللواطة.\nواثنان في اليدين، وهما: القتل، والسرقة.\nوواحد في الرجلين، وهو الفرار من الزحف.\nوواحد يتعلق بجميع الجسد وهو عقوق الوالدين.",0,292,"/edition/20/section/6469#page-358",1059,30],["قال إبليس:\nأهلكتُ بني آدم بالذنوب، وأهلكوني بالاستغفار وبلا إله إلا الله. فلما رأيت ذلك بثثتُ فيهم الأهواءَ، فهم يذنبون، ولا يتوبون؛ لأنّهم يحسبون أنهم يحسنون صُنْعا!",0,331,"/edition/20/section/6487#page-397",22,30],["اللحظات:\nهي رائد الشهوة ورسولها، وحفظها أصلُ حفظ الفرج.\nفمن أطلق بصره أورده موارد الهلَكات.\nقال النبي ﷺ: «لا تُتْبعِ النظرةَ النظرةَ، فإنّما لك الأولى، وليست لك الآخِرة».\nوفي المسند عنه ﷺ: «النظرة سهم مسموم من سهام إبليس، فمن غضّ بصره عن محاسن امرأةٍ لله أورث الله قلبه حلاوةَ إلى يوم يلقاه» هذا معنى الحديث.",0,348,"/edition/20/section/6493#page-414",2097,30],["علماءُ السَّوْءِ جلسوا على بابِ الجنَّةِ يدعونَ إليها الناسَ بأقوالِهِم ويَدْعونَهُم إلى النار بأفعالِهِم؛ فكلَّما قَالتْ أقوالُهُم للناس: هَلُمُّوا! قالتْ أفعالُهُم: لا تَسْمَعوا منهم! فلو كان ما دَعَوْا إليه حقًّا كانوا أولَ المستجيبين له! فهم في الصورة أدِلَّاءُ وفي الحقيقةِ قُطَّاعُ الطريق.",2,85,"/edition/37/section/9210#page-92",3201,30],["وفي الصدقة فوائد ومنافع لا يحصيها إلا الله، فمنها: أنها تقي مصارع السوء، وتدفع البلاء حتى إنها لتدفع عن الظالم، وتطفئ الخطيئة، وتحفظ المال، وتجلب الرزق، وتفرح القلب، وتوجب الثقة بالله وحسن الظن به، وترغم الشيطان، وتزكي النفس وتنميها، وتحبب العبد إلى الله وإلى خلقه، وتستر عليه كل عيب، وتزيد في العمر، وتستجلب أدعية الناس ومحبتهم، وتدفع عن صاحبها عذاب القبر، وتكون عليه ظلا يوم القيامة، وتشفع له عند الله، وتهون عليه شدائد الدنيا والآخرة، وتدعوه إلى سائر أعمال البر فلا تستعصي عليه، وفوائدها ومنافعها أضعاف ذلك.",5,490,"/edition/67/section/16055#page-534",2674,30],["في الصدقة فوائد ومنافع لا يحصيها إلا الله، فمنها:\n أنها تقي مصارع السوء، وتدفع البلاء، حتى إنها لتدفع عن الظالم، وتطفئ الخطيئة، وتحفظ المال، وتجلب الرزق، وتفرح القلب، وتوجب الثقة بالله، وحسن الظن به، وترغم الشيطان، وتزكِّي النفس وتنميها، وتُحبب العبد إلى الله، وإلى خلقه، وتستُر عليه كل عيب، وتزيد في العمر، وتستجلب أدعية الناس ومحبتهم، وتدفع عن صاحبها عذاب القبر، وتكون عليه ظلًّا يوم القيامة، وتشفع له عند الله، وتهون عليه شدائد الدنيا والآخرة، وتدعوه إلى سائر أعمال البر، فلا تستعصي عليه، وفوائدها ومنافعها أضعاف ذلك.",5,490,"/edition/67/section/16055#page-534",2674,30],["في الصدقة فوائد ومنافع لا يحصيها إلا اللَّه، فمنها: أنها تقي مصارع السوء، وتدفع البلاء حتى إنها لتدفع عن الظالم.. وتطفئ الخطيئة، وتحفظ المال، وتجلب الرزق، وتفرح القلب، وتوجب الثقة باللَّه وحسن الظن به -كما أن البخل سوء الظن باللَّه- وترغم الشيطان وتزكى النفس وتنميها، وتُحبّبُ العبد إلى اللَّه وإلى خلقه، وتَستُر عليه كل عيب -كما أن البخل يغطي عليه كل حسنة- وتزيد في العمر، وتستجلب أدعية الناس ومحبتهم، وتدفعُ عن صاحبها عذاب القبر، وتكون عليه ظلًّا يوم القيامة، وتشفع له عند اللَّه، وتهونُ عليه شدائد الدنيا والآخرة، وتدعوه إلى سائر أعمال البر فلا تستعصي عليه، وفوائدها ومنافعها أضعاف ذلك.",5,490,"/edition/67/section/16055#page-534",2674,30],["والمقصود:\nأن العبد قد يكون بعد التوبة خيرًا مما كان قبل الخطيئة وأرفع درجةً.\nوقد تُضعِف الخطيئةُ همّتَه، وتُوهن عزمَه، وتُمرض قلبَه، فلا يقوى دواء التوبة على إعادته إلى الصحة الأولى، فلا يعود إلى\nدرجته.\nوقد يزول المرض بحيث تعود الصحة كما كانت، ويعود إلى مثل عمله، فيعود إلى درجته.",0,211,"/edition/20/section/6431#page-277",38,29],["والنظر أصل عامة الحوادث التي تصيب الإنسان، فإن النظرة تولّد خطرةً، ثم تولّد الخطرة فكرةً، ثم تولّد الفكرة شهوةً، ثم تولّد الشهوة إرادةً، ثم تقوى فتصير عزيمةً جازمةً، فيقع الفعل، ولا بدّ، ما لم يمنع منه مانع.\nوفي هذا قيل: الصبر على غضّ البصر أيسرُ من الصبر على ألم ما بعده.",0,350,"/edition/20/section/6493#page-416",9,29],["قال بكر بن عبد اللَّه: قلت لأخ لي: أوصني. فقال: ما أدري ما أقول، غير أنه ينبغي لهذا العبد أن لا يفتر من الحمد والاستغفار، فإن العبد بين نعمة وذنب، ولا تصلح النعمة إلا بالحمد والشكر، ولا يصلح الذنب إلا بالتوبة والاستغفار، فأوسعني علمًا ما شئت.",5,268,"/edition/67/section/16048#page-312",6,29],["قال بعض السلف:\nالمعاصي بريد الكفر، كما أن القُبلة بريد الجماع، والغناء بريد الزنا، والنظر بريد العشق، والمرض بريد الموت.",0,125,"/edition/20/section/6394#page-191",2051,28],["والمقصود:\nأن الذنوب والمعاصي سلاحٌ ومددٌ يُمِدُّ بها العبدُ أعداءه، ويعينهم بها على نفسه، فيقاتلونه بسلاحه، ويكون معهم على نفسه، وهذا غاية الجهل:\nوما يبلغ الأعداءُ من جاهلٍ\nما يبلغ الجاهلُ من نفسه",0,242,"/edition/20/section/6444#page-308",18,28],["لمَّا كان مبدأ [الزنا] من قبل البصر جعل [الله] الأمرَ بغضّه مقدمًا على حفظ الفرج، فإن الحوادث مبداها من النظر، كما أن معظم النار من مستصغَر الشرر. فتكون نظرة، ثم خطرة، ثم خطوة، ثم خطيئة.",0,347,"/edition/20/section/6491#page-413",2051,28],["ومن خاصية [الزنا]: أنه يوجب الفقر، ويقصر العمر، ويكسو صاحبه سوادَ الوجه وثوبَ المقت بين الناس.\nومن خاصيته أيضًا: أنّه يشتّت القلب، ويُمرِضه إن لم يُمِتْه. ويجلب الهمّ والحزن والخوف، ويباعد صاحبه من الملَك، ويقرّب منه الشيطان.",0,378,"/edition/20/section/6494#page-444",1137,28],["كمال اللذة والفرح والسرور ونعيم القلب وابتهاج الروح تابع لأمرين:\nأحدهما: كمال المحبوب في نفسه وجماله وأنه أولى بإيثار الحب من كلّ ما سواه.\nوالأمر الثاني: كمال محبته، واستفرغ الوسع في حبه، وإيثار قربهِ والوصولِ إليه على كل شيء.",0,540,"/edition/20/section/6544#page-606",1584,28],["العلم إن لم يكن للَّه كان للنفس والهوى، والعمل إن لم يكن للَّه كان للرّياء والنفاق، والمال إن لم ينفق للَّه أنفق في طاعة الشيطان والهوى، والجاه إن لم يستعمل للَّه استعمل صاحبه في هواه وحظوظه، والقوة إن لم يستعملها في أمر اللَّه استعملتْه في معصيته.",5,107,"/edition/67/section/16033#page-151",19,28],["كما أنه لا نِسْبَةَ لنعيم ما في الجنة إلى نعيم النظر إلى وجه الأعلى سبحانه، فلا نسبة لنعيم الدنيا إلى نعيم محبته، ومعرفته، والشوق إليه، والأُنس به، بل لذة النظر إليه سبحانه تابعة لمعرفتهم به، ومحبتهم له؛ فإن اللذة تتبع الشعور والمحبة، فكلما كان المحب أعرف بالمحبوب، وأشد محبة له، كان الْتذاذه بقربه ورؤيته ووصوله إليه أعظم.",7,50,"/edition/13/section/4139#page-91",3585,28],["وأكثر توبة الخواص: من السيئات القلبية والإرادات المزاحمة لمراد الرب منهم، ومن ترك الحسنات، ومن الاشتغال بحسنة عما هو أكبر منها، ومن غفلتهم عن شهود المنة في الحسنات.\nوغالب توبة العوام: من السيئات البدنية والشبهات المتعلقة بها.\nفأعلى الناس مرتبة من لم تضله الشبهات، ولم تغوه الشهوات.",10,361,"/edition/38/section/9687#page-421",39,28],["الذنوب إذا تكاثرت : طُبع على قلب صاحبها ، فكان من الغافلين ، كما قال بعض السلف في قوله تعالى ( كلا بل ران على قلوبهم ما كانوا يكسبون ) قال : هو الذنب بعد الذنب ، وقال الحسن : هو الذنب على الذنب حتى يعمي القلب ، حتى قال : وأصل هذا أن القلب يصدأ من المعصية ، فاذا زادت : غلب الصدأ حتى يصير راناً ، ثم يغلب حتى يصير طبْعاً ، وقفلاً ، وختماً ، فيصير القلب في غشاوة وغلاف ، فاذا حصل له ذلك بعد الهدى والبصيرة : انتكس ، فصار أعلاه أسفله ، فحينئذ يتولاه عدوه ، ويسوقه حيث أراد .",0,148,"/edition/20/section/6409#page-214",34,28],["فالعبدُ في هذه الدار مفتونٌ بشهواته، ونفسه الأمّارة، وشيطانه المُغوِي المزَيِّن، وقُرنائه، وما يراه ويشاهده مما يعجز صبره عنه، ويتفق مع ذلك ضعف الإيمان واليقين، وضعف القلب، ومرارة الصبر، وذَوْقُ حلاوة العاجل،  وميل النفس إلى زهرة الحياة الدنيا، وكون العِوض مؤجّلًا في دار أخرى غير هذه الدار التي منها خلق، وفيها نشأ، فهو مكلفٌ بأن يترك شهوته الحاضرة المشاهدة لغيبٍ طُلب منه الإيمان به:\n\nفَوَ اللّهِ لَوْلا اللهُ يُسْعِدُ عَبْدَهُ\n بِتَوْفِيقِه وَاللهُ بِالْعَبْدِ أَرْحَمُ\nلَمَا ثَبَتَ الإيمَانُ يَوْمًا بِقَلْبِهِ\n عَلَى هذِه العِلاّتِ وَالأَمْرُ أَعْظَمُ\nوَلا طَاوَعَتْهُ النّفْسُ في تَرْكِ شَهْوَةٍ\n مَخَافَةَ نَارٍ جَمْرُها يَتَضَرَّمُ\nولا خاف يومًا من مقامِ إلهه\nعليه بحكمِ القسطِ إذ ليس يظلم",7,899,"/edition/13/section/4767#page-940",56,28],["القتل يتعلق به ثلاث حقوق:\nحقّ لله، وحقّ للمقتول، وحقّ للولي.\nفإذا سلّم القاتل نفسه طوعًا واختيارًا إلى الولي ندمًا على ما فعل، وخوفًا من الله، وتوبةً نصوحًا، سقط حقُّ الله بالتوبة، وحقُّ الولي بالاستيفاء أو الصلح أو العفو، وبقي حقّ المقتول يعوّضه الله عنه يوم القيامة عن عبده التائب المحسن، ويصلح بينه وبينه، فلا يذهب حقّ هذا، ولا تبطل توبة هذا.",0,335,"/edition/20/section/6489#page-401",2068,27],["قال تعالى: ﴿وَجَعَلْنَا مِنْهُمْ أَئِمَّةً يَهْدُونَ بِأَمْرِنَا لَمَّا صَبَرُوا وَكَانُوا بِآيَاتِنَا يُوقِنُونَ (٢٤)﴾: جمع -سبحانه- بين الصبر واليقين؛ إذ هما سعادة العبد، وفقدهما يُفقده  سعادته، فإن القلب تطرقه طوارق الشهوات المُخالفة لأمر الله، وطوارق الشبهات المخالفة لخبره، فبالصبر يَدفع الشهوات، وباليقين يَدفع الشبهات.",4,16,"/edition/52/section/12325#page-11",41,27],["القلب محتاج إلى ما يحفظ عليه قوَّته، وهو الإيمان وأوراد الطاعات؛ وإلى حِمية عن المؤذى الضارِّ، وذلك باجتناب الآثام والمعاصي وأنواع المخالفات؛ وإلى استفراغه من مادة فاسدة تعرض له، وذلك بالتوبة النصوح، واستغفار غافر الخطيئات.",7,24,"/edition/13/section/4121#page-65",38,27],["من غضَّ بصره عما حرَّمه الله عليه عوّضه الله من جنسه ما هو خير منه؛ فكما أمسك نورَ بصره عن المحرمات، أطلق الله نور بصيرته وقلبه، فرأى به ما لم يره من أطلق بصره ولم يَغُضَّه عن محارم الله، وهذا أمر يُحِسُّهُ الإنسان من نفسه؛ فإن القلب كالمرآة، والهوى كالصدأ فيها، فإذا خلصت من الصدأ انطبعت فيها صُوَر الحقائق كما هى عليه، وإذا صَدِئتْ لم ينطبع فيها صور المعلومات، فيكون علمه وكلامه من باب الخَرْص والظنون.",7,77,"/edition/13/section/4160#page-118",49,27],["فليس لمن قد فُتن بفتنةٍ دواءٌ مثل الصبر، فإن صبر كانت الفتنة مُمَحِّصةً له، ومُخلّصة من الذنوب، كما يُخلّص الكيرُ خَبَثَ الذهب والفضة. فالفتنةُ كِيْر القلوب، ومَحَكّ الإيمان، وبها يَتبيّن الصادق من الكاذب. والفتنةُ قَسَمت الناس إلى صادقٍ وكاذبٍ، ومؤمن ومنافق، وطيبٍ وخبيثٍ، فمن صبر عليها كانت رحمةً في حَقِّه، ونجا بصبره من فتنةٍ أعظم منها، ومن لم يَصْبر عليها وقع في فتنةٍ أشدّ منها.",7,896,"/edition/13/section/4762#page-937",1066,27],["فلو عرف الإنسان مقدار عمره؛ فإن كان قصير العمر لم يتهنأ بالعيش، وكيف يتهنأ به وهو يترقب الموت في ذلك الوقت؟! فلولا طول الأمل لخربت الدنيا، وإنما عمارتها بالآمال.\nوإن كان طويل العمر ــ وقد تحقق ذلك ــ فهو واثق بالبقاء، فلا يبالي بالانهماك في الشهوات والمعاصي وأنواع الفساد، ويقول: إذا قرب الوقت أحدثت توبة.\nوهذا مذهب لا يرتضيه الله تعالى عز وجل من عباده، ولا يقبله منهم، ولا يصلح عليه أحوال العالم، ولا يصلح العالم إلا على هذا الذي اقتضته حكمته وسبق في علمه.",11,802,"/edition/73/section/18200#page-902",2119,27],["الاجتماع بالإخوان قسمان:\n أحدهما: اجتماع على مؤانسة الطبع وشغل الوقت، فهذا مضرّته أرجح من منفعته، وأقل ما فيه أنه يفسد القلب، ويضيع الوقت.\n الثاني: الاجتماع بهم على التعاون على أسباب النجاة والتواصي بالحق والصبر، فهذا أعظم الغنيمة وأنفعها، ولكن فيه ثلاث آفات:\n الأولى: تَزَيُّنُ بعضهم لبعض.\nالثانية: الكلام والخلطة أكثر من الحاجة.\nالثالثة: أن يصير ذاك شهوة وعادة ينقطع بها عن المقصود.\n\nوبالجملة، فالاجتماع والخلطة لقاح: إما للنفس الأمارة، وإما للقلب والنفس المطمئنة، والنتيجة مستفادة من اللقاح، فمن طاب لقاحه طابت ثمرته، وهكذا الأرواح الطيّبة لقاحها من الملك، والخبيثة لقاحها من الشيطان، وقد جعل الله سبحانه بحكمته الطيبات للطيبين، والطيبين للطيبات.. وعكس ذلك",2,71,"/edition/37/section/9192#page-78",120,27],["ومن عقوبات الذنوب:\nأنها تُزيل النِّعم وتُحِلّ النِّقَم.\nفما زالت عن العبد نعمة إلا بذنب، ولا حلّت به نقمة إلا بذنب؛ كما قال علي بن أبي طالب رضي الله عنه: ما نزل بلاءً إلا بذنب، ولا رُفِعَ بلاءً إلا بتوبة.",0,179,"/edition/20/section/6419#page-245",6,26],["وإذا كان العبد في حال حضور ذهنه وقوته وكمال إدراكه قد تمكَّن منه الشيطان، واستعمله فيما يريده من معاصي الله، وقد أغفل قلبه عن الله، وعطَّل لسانَه عن ذكره، وجوارحَه عن طاعته، فكيف الظن به عند سقوط قواه، واشتغال قلبه ونفسه بما هو فيه من ألم النزع، وجَمْع الشيطانِ له كلَّ قوته وهمته، وحَشْدِه عليه بجميع ما يقدر عليه، لينال منه فرصته، فإن ذلك آخر العمل، فأقوى ما يكون عليه شيطانُه ذلك الوقت، وأضعف ما يكون هو في تلك الحال؟ فمَن تُرى يَسلَمُ على ذلك؟",0,218,"/edition/20/section/6433#page-284",112,26],["ما ذُكِر الله عز وجل على صعبٍ إلا هان، ولا على عَسيرٍ إلا تَيَسَّر، ولا مشقَّةٍ إلا خَفَّتْ، ولا شِدَّةٍ إلَّا زَالت، ولا كُرْبَةٍ إلا انفرجت، فَذِكْرُ الله تعالى هو الفرج بعد الشدة، واليُسْرُ بعد العُسْرِ، والفرج بعد الغم والهم.",1,185,"/edition/42/section/9999#page-233",1153,26],["الصبر ضربان:\nضرب بدني، وضرب نفساني،\nوكلٌّ منهما نوعان: اختياري، واضطراري، فهذه أربعة أقسام:\nالأول: البدنى الاختياري، كتعاطي الأعمال الشاقّة على البدن اختيارًا وإرادةً.\nالثاني: البدني الاضطراري، كالصبر على ألم الضرب والمرض والجراحات والبرد والحرّ وغير ذلك.\nالثالث: النفساني الاختياري، كصبر النَّفْس عن فعل ما لا يَحسُنُ فعلُه شرعًا ولا عقلًا.\nالرابع: النفساني الاضطراري، كصبر النّفس عن محبوبها قهرًا إذا حِيل بينها وبينه.",5,35,"/edition/67/section/16022#page-79",24,26],["باب المنهيات يمحوه اللَّه سبحانه ويبطل أثره بأمور عديدة من فعل العبد وغيره، فإنه يُبطله بالتوبة النصوح، وبالاستغفار، وبالحسنات الماحية، وبالمصائب المكفرة، وباستغفار الملائكة، وبدعاء المؤمنين -فهذه ستة في حال حياته- وبتشديد الموت وكربه وسياقه عليه -فهذا عند مفارقته الدنيا- وبهول المطلع، وروعة الملكين في القبر، وضغطته، وعصرته، وبشدة الموقف وعنائه وصعوبته، وبشفاعة الشافعين فيه، وبرحمة أرحم الراحمين له، فإن عجزت عنه هذه الأمور فلا بد له من دخول النار، ويكون لبثُه فيها على قدر بقاء خبثه ودرنه، فإن اللَّه حرَّم الجنة إلا على طيِّب، فما دام درنُه ووسخُه وخبثُه فيه فهو في غير التطهير حتى يتصفّى من ذلك الوسخ والخبَث.",5,71,"/edition/67/section/16028#page-115",2180,26],["النفوسُ الشريفة الزكيَّةُ العُلْويَّة تعشقُ صفاتِ الكمال بالذَّات، فأحبُّ شيء إليها العلمُ، والشَّجاعةُ، والعفَّةُ، والجودُ، والإحسانُ، والصبر، والثباتُ؛ لمناسبة هذه الأوصاف لجوهرها، بخلاف النفوس اللئيمة الدنيَّة فإنَّها بِمعْزِلٍ عن محبَّة هذه الصفات، وكثيرٌ من الناس يحملُه على الجود والإحسان فرطُ عشقه ومحبَّتِه له، واللَّذَّةُ التي يجدُها في بذله، كما قال المأمون: لقد حُبِّبَ إليَّ العفوُ حتى خشيتُ ألَّا أُؤْجَر عليه.\nوقيل للإمام أحمد بن حنبل رحمه الله تعالى: تعلَّمتَ هذا العلمَ لله؟ فقال: أمَّا لله فعزيز، ولكنْ شيءٌ حُبِّبَ إليَّ، ففعلتُه.",9,69,"/edition/56/section/12512#page-65",1545,26],["ولا ريب أن القلب يصدأ كما يصدأ النحاس والفضة وغيرهما، فجلاؤُهُ بذكر الله، فإنه يجلوه حتى يدعه كالمرآة البيضاء، فإذا تُرِك صدِئ، فإذا ذكره جلاه.\n\nوصدأ القلب بأمرين: بالغفلة والذنب، وجلاؤه بشيئين: بالاستغفار والذكر.",1,92,"/edition/42/section/9936#page-140",166,26],["فالذنب إما أن يميت القلب، أو يُمرضَه مرضًا مخوفًا، أو يضعف قوته، ولا بد، حتى ينتهي ضعفه إلى الأشياء الثمانية التي استعاذ منها النبي ﷺ، وهي: الهمّ والحزن، والعجز والكسل، والجبن والبخل، وضلَع الدَّين وغلبة الرجال.",0,178,"/edition/20/section/6418#page-244",1059,25],["معنى الصبر ومداره\n\nالصبر: حبس النفس عن التَّسخُّط بالمقدور، وحبس اللِّسان عن الشكوى، وحبس الجوارح عن المعصية، كاللَّطْم، وشق الثياب، ونتف الشعر، ونحو ذلك.\nفمدار الصبر على هذه الأركان الثلاثة، فإذا قام بها العبد كما ينبغي انقلبت المحنة في حقه منحة، واستحالت البلية عطية، وصار المكروه محبوبًا.",1,6,"/edition/42/section/9888#page-54",26,25],["كلُّ شيء له صدأ، وصدأ القلب الغفلة والهوى، وجِلاؤه الذكر والتوبة والاستغفار.",1,97,"/edition/42/section/9957#page-145",165,25],["القلب الميت الذي لا حياة به، فهو لا يعرف ربه، ولا يعبده بأمره وما يحبه ويرضاه، بل هو واقفٌ مع شهواته ولذاته، ولو كان فيها سخط ربه وغضبه، فالهوى إمامه، والشهوة قائده، والجهل سائسه، والغفلة مركبه، فهو بالفكر في تحصيل أغراضه الدنيوية معمور، وبسكرة الهوى وحبِّ العاجلة مغمور، يُنادَى إلى الله وإلى الدار الآخرة من مكان بعيد، فلا يستجيب للناصح ويتّبع كل شيطان مريد؛ الدنيا تُسخطه وتُرضيه، والهوى يُصِمُّه عما سوى الباطل ويُعميه. فمخالطة صاحب هذا القلب سُقْمٌ، ومعاشرته سُمٌّ، ومجالسته هلاك.",7,12,"/edition/13/section/4114#page-53",2081,25],["الناس ثلاثة أقسام:\nالسابقون المقربون، يتوبون من ترك الحسنات، والاشتغال عن الحسنة الكبيرة بأصغر منها.\nوالمقتصدون، توبتهم من مواقعة السيئات.\nوالظالمون: يذنبون ولا يتوبون.",10,361,"/edition/38/section/9687#page-421",6,25],["العبد إما أن يكون مستقيماً أو مائلاً عن الاستقامة؛ فإن كان مائلاً عن الاستقامة فخوفه من العقوبة على ميله، ولا يصح الإيمان إلا بهذا الخوف، وهو ينشأ من ثلاثة أُمور:\nأحدها: معرفته بالجناية وقبحها.\nوالثاني: تصديق الوعيد وأن الله رتّب على المعصية عقوبتها.\nوالثالث: أنه لا يعلم لعلّه يُمنع من التوبة ويُحال بينه وبينها إذا ارتكب الذنب.\n\nفبهذه الأمور الثلاثة يتم له الخوف، وبحسب قوتها وضعفها تكون قوة الخوف وضعفه.",12,616,"/edition/65/section/15863#page-701",7,25],["فكيف يوفَّق لحسن الخاتمة من أغفل اللهُ سبحانه قلبَه عن ذكره، واتّبَعَ هواه، وكان أمره فُرُطًا؟ فبعيدٌ من قلبٍ بعيدٍ من الله تعالى، غافلٍ عنه، متعبّدٍ لهواه، أسيرٍ لشهواته؛ ولسانٍ يابسٍ من ذكره، وجوارحَ معطلةٍ من طاعته مشتغلةٍ بمعصيته أن توفَّقَ للخاتمة بالحسنى.",0,219,"/edition/20/section/6433#page-285",35,24],["فليس على النفس الأمّارة أشقُّ من العملِ لله، وإيثارِ رضاه على هواها؛ وليس لها أنفعُ منه.\nوليس على النفس المطمئنّة أشقُّ من العمل لغير الله، وإجابةِ داعي الهوى؛ وليس عليها أضرُّ منه.",0,360,"/edition/20/section/6493#page-426",17,24],["مراتب الحب\n١- العلاقة، وسميت «علاقة» لتعلق القلب بالمحبوب.\n٢- الصبابة، وسميت بذلك لانصباب القلب إلى المحبوب.\n٣- الغرام، وهو لزوم الحب للقلب لزومًا لا ينفك عنه، ومنه سمي الغريم غريمًا لملازمته صاحبَه.\n٤- العشق، وهو إفراط المحبة.\n٥- الشوق، وهو سفر القلب إلى المحبوب أحث السفر.\n٦- التتيُّم، وهو آخر مراتب الحب، وهو تعبد المحب لمحبوبه.\n٧- الخلة، وهي تتضمن كمال المحبة ونهايتَها، بحيث لا يبقى في قلب المحب سعة لغير محبوبه، وهي منصب لا يقبل المشاركة بوجهٍ ما.",0,444,"/edition/20/section/6515#page-510",545,24],["والمحبوب قسمان:\nمحبوب لنفسه، ومحبوب لغيره.\nوالمحبوب لغيره لابد أن ينتهي إلى المحبوب لنفسه، دفعًا للتسلسل المحال.\nوكل ما سوى المحبوب الحق فهو محبوب لغيره، وليس شيء يُحَبّ لنفسه إلا الله وحده.",0,451,"/edition/20/section/6520#page-517",528,24],["العشاق ثلاثة أقسام:\n- منهم من يعشق الجمال المطلق.\n- ومنهم من يعشق الجمال المقيد، سواء طمع بوصاله أو لم يطمع.\n- ومنهم من لا يعشق إلا من يطمع في الوصول إليه.\n- فعاشق الجمال المطلق قلبه يهيم في كل واد، وله في كل صورة جميلة مراد.\n- وعاشق الجمال المقيد أثبتُ على معشوقه، وأدوَمُ محبةً له.\n- وعاشق الجمال الذي يطمع في وصاله أعقَلُ العشاق وأعرَفهم، وحبه أقوى لأن الطمع يُمِدّه ويُقوّيه.",0,567,"/edition/20/section/6558#page-633",33,24],["السيئات والذنوب هي أمراضٌ قلبية، كما أن الحمَّى والأوجاع أمراضٌ بدنيةٌ، والمريضُ إذا عُوفي من مرضه عافية تامة عادت إليه قوته وأفضل منها، حتى كأنه لم يَضْعُفْ قط؛ فالقوةُ المتقدِّمة بمنزلة الحسنات، والمرضُ بمنزلة الذنوب، والصحةُ والعافيةُ بمنزلة التوبة سواء بسواء.",1,25,"/edition/42/section/9901#page-73",6,24],["إضاعة الوقت أشدُّ من الموت؛ لأنَّ إضاعة الوقت تقطعك عن الله والدار الآخرة، والموتُ يقطعك عن الدنيا وأهلها.",2,44,"/edition/37/section/9176#page-51",2112,24],["القلب يَمرضُ كما يمرض البدنُ، وشفاؤهُ في التوبة والحِمْية، ويَصْدَأ كما تَصْدأ المرآةُ، وجلاؤهُ بالذكر، ويَعْرَى كما يَعْرَى الجسمُ، وزينتُهُ التَّقوى، ويجوعُ ويظمأ كما يجوع البدن، وطعامه وشرابه المعرفةُ والمحبة والتوكل والإنابة والخدمةُ.",2,143,"/edition/37/section/9249#page-150",676,24],["العبد على جناح سفر إما إلى الجنة وإما إلى النار؛ فإذا طال عمره وحسُنَ عمله كان طول سفره زيادةً له في حصول النعيم واللَّذَّة؛ فإنه كلما طال السفر إليها كانت الصبابة أجل وأفضل، وإذا طال عمره وساء عمله كان طول سفره زيادةً في ألمه وعذابه ونزولًا له إلى أسفل؛ فالمسافرُ إما صاعدٌ وإما نازلٌ.",2,275,"/edition/37/section/9361#page-282",3136,24],["أصحاب العشق الشيطاني لهم مِن تَوَلَّي الشيطان والإشراك به بقَدْر ذلك، لما فيهم من الإشراك بالله، ولما فاتهم من الإخلاص له، ففيهم نصيب من اتخاذ الأنداد، ولهذا ترى كثيرًا منهم عبدًا لذلك المعشوق، مُتَيمًا فيه، يصرخُ في حضوره ومغيبه: أنه عبده، فهو أعظم ذكرًا له من ربّه، وحُبّه في قلبه أعظم من حبّ الله فيه، وكفى به شاهدًا بذلك على نفسه فالإنسان على نفسه بصيرة، ولو ألقى معاذيره.",7,151,"/edition/12/section/4101#page-543",49,24],["قال بعض العلماء: إذا علا الذكر الذكر؛ هربت الملائكة، وعجت الأرض إلى ربها، ونزل سخط الجبار ــ ﷻ ــ عليهم، وغشيتهم اللعنة، وحفت بهم الشياطين، واستأذنت الأرض ربها أن تخسف بهم، وثقل العرش على حملته، وكبرت الملائكة، واستعرت الجحيم، فإذا جاءته رسل الله لقبض روحه؛ نقلوها إلى ديار إخوانهم، وموضع عذابهم، فكانت روحه بين أرواحهم. وذلك أضيق مكانا، وأعظم عذابا من تنور الزناة. فلا كانت لذة توجب هذا العذاب الأليم! وتسوق صاحبها إلى مرافقة أصحاب الجحيم. تذهب اللذات، وتعقب الحسرات، وتفنى الشهوة، وتبقى الشقوة.",9,510,"/edition/57/section/12856#page-536",1153,24],["كل طالب لشيء فهو محب له، مؤثر لقربه، ساع في طريق تحصيله، متوصل إليه بجهده، وهذا يوجب له تعلق أفكاره بجمال محبوبه وكماله وصفاته التي يحب لأجلها، وتعلقها بما يناله به من الخير والفرحة والسرور.\nففكره في حال محبوبه دائر بين الجمال والإجمال، والحسن والإحسان، فكلما قويت محبته له ازداد هذا الفكر وقوي وتضاعف، حتى يستغرق أجزاء القلب فلا يبقى فيه فضل لغيره، بل يصير بين الناس بقالبه، وقلبه كله في حضرة محبوبه.\nفإن كان هذا المحبوب هو المحبوب الحق الذي لا تنبغي المحبة إلا له، ولا يحب غيره إلا تبعا لمحبته، فهو أسعد المحبين به، وقد وضع الحب موضعه، وتهيأت نفسه لكمالها الذي خلقت له الذي لا كمال لها بدونه بوجه.\nوإن كانت تلك المحبة لغيره من المحبوبات الباطلة المتلاشية التي تفنى وتبقى حزازات النفوس بها على حالها، فقد وضع المحبة في غير موضعها، وظلم نفسه أعظم ظلم وأقبحه، وتهيأت بذلك نفسه لغاية شقائها وألمها.",11,529,"/edition/73/section/18079#page-629",1584,24],["كل ذي لب يعلم أنه لا طريق للشيطان عليه إلا من ثلاث جهات:\n\nأحدها: التزيد والإسراف، فيزيد على قدر الحاجة، فتصير فضلةً، وهي حظُّ الشيطان ومدخله إلى القلب. وطريق الاحتراز [منه الاحتراز] من إعطاء النفس تمامَ مطلوبها من غذاءٍ أو نوم أو لذةٍ أو راحة؛ فمتى أغلقتَ هذا البابَ حصلَ الأمان من دخول العدو منه.\n\nالثانية: الغفلة؛ فإن الذاكر في حصن الذكر؛ فمتى غَفَل فتح باب الحصن، فولجَه العدوُّ، فيعسُر عليه أو يصعبُ إخراجه.\n\nالثالثة: تكلف ما لا يعنيه من جميع الأشياء.",2,277,"/edition/37/section/9364#page-284",1200,24],["منافع غض البصر:\nأحدها: أنّه امتثال لأمر الله الذي هو غاية سعادة العبد في معاشه ومعاده.\nالثانية: أنه يمتنع من وصول أثر السهم المسموم الذي لعل فيه هلاكه.\nالثالثة: أنّه يورث القلب أنسًا بالله وجمعية على الله.\nالرابعة: أنه يقوّي القلب ويفرحه.\nالخامسة: أنه يُكسب القلب نورًا.\nالسادسة: أنّه يُورثه فراسةً صادقةً يميّز بها بين المحِقّ والمبطل والصادق والكاذب.\nالسابعة: أنّه يورث القلب ثباتًا وشجاعةً وقوةً، فيجمع الله له بين سلطان البصيرة والحجة وسلطان القدرة والقوة.\nالثامنة: أنه يسدّ على الشيطان مدخله إلى القلب، فإنّه يدخل مع النظرة، وينفذ معها إلى القلب أسرع من نفوذ الهواء في المكان الخالي.\nالتاسعة: أنّه يُفرغ القلب للفكرة في مصالحه والاشتغال بها.\nالعاشرة: أنّ بين العين والقلب منفذًا وطريقًا يوجب انفعال أحدهما عن الآخر، وأن يصلح بصلاحه ويفسد بفساده.",0,421,"/edition/20/section/6506#page-487",49,23],["لذات الدنيا ثلاثة أنواع:\nفأعظمها وأكملها: ما أوصل إلى لذة الآخرة.\nوالنوع الثاني: لذة تمنع لذة الآخرة، وتُعقِب آلامًا أعظمَ منها، كلذة الذين اتخذوا من دون الله أوثانًا مودةَ بينهم في الحياة الدنيا.\nوالنوع الثالث: لذة لا تعقِبُ لذةً في دار القرار ولا ألمًا، ولا تمنع أصل لذة دار القرار، وإن منعَتْ كمالَها. وهذه اللذة المباحة التي لا يستعان بها على لذة الآخرة. فهذه زمانها يسير، ليس لتمتُّعُ النفس بها قدر، ولابدّ أن تشغل عما هو خير وأنفع منها.",0,546,"/edition/20/section/6549#page-612",3088,23],["قال شيخ الإسلام: «العارف يسير إلى الله بين مشاهدة المِنَّة، ومطالعة عيب النفس والعمل».\nفمشاهدةُ المنة توجب له المحبة والحمد والشكر لوليِّ النعم والإحسان، ومطالعةُ عيب النفس والعمل توجب له الذل والانكسار، والافتقار والتوبة في كل وقت، وأن لا يرى نفسه إلا مفلسًا.",1,12,"/edition/42/section/9891#page-60",532,23],["الصلاة إنما تُكَفِّرُ سيئات من أدَّى حقها، وأكمل خشوعها، ووقف بين يدي الله تعالى بقلبه وقالبه؛ فهذا إذا انصرف منها وجد خِفَّةً من نفسه، وأحس بأثقالٍ قد وُضِعَتْ عنه، فوجد نشاطًا وراحةً وروحًا، حتى يتمنى أنه لم يكن خرج منها؛ لأنها قرةُ عينه، ونعيمُ روحه، وجنة قلبه، ومُسْتَراحُه في الدنيا، فلا يزال كأنه في سجن وضيق حتى يدخل فيها، فيستريح بها، لا منها، فالمُحِبُّون يقولون: نصلي فنستريح بصلاتنا، كما قال إمامهم وقدوتهم ونبيهم ﷺ: «يا بلالُ أرِحنا بالصَّلاة»، وقال ﷺ: «جُعِلت قُرَّة عيني في الصّلاةِ».",1,46,"/edition/42/section/9912#page-94",1840,23],["تأملات في دعاء:\n«اللَّهُمَّ إني ظلمت نفسي ظلمًا كثيرًا، وإنه لا يغفر الذنوب إلا أنت، فاغفر لي مغفرة من عندك وارحمني، إنك أنت الغفور الرحيم»\n\nجمع في هذا الدعاء الشريفِ العظيمِ القدْرِ بين الاعتراف بحاله، والتَّوسُّلِ إلى ربه عز وجل بفضله وجوده، وأنه المنفرد بغفران الذنوب، ثم سأل حاجته بعد التوسل بالأمرين معًا، فهكذا أدب الدعاء وآداب العبودية.",1,229,"/edition/42/section/10017#page-277",130,23],["من أعجبِ الأشياءِ:\n\nأن تعرِفَه ثم لا تحبَّهُ، وأن تسمع داعِيَهُ ثم تتأخَّر عن الإجابة، وأن تعرفَ قدرَ الربح في معاملتِهِ ثم تعامل غيرَهُ، وأن تعرف قدْر غضبهِ ثم تتعرَّض له، وأن تذوقَ ألمَ الوَحْشةِ في معصيتِهِ ثم لا تَطْلُبَ الأنسَ بَطاعتِهِ، وأن تذوقَ عُصْرةَ القلبِ عند الخوْض في غير حديثه والحديث عنه ثم لا تشتاق إلى انشراح الصَّدْرِ بذِكْرِهِ ومناجاتِهِ، وأن تذوقَ العذابَ عند تعلُّق القلب بغيره ولا تهرب منه إلى نعيم الإقبال عليه والإنابة إليه! وأعجبُ من هذا علمُك أنَّك لا بدَّ لك منهُ وأنَّك أحوجُ شيءٍ إليه وأنت عنه مُعْرِضٌ وفيما يُبعِدُك عنه راغبٌ!",2,62,"/edition/37/section/9187#page-69",1062,23],["الاجتماعُ بالإخوانِ قسمانِ:\nأحدُهُما: اجتماعٌ على مؤانسةِ الطبع وشُغْل الوقتِ؛ فهذا مَضَرَّتُهُ أرجحُ من منفعتِهِ، وأقلُّ ما فيه أنَّه يُفْسِدُ القلبَ ويُضيِّعُ الوقتَ.\nالثاني: الاجتماعُ بهم على التعاونِ على أسباب النَّجاةِ والتَّواصي بالحقِّ والصبر؛ فهذا من أعظم الغنيمةِ وأنفعها، ولكنَّ فيه ثلاث آفاتٍ: إحداها: تزيُّنُ بعضهم لبعضٍ. الثانيةُ: الكلامُ والخِلْطة أكثر من الحاجةِ. الثالثةُ: أن يصيرَ ذلك شهوةً وعادةً ينقطعُ بها عن المقصود.\nوبالجملةِ فالاجتماعُ والخِلْطَةُ لِقاحٌ: إما للنفس الأمَّارةِ، وإما للقلبِ والنفس المطمئنَّةِ، والنتيجةُ مستفادةٌ من اللِّقاحِ؛ فمن طابَ لِقاحُهُ طابتْ ثمرتُهُ. وهكذا الأرواح الطيبةُ لِقاحُها من المَلكِ، والخبيثةُ لِقاحُها من الشيطان، وقد جعلَ الله سبحانه بحكمتِهِ الطَّيِّباتِ للطَّيِّبين والطَّيِّبينَ للطَّيِّباتِ، وعَكْسَ ذلك.",2,71,"/edition/37/section/9192#page-78",120,23],["إنما كان الصبر والشكر سببًا لانتفاع صاحبهما بالآيات؛ لأنَّ الإيمان ينبني على الصبر والشكر؛ فنصفُهُ صبرٌ ونصفه شكرٌ؛ فعلى حسب صبر العبد وشكره تكون قوةُ إيمانِه، وآياتُ الله إنما ينتفع بها من آمن بالله وآياته، ولا يتم له الإيمان إلا بالصبر والشكر؛ فإن رأس الشكر التوحيد، ورأس الصبر ترك إجابة داعي الهوى.",2,191,"/edition/37/section/9284#page-198",9,23],["الصادقون السائرون إلى الله والدار الآخرة قسمان:\nقسمٌ صَرَفوا ما فضلَ من أوقاتهم بعد الفرائض إلى النوافل البدنيَّة وجعلوها دأبهم؛ من غير حرص منهم على تحقيق أعمال القلوب ومنازلها وأحكامها، وإن لم يكونوا خالين من أصلها، لكن هِمَمَهم مصروفةٌ إلى الاستكثار من الأعمال.\nوقسمٌ صرفوا ما فضَلَ عن الفرائض والسنن إلى الاهتمام بصلاح قلوبهم وعكوفها على الله وحده والجمعية عليه وحفظ الخواطر والإرادات معه، وجعلوا قوة تعبُّدهم بأعمال القلوب من تصحيح المحبة والخوف والرجاء والتوكُّل والإنابة، ورأوا أن أيسر نصيبٍ من الواردات التي تَرِدُ على قلوبهم من الله أحبُّ إليهم من كثير من التطوعات البدنيَّة.",2,208,"/edition/37/section/9299#page-215",2612,23],["الشركُ والكذبُ والرياءُ شجرةٌ في القلب؛ ثمرها في الدنيا الخوف والهمُّ والغمّ وضيق الصدر وظلمةُ القلب، وثمرها في الآخرة الزقُّوم والعذابُ المقيم.",2,241,"/edition/37/section/9327#page-248",3104,23],["الله سبحانه سمى الزواني والزناة خبيثين وخبيثات، وجنس هذا الفعل قد شُرِعَتْ فيه الطهارة وإن كان حلالًا، وسُمِّيَ فاعله جُنُبًا، لبعده عن قراءة القرآن وعن الصلاة وعن المساجد، فمُنِعَ من ذلك كله حتى يتطهر بالماء، فكذلك إذا كان حرامًا يبعد القلب عن الله وعن الدار الآخرة، بل يحول بينه وبين الإيمان، حتى يُحْدِثَ طُهرًا كاملًا بالتوبة، وطُهرًا لبدنه بالماء.",7,111,"/edition/13/section/4187#page-152",2341,23],["العبدُ في هذه الدار مفتونٌ بشهواته، ونفسه الأمّارة، وشيطانه المُغوِي المزَيِّن، وقُرنائه، وما يراه ويشاهده مما يعجز صبره عنه، ويتفق مع ذلك ضعف الإيمان واليقين، وضعف القلب، ومرارة الصبر، وذَوْقُ حلاوة العاجل، وميل النفس إلى زهرة الحياة الدنيا، وكون العِوض مؤجّلًا في دار أخرى غير هذه الدار التي منها خلق، وفيها نشأ، فهو مكلفٌ بأن يترك شهوته الحاضرة المشاهدة لغيبٍ طُلب منه الإيمان به.",7,899,"/edition/13/section/4767#page-940",56,23],["وكثيرٌ من الأجواد يعشقُ الجودَ أعظمَ عِشق، فلا يصبِرُ عنه مع حاجته إلى ما يجودُ به، ولا يقبلُ فيه عَذْلَ عاذلٍ، ولا تأخذُه فيه لومةُ لائم، وأما عشَّاق العلم فأعظمُ شَغَفًا به وعشقًا له من كل عاشقٍ بمعشوقِه، وكثيرٌ منهم لايشْغَلُهُ عنه أجملُ صورة من البشر.\nوقيل لامرأةِ الزُّبَيْر بن بكَّار - أو غيره ـ: هنيئًا لكِ؛ إذ ليست لك ضَرَّة، فقالت: والله لهذه الكتبُ أضرُّ عليَّ من عِدَّة ضرائرَ!",9,108,"/edition/57/section/12639#page-134",9,23],["وقد جعل الله سبحانه العينَ مِرْآة القلب، فإذا غضَّ العبدُ بصرَه غضَّ القلبُ شهوتَه وإرادتَه، وإذا أطلق بصره أطلق القلبُ شهوتَه.",9,92,"/edition/56/section/12512#page-88",33,23],["شرع الله سبحانه لعباده عند [المصيبة والنعمة] ما يحفظ به العبد قلبه وإيمانه ودينه أن يستلبه الشيطان ويستفزه، فشرع لهم عند المصيبة الصبر والاسترجاع، وعند النعمة سجود الشكر، والتواضع لله، وحمده وشكره، فبذلك تدوم النعمة، كما أن بالصبر والاسترجاع تندفع المصيبة عن القلب أو تخف، فعارض الشيطان وحزبه أمر الله، وشرعوا عند المصيبة والنعمة الصوتين الأحمقين الفاجرين: صوت الندب والنياحة والدعاء بالويل والعويل وتوابع ذلك، وصوت الغناء والمزامير وآلات اللهو وتوابع ذلك.",10,31,"/edition/38/section/9430#page-92",184,23],["وأعظم محرِّكات الهوى ودواعيه ثلاثة أشياء تُسْكِر الروح: النظر واستماع الغناء وشرب الخمر، فهذه الثلاثة هي أقوى أسباب العشق والفجور، والنفس الأمَّارة محبة لها مؤثرة لها، فجاء الشيطان إلى النفوس ودعاها من هذه الأبواب الثلاثة.",10,75,"/edition/38/section/9464#page-136",17,23],["الذنوب تزيل النِّعَم ولا بد، فما أذنب عبد ذنبا إلا زالت عنه نعمة من الله بحسب ذلك الذنب؛ فإن تاب وراجعَ رجعت إليه أو مثلها، وإن أصر لم ترجع إليه، ولا تزال الذنوب تزيل عنه نعمة نعمة حتى تسلبه النِّعَمَ كلَّها !\nقال الله تعالى:\n{إن الله لا يغير ما بقوم حتى يغيروا ما بأنفسهم}\n\nوبالجملة فإنَّ المعاصي نار النعم تأكلُها كما تأكل النار الحطبَ، عياذا بالله من زوال نعمته وتحوّل عافيته.",12,588,"/edition/65/section/15854#page-673",2066,23],["على حسب صبر العبد وشكره تكون قوة إيمانه، وآيات الله إنما ينتفع بها من آمن بالله، ولا يتم له الإيمان إلا بالصبر والشكر؛ فإن رأس الشكر التوحيد، ورأس الصبر ترك إجابة داعي الهوى.",2,131,"/edition/36/section/9060#page-127",9,23],["ولو عطّل المجرم المعصية وأقبل على الطاعة:\n لضاقت عليه نفسُه،\nوضاق صدره،\nوأعيَتْ عليه مذاهبُه، حتى يعاودها.\n\nحتى إنّ كثيرًا من الفسّاق لَيواقع المعصية من غير لذة يجدها، ولا داعية إليها.",0,139,"/edition/20/section/6401#page-205",1042,23],["إن لله عزَّ وجلَّ على القلوب أنواعًا من العبوديَّة؛ من الخشية والخوف والإشفاق وتوابعها؛ ومن المحبة والإنابة وابتغاء الوسيلة إليه وتوابعها.\n\nوهذه العبوديَّاتُ لها أسبابٌ تهيِّجُها وتبعثُ عليها، فكلُّ ما قيَّضه الربُّ تعالى لعبده من الأسباب الباعثة على ذلك المهيِّجة له فهو من أسباب رحمته له، ورُبَّ ذنبٍ قد هاجَ لصاحبه من الخوف والإشفاق والوَجَل والإنابة والمحبة والإيثار  والفرار إلى الله ما لا يَهِيجُه له كثيرٌ من الطَّاعات.\n\nوكم من ذنبٍ كان سببًا لاستقامة العبد وفراره إلى الله وبُعْده عن طرق الغيِّ، وهو بمنزلة من خَلَط فأحسَّ بسوء مِزاجه، وكان عنده أخلاطٌ مُزْمِنةٌ قاتلةٌ وهو لا يشعُر بها، فشرب دواءً أزال تلك الأخلاط العَفِنَة التي لو دامت لترامت به إلى الفساد والعطب.\n\nوإنَّ من تبلغُ رحمتُه ولطفُه وبرُّه بعبده هذا المبلغَ وما هو أعجبُ وألطفُ منه، فحقيقٌ به أن يكون الحبُّ كلُّه له، والطَّاعةُ كلُّها له، وأن يُذْكَر فلا يُنسى، ويُطاع فلا يُعصى، ويُشْكَر فلا يُكْفَر.",11,293,"/edition/72/section/17851#page-291",550,23],["الهوى صنمٌ، ولكلِّ عبد صنمُ في قلبه بحسب هواه، وإنَّما بعث الله رسله بكسر الأصنام، وعبادته وحده لا شريك له، وليس مرادُ الله ــ سبحانه ــ كسرَ الأصنام المجسَّدة، وترك الأصنام التي في القلب، بل المراد كسرها من القلب أوَّلًا.",9,481,"/edition/56/section/12536#page-472",33,23],["من أحوال علي بن أبي طالب رضي الله عنه\n\n- وهذا علي بن أبي طالب رضي الله عنه وبكاؤه وخوفه.\n- وكان يشتد خوفه من اثنتين : طول الأمل، واتباع الهوى. قال: فأما طول الأمل فيُنْسي الآخرة، وأما اتباع الهوى فيصدّ عن الحق. ألا وإن الدنيا قد ولّت مدبرةً، والآخرةُ مقبلةٌ، ولكل واحدة منهما بنون، فكونوا من أبناء الآخرة، ولا تكونوا من أبناء الدنيا، فإن اليوم عمل ولا حسابَ، وغدًا حساب ولا عملَ.",0,94,"/edition/20/section/6390#page-160",2049,22],["قال عبد الحق الإشبيلي:\nواعلم أنّ سوء الخاتمة -أعاذنا الله منها- لا تكون لمن استقام ظاهره، وصلح باطنه، ما سمع بهذا ولا علم به، ولله الحمد.\nوإنّما تكون لمن له فساد في العقيدة، أو إصرار على الكبائر، وإقدام على العظائم.\nفربّما غلب ذلك عليه، حتى ينزل به الموت قبل التوبة، فيأخذه قبل إصلاح الطوِيّة، ويُصطلَم قبل الإنابة، فيظفر به الشيطان عند تلك الصدمة، ويختطفه عند تلك الدهشة. والعياذ بالله.",0,391,"/edition/20/section/6497#page-457",2068,22],["العبدُ إذا قام في الصلاة غار الشيطان منه، فإنه قد قام في أعظم مقام، وأقربِه، وأغيظِه للشيطان، وأشدِّه عليه، فهو يحرص ويجتهد كل الاجتهاد أن لا يقيمه فيه، بل لا يزال به يَعِدُه ويُمَنِّيه ويُنْسِيه، ويجلب عليه بخيله ورَجِلِه حتى يُهوِّن عليه شأن الصلاة، فيتهاون بها، فيتركها.\nفإن عجز عن ذلك منه، وعصاه العبد، وقام في ذلك المقام، أقبل عدو الله تعالى حتى يخطر بينه وبين نفسه، ويَحُول بينه وبين قلبه، فيذكِّره في الصلاة ما لم يكن يذكر قبل دخوله فيها، حتى ربما كان قد نسي الشيء والحاجة، وأَيِس منها، فَيُذَكِّره إياها في الصلاة؛ ليشغل قلبه بها، ويأخذه عن الله عز وجل، فيقوم فيها بلا قلب.",1,45,"/edition/42/section/9911#page-93",304,22],["لقد أسمع منادي الإيمان لو صادف آذانًا واعية، وَشَفَتْ مواعظُ القرآن لو وافقت قلوبًا من غَيِّها خالية، ولكن عَصَفَتْ على القلوب أهوية الشبهات والشهوات فأطفأت مصابيحها، وتمكنت منها أيدي الغفلة والجهالة فأغلقت أبواب رشدها، وأضاعت مفاتيحها، وران عليها كسبُها فلم ينفع فيها الكلام، وسَكِرَتْ بشهوات الغيِّ وشبهات الباطل فلم تُصْغِ بعده إلى الملام، وَوُعِظَتْ بمواعظ أنكى فيها من الأسِنَّة والسِّهام، ولكنْ ماتت في بحر الجهل والغفلة، وأَسْرِ الهوى والشهوة، و«ما لِجُرْحٍ بميِّتٍ إيلام».",1,127,"/edition/42/section/9972#page-175",289,22],["أصولُ الخطايا كلِّها ثلاثةٌ:\nالكبْرُ: وهو الذي أصار إبليسَ إلى ما أصارهُ، والحِرْصُ: وهو الذي أخرج آدم من الجنَّة، والحسدُ: وهو الذي جَرَّأ أحدَ ابنَي آدمَ على أخيهِ؛ فمنْ وُقِي شَرَّ هذه الثلاثة فقد وُقِيَ الشَّرَّ؛ فالكفرُ من الكِبر، والمعاصي من الحِرْص، والبَغْيُ والظُّلْمُ من الحسد.",2,80,"/edition/37/section/9203#page-87",2066,22],["أكمل الناس لذةً من جُمِع له بين لذَّة القلب والروح ولذة البدن؛ فهو يتناول لذَّاته المباحة على وجهٍ لا ينقُصُ حظّه من الدار الآخرة ولا يقطع عليه لذَّةَ المعرفة والمحبة والأنس بربِّه.",2,221,"/edition/37/section/9307#page-228",3616,22],["الصبر وإن كان شاقًّا كريهًا على النفوس فتحصيله ممكن، وهو يتركب من مفردين: العلم والعمل، فمنهما تُركب جميع الأدوية التي تُداوى بها القلوب والأبدان، فلا بدَّ من جزء علمي وجزء عملي، فمنهما يركب هذا الدواء الذي هو أنفع الأدوية.\nفأما الجزء العلمي فهو إدراك ما في المأمور من الخير والنفع واللذة والكمال، وإدراك ما في المحظور من الشرِّ والضرِّ والنقص، فإذا أدرك هذين العلمين كما ينبغي أضاف إليهما العزيمة الصادقة والهمَّة العالية والنّخوة والمروءة الإنسانية، وضم هذا الجزء إلى هذا الجزء.\nومتى فعل ذلك حصل له الصبر وهانت عليه مشاقُّه وحَلَت له مرارته وانقلب ألمه لذة.",5,53,"/edition/66/section/15991#page-276",1064,22],["أسماء المحبة\n\nالمَحَبَّة، والعلاقة، والهَوى، والصَّبْوة، والصَّبابة، والشَّغَف، والمِقَة، والْوَجْد، والكَلَف، والتَّتيُّم، والعِشق، والجَوى، والدَّنَف، والشَّجْو، والشَّوق، والخِلابة، والبلابل، والتَّباريح، والسَّدَمُ، والغَمَرَات، والوَهَل، والشَّجَن، واللاعِج، والاكتئاب، والوَصَب، والحُزْن، والكَمَد، واللَّذْع، والحُرَق، والسُّهْد، والأَرَق، واللَّهَف، والحَنين، والاستِكانة، والتَّبالة، واللَّوْعة، والفتُون، والجُنون، واللَّمَمُ، والخَبَلُ، والرَّسِيس، والدَّاء المُخامِر، والوُدّ، والخُلَّة، والخِلْمُ، والغَرَام، والهُيَام، والتَّدْلِيهُ، والوَلَهُ، والتعَبُّد.",9,16,"/edition/56/section/12508#page-13",1537,22],["وأما الهوى: فهو ميلُ النفس إلى الشيء، وأكثر ما يُستعمل في الحبّ المذموم، ويُقال: إنما سمي هوًى؛ لأنه يهوي بصاحبه. وقد يُستعمل في الحبِّ الممدُوح استعمالًا مقيَّدًا. ومنه قول النبي ﷺ: «لا يُؤْمِنُ أَحَدُكُم حَتَّى يَكُونَ هَوَاهُ تَبَعًا لِمَا جِئْتُ بِهِ».",9,37,"/edition/57/section/12557#page-63",529,22],["ولمَّا كان العبدُ له ثلاثة أحوال: حالةُ جهلٍ بما يَحِلُّ له ويحرمُ، وحالةُ تقصيرٍ وتفريط، وحالةُ ضعفٍ وقلَّة صبرٍ؛ قابل سبحانه جهل عبده بالبيان والهدى، وتقصيرَه وتفريطه بالتوبة، وضعفه وقلَّة صبره بالتَّخفيف.",9,203,"/edition/56/section/12523#page-199",13,22],["بالصبر واليقين تنال الإمامة في الدين، فبالصبر تنفى الشهوات، وباليقين تدفع الشبهات، فيصير قدوة للمؤمنين وإمامًا للمتقين، يقتدي أهل الإرادة بصبره، وأهل العلم بيقينه.\nفلواء الإمامة بيده، فإذا قصده جيش الشهوات ليدقوا اللواء اتقاه بالصبر، وإذا قصده جيش الشبهات دفعه باليقين.",10,372,"/edition/38/section/9691#page-432",9,22],["مِن الذاكرين مَن يبتدئ بذِكْر اللِّسان وإنْ كان على غفلة، ثم لا يزال فيه حتَّى يحضر قلبه فيتواطأ على الذِّكْر، ومنهم مَن لا يرَى ذلك ولا يَبتدئ على غفلة، بل يسكُن حتى يحضر قلبُه فيشرع في الذِّكر بقلبه، فإذا قوي استتبع لسانه فتواطأ جميعًا، فالأوَّل ينتقل الذِّكْر مِن لسانه إلى قلبه، والثاني ينتقل مِن قلبه إلى لسانه مِن غير أن يخلوَ قلبه منه، بل يسكُن أولاً حتى يُحِسَّ بظهور الناطِق فيه، فإذا أحسَّ بذلك نطَق قلبه، ثم انتقل النُّطق القلبي إلى الذِّكر اللِّساني، ثم يستغرِق في ذلك حتى يجدَ كل شيء منه ذاكرًا، وأفضل الذِّكر وأنفعه ما واطأ فيه القلبُ اللسانَ، وكان مِن الأذكار النبوية، وشهِد الذاكر معانيه ومقاصده.",2,278,"/edition/37/section/9366#page-285",160,22],["قال الله تعالى: {وَلَا تُطِعْ مَنْ أَغْفَلْنَا قَلْبَهُ عَنْ ذِكْرِنَا وَاتَّبَعَ هَوَاهُ وَكَانَ أَمْرُهُ فُرُطًا  (٢٨)} [الكهف: ٢٨].\n\nفإذا أراد العبد أن يقتدي برجل فلينظر: هل هو من أهل الذكر، أو هو من الغافلين؟ وهل الحاكم عليه الهوى أو الوحي؟؛ فإن كان الحاكم عليه هو الهوى، وهو من أهل الغفلة، وأمره فُرُطٌ = لم يَقْتَدِ به ولم يَتبعه؛ فإنه يقوده إلى الهلاك .\n\nومعنى الفُرُط قد فُسِّر بالتضييع ، أي: أمره الذي يجب أن يلزمه ويقوم به، وبه رشده وفلاحه ضائعٌ قد فَرَّطَ فيه.\nوفُسِّر بالإسراف ، أي: قد أفرط، وفُسِّر بِالهلاك . وفُسِّر بالخلاف للحق . وكلها أقوال متقاربة.\n\nوالمقصودُ أن الله سبحانه وتعالى نهى عن طاعةِ مَنْ جَمَع هذه الصفات، فينبغي للرجل أن ينظر في شيخه وقدوته ومتبوعه؛ فإن وجده كذلك فَلْيُبْعِدْ عنه، وإن وجده ممن غلب عليه ذكر الله تعالى واتباع السنة، وأمره غير مفروط عليه، بل هو حازم في أمره = فليتمسّك بِغَرْزِه.",1,92,"/edition/42/section/9936#page-140",161,22],["واعلم أنّ سوء الخاتمة - أعاذنا الله منها -\n\nلا تكون لمن استقام ظاهره ، وصلح باطنه ،\nما سمع بهذا ولا علم به ، ولله الحمد .\n\nوإنّما تكون لمن له :\n* فساد في العقيدة ،\n* أو إصرار على الكبائر ،\n* وإقدام على العظائم ،\n\nفربّما غلب ذلك عليه ، حتى ينزل به الموت قبل التوبة ، فيأخذه قبل إصلاح الطوِيّة ،\n\nويُصطلَم قبل الإنابة ،\nفيظفر به الشيطان عند تلك الصدمة ،\nويختطفه عند تلك الدهشة ،\nوالعياذ بالله .",0,391,"/edition/20/section/6497#page-457",2068,22],["والنزول أمر لازم للإنسان، ولكن من الناس من يكون نزوله إلى غفلة، فهذا متى استيقظ من غفلته عاد إلى درجته، أو إلى أرفع منها بحسب يقظته.\n\nومنهم من يكون نزوله إلى مباح لا ينوي به الاستعانة على الطاعة. فهذا متى رجع إلى الطاعة فقد يعود إلى درجته، وقد لا يصل إليها، وقد يرتفع عنها.\n\nومنهم من يكون نزوله إلى معصية: إما صغيرة أو كبيرة، فهذا يحتاج في عوده إلى درجته إلى توبة نصوح وإنابة صادقة.",0,206,"/edition/20/section/6431#page-272",6,21],["الغضب جمرةٌ في قلب ابن آدم، والشهوةَ نارٌ تثور من قلبه، وإنما تُطفأ النارُ بالماء والصلاة والذكر والتكبير.",0,241,"/edition/20/section/6444#page-307",2465,21],["قال بعض السلف:\nإذا أصبح العبدُ ابتدره الملَك والشيطانُ، فإن ذكر الله وكبَّره وحمِده وهلّله طرد الملكُ الشيطانَ وتولَّاه، وإن افتتح بغير ذلك ذهب الملك عنه، وتولَّاه الشيطان.",0,250,"/edition/20/section/6447#page-316",144,21],["ولا يجتمع الحد والتعزير في معصية، بل إن كان فيها حد اكتفيَ به، وإلا اكتفى بالتعزير.\nولا يجتمع الحد والكفارة في معصية، بل كل معصية فيها حد فلا كفارة فيها، وما فيه كفارة فلا حد فيه.",0,266,"/edition/20/section/6455#page-332",2,21],["واعلم أن ورود الخاطر لا يضرّ، وإنّما يضرّ استدعاؤه ومحادثته.\nفالخاطر كالمارّ على الطريق، فإنْ لم تستدعِه وتركتَه مرّ وانصرف عنك، وإن استدعيتَه سَحَرك بحديثه وخَدْعه وغروره.\nوهو أخفّ شيء على النفس الفارغة الباطلة، وأثقل شيء على القلب والنفس الشريفة السماوية المطمئنة.",0,360,"/edition/20/section/6493#page-426",48,21],["الظلم عند الله عز وجل يوم القيامة له دواوين ثلاثة:\nديوانٌ لا يغفر الله منه شيئًا، وهو الشِّرك به؛ فإن الله لا يغفر أن يُشْرَك به.\nوديوان لا يترك الله تعالى منه شيئًا، وهو ظلم العباد بعضهم بعضًا؛ فإن الله تعالى يستوفيه كله.\nوديوانٌ لا يعبأ الله به شيئًا، وهو ظلم العبد نفسه بينه وبين ربه عز وجل؛ فإن هذا الديوان أخف الدواوين وأسرعها محوًا، فإنه يُمْحى بالتوبة والاستغفار، والحسنات الماحية، والمصائب المكفرة، ونحو ذلك.\nبخلاف ديوان الشرك، فإنه لا يُمْحى إلا بالتوحيد.\nوديوانُ المظالم لا يُمْحى إلا بالخروج منها إلى أربابها، واستحلالهم منها.",1,40,"/edition/42/section/9908#page-88",3092,21],["إذا أصبحَ العبدُ وأمسَى وليس هَمُّه إلا الله وحده؛ تَحَمَّلَ اللهُ سبحانه حوائجَه كلَّها، وحَمَلَ عنه كلَّ ما أهمَّهُ، وفرَّغَ قلبَه لمحبَّتِه ولسانَه لذكرِه وجوارحَه لطاعتِه، وإن أصبح وأمسى والدُّنيا همُّهُ؛ حَمَّلهُ اللهُ همومَها وغُمومَها وأنكادَها، وَوَكَلَه إلى نفسه، فشَغَلَ قلبَه عن محبَّتِهِ بمحتَّةِ الخلق، ولسانَهُ عن ذكرِه بذكرهم، وجوارحَه عن طاعتِه بخدمتهم وأشغالهم؛ فهو يَكْدَحُ كَدْحَ الوحشِ في خدمة غيره؛ كالكِيرِ ينفُخ بطنَه ويَعصرُ أضالِعَه في نفعِ غيره.",2,121,"/edition/37/section/9232#page-128",1584,21],["اللَّه سبحانه جعل الصبر جوادًا لا يكبو، وصارما لا ينبو، وجندًا غالبًا لا يهزم، وحصنًا حصينًا لا يهدم ولا يثلم، فهو والنصر أخوان شقيقان، فالنصر مع الصبر، والفرج مع الكرب، واليسر مع العسر، وهو أنصر لصاحبه من الرجال، بلا عدة ولا عدد، ومحله من الظفر كمحل الرأس من الجسد.\nولقد ضمن الوفي الصادق لأهله في محكم كتابه أنه يوَفيهم أجرهم بغير حساب، وأخبر أنه معهم بهدايته ونصره العزيز وفتحه المبين، فقال: ﴿وَاصْبِرُوا إِنَّ اللَّهَ مَعَ الصَّابِرِينَ﴾ [الأنفال: ٤٦]؛ فذهب الصابرون بهذه المعية بخير الدنيا والآخرة، وفازوا بها بنعمه الباطنة والظاهرة.",5,11,"/edition/66/section/15965#page-4",2057,21],["الصبر ينقسم إلى قسمين: قسم مذموم، وقسم ممدوح.\nفالمذموم: الصبر عن اللَّه وإرادته ومحبته وسير القلب إليه، فإن هذا الصبر يتضمن تعطيل كمال العبد بالكلية وتفويت ما خُلِق له.\nوأما الصبر المحمود فنوعان: صبر للَّه وصبر باللَّه.",5,44,"/edition/66/section/15991#page-272",552,21],["من الدعاء ما هو واجب، وهو الدعاء بالتوبة والاستغفار من الذنوب، والهداية والعفو، وغيرها.",6,418,"/edition/49/section/12019#page-467",134,21],["وتأمل حكمة الرب تعالى في أمره إبراهيم خليله - ﷺ - بذبح ولده؛ لأن الله اتخذه خليلا، والخلة منزلة تقتضي إفراد الخليل بالمحبة، وأن لا يكون له فيها منازع أصلا، بل تخللت محبته جميع أجزاء القلب والروح فلم يبق فيها موضع خال من حبه، فضلا عن أن يكون محلا لمحبة غيره.\nفلما سأل إبراهيم الولد وأعطيه أخذ شعبة من قلبه كما يأخذ الولد شعبة من قلب والده، فغار المحبوب على خليله أن يكون في قلبه موضع لغيره، فأمره بذبح الولد ليخرج حبه من قلبه ويكون الله أحب إليه وآثر عنده، ولا يبقى في القلب سوى محبته، فوطن نفسه على ذلك وعزم عليه، فخلصت المحبة لوليها ومستحقها، فحصلت مصلحة المأمور به من العزم عليه وتوطين النفس على الامتثال، فبقي الذبح مفسدة؛ لحصول المصلحة بدونه، فنسخه في حقه لما صار مفسدة، وأمره به لما كان عزمه عليه وتوطين نفسه مصلحة لهما.",11,937,"/edition/73/section/18225#page-1037",560,21],["فإن إطلاق البصر يوجب استحكام الغفلة عن الله والدار الآخرة، ويوقع في سكرة العشق، كما قال الله تعالى عن عشاق الصور: (لعمرك إنهم لفي سكرتهم يعمهون).\n\nفالنظرة كأس من خمر، والعشق هو سكر ذلك الشراب، وسُكر العشق أعظم من سكر الخمر، فإن سكران الخمر يفيق وسكران العشق قلما يفيق إلا وهو في عسكر الأموات .",9,164,"/edition/57/section/12667#page-190",2049,21],["«المريض الذى يشكو وجع البطن مثلا اذا استعمل دواء ذلك الداء انتفع به، واذا استعمل دواء وجع الرأس لم يصادف داءه.\n\nفالشح المطاع مثلا من المهلكات، ولا يزيله صيام مائة عام، ولا قيام ليلها.\n\nوكذلك داء اتباع الهوى والاعجاب بالنفس لا يلائمه كثرة قراءة القرآن واستفراغ الوسع في العلم والذكر والزهد، وانما يزيله اخراجه من القلب بضده».",5,218,"/edition/67/section/16047#page-262",433,21],["العارف ابن وقته، فإن أضاعه ضاعت عليه مصالحه كلها، فجميع المصالح إنما تنشأ من الوقت، وإن ضيعه لم يستدركه أبدا..\n\nفوقت الإنسان هو عمره في الحقيقة، وهو مادة حياته الأبدية في النعيم المقيم، ومادة المعيشة الضنك في العذاب الأليم\n\nوهو يمر أسرع من السحاب، فما كان من وقته لله وبالله فهو حياته وعمره، وغير ذلك ليس محسوبا من حياته.",0,156,"/edition/19/section/6318#page-149",1088,21],["ولما كان البخيل محبوسًا عن الإحسان، ممنوعًا عن البِر والخير، كان جزاؤه من جنس عمله؛ فهو ضَيِّقُ الصدر، ممنوعٌ من الانشراح، ضَيِّق العَطَن، صغير النفس، قليل الفرح، كثير الهم والغم والحزن، لا يكاد تُقْضَى له حاجة، ولا يُعان على مطلوب.\n\nفهو كرجل عليه جبة من حديد، قد جُمِعت يداه إلى عنقه بحيث  لا يتمكن مِن  إخراجها ولا حركتها، وكلما أراد إخراجها، أو توسيع تلك الجبة لزمت كل حَلقة من حِلَقها موضعها.\n\nوهكذا البخيل كلما أراد أن يتصدق مَنَعَهُ البخل، فيبقى قلبه في سجنه كما هو، والمتصدقُ كلما تصدق بصدقة انشرح لها قلبه، وانفسح بها صدره، فهو بمنزلة اتساع تلك الجُبّة عليه، فكلما تصدق اتسع وانفسح وانشرح، وقَوِيَ فرحه، وعَظُمَ سروره.\n\nولو لم يكن في الصدقة إلا هذه الفائدة وحدها لكان العبد حقيقًا بالاستكثار منها والمبادرة إليها. وقد قال تعالى: {وَمَنْ يُوقَ شُحَّ نَفْسِهِ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ } .",1,74,"/edition/42/section/9928#page-122",1072,21],["الشيطان ليس له مدخلٌ على ابن آدم إلَّا من باب هواه، فإنَّه يطيف به، من أين يدخل عليه، حتَّى يفسد عليه قلبَه وأعماله، فلا يجد مدخلًا  إلَّا من باب الهوى، فيسري معه سرَيان السُّمِّ في الأعضاء.",9,635,"/edition/57/section/12901#page-661",49,21],["اعلم أنّ ورود الخاطر  لا يضرّ، وإنّما يضرّ استدعاؤه ومحادثته. فالخاطر  كالمارّ على الطريق، فإنْ لم تستدعِه وتركتَه مرّ وانصرف عنك ، وإن استدعيتَه سَحَرك بحديثه وخَدْعه وغروره. وهو أخفّ شيء على النفس الفارغة الباطلة، وأثقل شيء على القلب والنفس الشريفة السماوية المطمئنة.",0,360,"/edition/20/section/6493#page-426",48,21],["الطَّبيب إذا كان عارفًا بأمراض القلب والرُّوح وعلاجها كان هو الطَّبيب الكامل.\nوالَّذي لا خبرة له بذلك، وإن كان حاذقًا في علاج الطَّبيعة وأحوال البدن، نصفُ طبيبٍ.\n\n وكلُّ طبيب لا يداوي العليل بتفقُّد قلبه وصلاحه وتقوية أرواحه وقواه بالصَّدقة وفعل الخير والإحسان والإقبال على الله والدَّار الآخرة، فليس بطبيبٍ، بل متطبِّبٌ قاصرٌ.\n\n ومن أعظم علاجات المرض : فعلُ الخير والإحسان والذِّكر والدُّعاء والتَّضرُّع والابتهال إلى اللَّه والتَّوبة.\nولهذه الأمور تأثيرٌ في دفع العلل وحصول الشِّفاء أعظَمُ من الأدوية الطَّبيعيَّة، ولكن بحسب استعداد النَّفس وقبولها وعقيدتها في ذلك ونفعه.",14,206,"/edition/59/section/14817#page-2457",2228,21],["إذا كان العبد مسؤولًا ومحاسبًا على كل شيء، حتى على سمعه وبصره وقلبه، كما قال تعالى: ﴿إِنَّ السَّمْعَ وَالْبَصَرَ وَالْفُؤَادَ كُلُّ أُولَئِكَ كَانَ عَنْهُ مَسْئُولًا﴾ [الإسراء: ٣٦]، فهو حقيق أن يحاسب نفسه قبل أن يُناقش الحساب.",7,142,"/edition/13/section/4207#page-183",49,21],["الله خلق خلقَه قسمين: عِلية وسِفلة، وجعل علّيين مستقرّ العلية، وأسفل سافلين مستقرّ السفلة. وجعل أهل طاعته الأعلَين في الدنيا والآخرة، وأهل معصيته الأسفلِين في الدنيا والآخرة، كما جعل أهل طاعته أكرمَ خلقه عليه، وأهلَ معصيته أهونَ خلقه عليه، وجعل العزّة لهؤلاء، والذلّة والصغار لهؤلاء.",0,205,"/edition/20/section/6431#page-271",2050,20],["الطاعة تُنوِّر القلب، وتجلوه وتصقُله، وتقوّيه وتثبته، حتى يصير كالمرآة المجلوّة في جلائها وصفائها ويمتلئ نورًا؛ فإذا دنا الشيطان منه أصابه من نوره ما يصيب مُسْتَرِقي السَّمْع من الشهب الثواقب.\nفالشيطان يفرَق من هذا القلب أشدَّ من فرَقِ الذئب من الأسد.",0,222,"/edition/20/section/6436#page-288",48,20],["قال بعض السلف:\nالبدعة أحبُّ إلى إبليس من المعصية؛ لأن المعصية يتاب منها، والبدعة لا يتاب منها.",0,331,"/edition/20/section/6487#page-397",18,20],["كان شجاع الكرماني يقول:\nمن عمر ظاهرَه باتباع السنة، وباطنَه بدوام المراقبة؛ وغضّ بصرَه عن المحارم، وكفّ نفسه عن الشهوات، واغتذى بالحلال = لم تخطئ فراسته.\nوكان شجاع هذا لا تخطئ له فراسة.",0,417,"/edition/20/section/6506#page-483",17,20],["قراءةُ القرآن أفضلُ من الذِّكْر، والذِّكْرُ أفضلُ من الدعاء، هذا مِنْ حيث النظر إلى كُلٍّ منهما مُجَرَّدًا.\nوقد يَعْرِضُ للمفضول ما يجعله أولى من الفاضل، بل يُعَيِّنُه، فلا يجوز أَنْ يُعْدَلَ عنه إلى الفاضل.",1,231,"/edition/42/section/10018#page-279",385,20],["العبد إذا شرع في قول أو عمل؛ يبتغي به مرضاة الله، مطالعًا فيه منَّةَ الله عليه به وتوفيقَه له فيه، وأنه بالله لا بنفسه ولا بمعرفته وفكره وحوله وقوَّته، بل هو بالذي أنشأ له اللسانَ والقلب والعين والأذن، فالذي منَّ عليه بذلك هو الذي مَنَّ عليه بالقول والفعل؛ فإذا لم يَغِبْ ذلك عن ملاحظته ونظر قلبه لم يَحضُره العُجْبُ الذي أصلُهُ رؤيةُ نفسه وغيَبتُهُ عن شهود مِنَّة ربِّه وتوفيقه وإعانته.",2,224,"/edition/37/section/9309#page-231",48,20],["طالبُ النفوذ إلى كل علم يحتاج أن يكون شجاعًا، مِقدامًا، حاكمًا على وهمه، غيرَ مقهور تحت سلطان تخيُّله، زاهدًا في كل ما سوى مطلوبه، عاشقًا لما توجه إليه، عارفًا بطريق الوصول إليه والطرق القواطع عنه، مِقدامَ الهمة، ثابت الجأش، لا يَثنيِه عن مطلوبه لومُ لائم ولا عذلُ عاذل، كثير السكون، دائم الفكر، غير مائل مع لذة المدح ولا ألم الذم، قائمًا بما يحتاج إليه من أسباب معونته، لا تَستفِزُّه المعارضات، شعارُه الصبر، وراحته التعب، محبًّا لمكارم الأخلاق، حافظًا لوقته، لا يخالط الناس إلا على حذر كالطائر الذي يلتقط الحبَّ بينهم، قائمًا على نفسه بالرغبة والرهبة، طامعًا في نتائج الاختصاص على بني جنسه، غيرَ مرسلٍ شيئًا من حواسِّه عبثًا، ولا مُسرِّحًا خواطره في مراتب الكون.",2,278,"/edition/37/section/9366#page-285",1560,20],["يُقال: صبَر إذا أتى بالصبر، وتصبَّر إذا تكلَّفه واستدعاه، واصطبر إذا اكتسبه وتعلمه، وصابر إذا واقف خصمَه في مقام الصبر، وصبَّر نفسَه وغيرَه -بالتشديد- إذا حَملها على الصبر.",5,18,"/edition/67/section/16018#page-62",24,20],["نجاسة الفواحش والمعاصي في القلب بمنزلة الأخلاط الرديئة في البدن، وبمنزلة الدَّغَل في الزرع، وبمنزلة الخَبَث في الذهب والفضة والنحاس والحديد.",7,46,"/edition/12/section/4095#page-47",1059,20],["وهذا الكتاب يَصلُح لسائر طبقات الناس، فإنه يَصلُح عونًا على الدِّين وعلى الدُّنيا، ومرقاةً للذة العاجلة ولذة العُقْبى، وفيه من ذكر أقسام المحبَّة، وأحكامها ومتعلقاتها، وصحيحها وفاسدها، وآفاتها وغوائلها، وأسبابها وموانعها، وما يُناسب ذلك من نُكَتٍ تفسيرية، وأحاديثَ نبوية، ومسائلَ فقهية، وآثارٍ سَلَفية، وشواهدَ شعرية، ووقائعَ كونية، ما  يكونُ مُمْتِعًا لقارئه، مُرَوِّحًا للناظرِ فيه، فإن شاءَ أوسَعَه جِدًّا، وأعطاه ترغيبًا وترهيبًا، وإن شاءَ أخذَ من هزله ومُلَحه نصيبًا، فتارةً يُضحِكُه، وتارةً يُبكيه، وطورًا يُبعِدُه من أسباب اللذة الفانية، وطورًا يُرغّبه فيها ويُدنيه.\nفإنْ شئتَ وجدته واعظًا ناصحًا، وإن شئت وجدتَه بنصيبك من اللذة والشهوة ووَصْلِ الحبيب مُسامحًا.",9,24,"/edition/57/section/12551#page-50",1537,20],["وكثيرٌ من الناس يرى محبوبَه فيَصفرُّ ويَرتعِدُ.\nقيل: هذا مما خفي سببه على أكثر المحبِّين، فلا يدرون ما سببه، فقيل: سببُه أنَّ للجمالِ سلطانًا على القلوب، وإذا بدا راعَ القلوبَ بسلطانه، كما يَرُوعُها الملِكُ ونحوهُ مِمَّن له سلطانٌ على الأبدان، فسلطانُ الجمال والمحبَّة على القلوب، وسلطانُ الملوك على الأبدان، فإذا كان السلطانُ الذي على الأبدان يَرُوع إذا بدا؛ فكيف بالسلطان الذي هو أعظم منه؟!\nقالوا: وأيضًا فإنَّ الجمالَ يأْسِرُ القلبَ فيُحِسّ القلبُ بأنه أسيرٌ ولا بُدَّ لتلك الصورة التي بَدتْ له فيرتاع، كما يرتاع الرجلُ إذا أحسَّ بمن يأْسِرُه، ولهذا إذا أمن الناظرُ من ذلك لم تَحْصُل له هذه الرَّوعة.",9,57,"/edition/57/section/12576#page-83",545,20],["ذكر الله سبحانه عقوبة اللوطية، وما حل بهم من البلاء في عشر سور من القرآن وهي: سورة الأعراف، وهود، والحجر، والأنبياء، والفرقان، والشعراء، والنمل، والعنكبوت، والصافات، واقتربت الساعة. وجمع على القوم بين عمى الأبصار، وخسف الديار، والقذف بالأحجار، ودخول النار. وقال محذرا لمن عمل عملهم مما حل بهم من العذاب الشديد: ﴿وما قوم لوط منكم ببعيد﴾ [هود/ ٨٩].",9,510,"/edition/57/section/12856#page-536",2497,20],["والتوبة والاعتراف هي الغاية المطلوبة من العباد، ولابد لكل عبد منها، وتوبة كل عبد بحسبه، فحسنات الأبرار سيئات المقربين، والله يحب التوابين ويحب المتطهرين، والاعتبار بكمال النهاية لا بنقص البداية، فكيف بين حال آدم بعد التوبة وحاله قبل الخطيئة!",10,360,"/edition/38/section/9686#page-420",6,20],["إذا كان الدعاء في نفسه غير صالح، أو الداعي لم يجمع بين قلبه ولسانه في الدعاء، أو كان ثَمَّ مانع من الإجابة، لم يحصل الأثر.",0,26,"/edition/20/section/6372#page-92",176,19],["عن محمَّد بن سيرين:\nأنه لما ركبه الدَّينُ اغتم لذلك، فقال: إني لأعرفُ هذا الغمَّ بذنب أصبتُه منذ أربعين سنة!\n\nوها هنا نكتة دقيقة يغلط فيها الناس في أمر الذنب، وهي أنهم لا يرون تأثيرَه في الحال، وقد يتأخر تأثيره فيُنسَى، ويظن العبد أنه لا يغبِّر بعد ذلك، وأن الأمر كما قال القائل:\nإذا لم يغبِّرْ حائطٌ في وقوعه\nفليس له بعد الوقوع غبارُ",0,130,"/edition/20/section/6395#page-196",1026,19],["وليس على القلب أمَرُّ من وحشة الذنب على الذنب، فالله المستعان.",0,134,"/edition/20/section/6398#page-200",34,19],["قد أجمع السائرون إلى الله:\nأن القلوب لا تعطَى مُناها حتى تصل إلى مولاها،\nولا تصل إلى مولاها حتى تكون صحيحة سليمة،\nولا تكون صحيحة سليمة حتى ينقلب داؤها فيصير نفس دوائها.\nولا يصح لها ذلك إلا بمخالفة هواها، فهواها مرضها، وشفاؤها مخالفته.",0,184,"/edition/20/section/6422#page-250",33,19],["فالعاصي يدس نفسه في المعصية، ويخفي مكانها، ويتوارى من الخلق من سوء ما يأتي به، قد انقمع عند نفسه، وانقمع عند الله، وانقمع عند الخلق.",0,189,"/edition/20/section/6424#page-255",18,19],["ولا سجنَ أضيقُ من سجن الهوى،\nولا قيدَ أصعبُ من قيد الشهوة.",0,190,"/edition/20/section/6425#page-256",1025,19],["وليست سعةُ الرزق والعمل بكثرته، ولا طولُ العمر بكثرة الشهور والأعوام، ولكن سعة الرزق والعمر بالبركة فيه.",0,201,"/edition/20/section/6430#page-267",65,19],["وإنما كانت معصيةُ الله سببًا لمحق بركة الرزق والأجل؛ لأنّ الشيطان موكَّل بها وبأصحابها، فسلطانُه عليهم، وحوالتُه على هذا الديوان، وأهلُه أصحابُه؛ وكل شيء يتصل به الشيطان ويقارنه، فبركته ممحوقة.",0,202,"/edition/20/section/6430#page-268",18,19],["لما كانت البدع المضِلّة جهلًا بصفات الله وتكذيبًا بما أخبر به عن نفسه وأخبر به عنه رسوله عنادًا وجهلًا كانت من أكبر الكبائر -إن قصرت عن الكفر- وكانت أحبَّ إلى إبليس من كبار الذنوب.",0,331,"/edition/20/section/6487#page-397",18,19],["والله سبحانه يجزي العبد على عمله بما هو من جنس عمله،\nومن ترك لله شيئًا عوّضه الله خيرًا منه،\nفإذا غضّ بصره عن محارم الله عوّضه الله بأن يُطلِق نورَ بصيرته عوضًا عن حبسِه بصرَه لله،\nويفتحَ عليه باب العلم والإيمان والمعرفة والفراسة الصادقة المصيبة التي إنّما تُنال ببصيرة القلب.",0,417,"/edition/20/section/6506#page-483",33,19],["إن القلب إذا خلَص وأخلص عملَه لله لم يتمكن منه عشق الصور، فإنه إنما يتمكن من قلب فارغ.",0,491,"/edition/20/section/6536#page-557",33,19],["إذا امتلأ القلبُ بالشُّغْل بالمخلوق والعلوم التي لا تنفعُ؛ لم يبق فيها موضعٌ للشُّغل بالله ومعرفة أسمائِهِ وصفاتِهِ وأحكامِه.\nوسرُّ ذلك أنَّ إصغاء القلب كإصغاءِ الأُذُنِ: فإذا صَغا إلى غير حديث الله؛ لم يبْقَ فيه إصغاءٌ ولا فهمٌ لحديثِهِ، كما إذا مال إلى غير محبَّة الله؛ لم يبقَ فيه ميلٌ إلى محبَّتِهِ، فإذا نطق القلبُ بغير ذِكرِهِ؛ لم يَبْقَ فيه محلٌّ للنُّطقِ بذكرِهِ كاللسان.",2,42,"/edition/37/section/9174#page-49",544,19],["الإنابة: هي عكوف القلب على الله عز وجل كاعتكاف البدن في المسجد لا يُفارِقه.\nوحقيقة ذلك عكوف القلب على محبته، وذِكْره بالإجلال والتعظيم، وعكوف الجوارح على طاعته بالإخلاص له والمتابعة لرسوله.",2,284,"/edition/37/section/9373#page-291",548,19],["ساحة العافية أوسع للعبد من ساحة الصبر، كما قال النبي ﷺ في الدعاء المشهور: «إن لم يكن بك غَضَبٌ عليَّ فلا أبالي، غير أن عافيتَك أوسعُ لي»، ولا يناقض هذا قولَه ﷺ: «وما أُعطِي أحدٌ عطاءً خيرًا وأوسعَ من الصّبرِ»؛ فإن هذا بعد نزول البلاء ليس للعبد أوسع من الصبر، وأما قبله فالعافية أوسع له منه.",5,22,"/edition/67/section/16019#page-66",136,19],["العبد إذا كان باللَّه هان عليه كل شيء، ويتحمل الأثقال ولم يجد لها ثقلًا، فإنه إذا كان باللَّه لا بالخلق ولا بنفسه، كان لقلبه وروحه وجود آخر وشأن آخر غير شأنه إذا كان بنفسه وبالخلق، وفي هذه الحال لا يجد عناء الصبر ولا مرارته، وتنقلب مشاق التكليف له نعيمًا وقرة عين.",5,91,"/edition/67/section/16029#page-135",56,19],["لمَّا علم عدو الله إبليس أن المدار على القلب والاعتماد عليه؛ أجلبَ عليه بالوساوس، وأقبل بوجوه الشهوات إليه، وزيَّن له من الأحوال والأعمال ما يصدُّه به عن الطريق، وأمدَّه من أسباب الغَيّ بما يقطعه عن أسباب التوفيق، ونصبَ له من المصايد والحبائل ما إن سَلِم من الوقوع فيها لم يَسلَمْ من أن يحصل له بها التعويق، فلا نجاة من مصايده ومكايده إلا بدوام الاستعانة بالله تعالى، والتعرُّضِ لأسباب مرضاته، والْتِجَاءِ القلب إليه وإقباله عليه في حركاته وسكناته، والتحقُّق بِذُلِّ العبودية الذي هو أولى ما تلبَّس به الإنسان ليحصل له الدخول في ضمانِ ﴿إِنَّ عِبَادِي لَيْسَ لَكَ عَلَيْهِمْ سُلْطَانٌ﴾.",7,7,"/edition/13/section/4109#page-48",561,19],["من أصغى إلى كلام الله بقلبه، وتدبره وتفهمه، أغناه عن السماع الشيطاني الذي يصد عن ذكر الله وعن الصلاة، وينبت النفاق في القلب.",7,214,"/edition/12/section/4100#page-217",432,19],["السماع الشيطاني المضادّ للسماع الرحماني له في الشرع بضعة عشر اسمًا:\nاللهو، واللغو، والباطل، والزور، والمُكاء، والتصدية، ورُقية الزنى، وقرآن الشيطان، ومُنبت النفاق في القلب، والصوتُ الأحمق، والصوت الفاجر، وصوتُ الشيطان، ومزمور الشيطان، والسمودُ.",7,419,"/edition/13/section/4346#page-460",48,19],["قال بعض أهل العلم: إذا اتَّصف القلب بالمكر والخديعة والفسق، وانصبغ بذلك صبغةً تامةً، صار صاحبه على خُلُق الحيوان الموصوف بذلك من القردة والخنازير وغيرهما، ثم لا يزال يتزايد ذلك الوصف فيه، حتى يبدو على صفحات وجهه بُدُوًّا خفيًّا، ثم يقوَى ويتزايد، حتى يصير ظاهرًا على الوجه، ثم يقوى حتى يَقلِبَ الصورة الظاهرة كما قلب الهيئة الباطنة، ومَنْ له فراسة تامة يرى على صور الناس مسخًا من صور الحيوانات التي تخلَّقوا بأخلاقها في الباطن، فقلّ أن ترى مُختالًا مكارًا مخادعًا خَتَّارًا إلا وعلى وجهه مِسْخة قرد، وقلَّ أن ترى رافضيًّا إلا وعلى وجهه مِسخة خنزير، وقلَّ أن ترى شَرِهًا نَهِمًا نفسه نفسٌ كَلْبِيَّةٌ إلا وعلى وجهه مِسخة كلب. فالظاهر مرتبط بالباطن أتمَّ ارتباطٍ، فإذا استحكمت الصفات المذمومة في النفس قويت على قلب الصورة الظاهرة.",7,471,"/edition/13/section/4374#page-512",49,19],["الفتنة بعشق الصور تنافي أن يكون دين العبد كلُّه لله، بل ينقص من كون دينه لله بحسب ما حصل له من فتنة العشق، وربما أخرجت صاحبه من أن يبقى معه شيء من الدين لله.",7,890,"/edition/13/section/4746#page-931",1,19],["إذا كانت اللذة مطلوبة لنفسها فهي إنما تذم؛ إذا أعقبت ألما أعظم منها، أو منعت لذة خيرا منها، وتحمد؛ إذا أعانت على اللذة الدائمة المستقرة، وهي لذة الدار الآخرة ونعيمها؛ الذي هو أفضل نعيم وأجله.",9,235,"/edition/57/section/12700#page-261",3088,19],["وأعظم الناس اعترافا واستغفارا أعرفهم بربه وبنفسه، ولهذا كان أعظم الأمة استغفارا نبيها، فكانت الصحابة يعدون له في المجلس الواحد مائة مرة يقول: «رب اغفر لي وتب علي، إنك أنت التواب الغفور»، وقال: «يا أيها الناس، توبوا إلى ربكم، فإني لأتوب إليه في اليوم أكثر من سبعين مرة».",10,360,"/edition/38/section/9686#page-420",20,19],["لا شيء أنفع للقلب من قراءة القرآن بالتدبر والتفكر؛ فإنه جامع لجميع منازل السائرين، وأحوال العاملين، ومقامات العارفين، وهو الذي يورث المحبة والشوق والخوف والرجاء والإنابة والتوكل والرضا والتفويض والشكر والصبر وسائر الأحوال التي بها حياة القلب وكماله، وكذلك يزجر عن جميع الصفات والأفعال المذمومة التي بها فساد القلب وهلاكه.",11,535,"/edition/73/section/18081#page-635",812,19],["وقد أجمع عقلاء كل أمة على أن النعيم لا يدرك بالنعيم، وأن من آثر الراحة فاتته الراحة، وأن بحسب ركوب الأهوال واحتمال المشاق تكون الفرحة والملذة؛ فلا فرحة لمن لا هم له، ولا لذة لمن لا صبر له، ولا نعيم لمن لا شقاء له، ولا راحة لمن لا تعب له، بل إذا تعب العبد قليلا استراح طويلا، وإذا تحمل مشقة الصبر ساعة قاده لحياة الأبد، وكل ما فيه أهل النعيم المقيم فهو ثمرة صبر ساعة، والله المستعان، ولا قوة إلا بالله.",11,15,"/edition/72/section/17873#page-317",1032,19],["الْمصَالح والخيرات وَاللَّذَّات والكمالات كلهَا لَا تنَال إِلَّا بحظ من الْمَشَقَّة، وَلَا يعبر إِلَيْهَا إِلَّا على جسر من التَّعَب، وقد أجمع عقلاء كل أمة على أن النعيم لا يدرك بالنعيم وإن من آثر الراحة فاتته الراحة وإن بحسب ركوب الأهوال وإحتمال المشاق تكون الفرحة واللذة فلا فرحة لمن لا هم له ولا لذة لمن لا صبر له ولا نعيم لمن لا شقاء له ولا راحة لمن لا تعب له بل إذا تعب العبد قليلا استراح طويلا وإذا تحمل مشقة الصبر ساعة قاده لحياة الأبد وكل ما فيه أهل النعيم المقيم فهو صبر ساعة والله المستعان ولا قوة إلا بالله .",11,895,"/edition/73/section/18215#page-995",1032,19],["إطلاق البصر وإرساله لا يحصل إلا من خفة العقل وطيشه وعدم ملاحظته للعواقب، فإن خاصة العقل ملاحظة العواقب ومرسل النظر لو علم ما تجني عواقب نظره عليه لما أطلق بصره.",9,164,"/edition/57/section/12667#page-190",1,19],["إن كان المسموع معنًى شريفًا بصوتٍ لذيذٍ= حصل للقلب حظُّه ونصيبُه من إدراك المعنى، وابتهجَ به أتمَّ ابتهاجٍ على حسب إدراكه له. وللرُّوح حظُّها ونصيبُها من لذّة الصّوت  ونغمتِه وحسنِه، فابتهجتْ به، فتتضاعف اللّذّة، ويتمُّ الابتهاج، ويحصل الارتياح، حتّى ربّما فاض على البدن والجوارح وعلى الجليس.\nوهذا لا يحصل على الكمال في هذا العالم ولا يحصل إلّا عند سماع كلام الله. فإذا تجرّدت الرُّوح، وكانت مستعدّةً، وباشر القلب روح المعنى، وأقبلَ بكلِّيّته على المسموع، فألقى السّمعَ وهو شهيدٌ، وساعده طيب صوت القارئ= كاد القلب يفارقُ هذا العالمَ، ويَلِجُ عالمًا آخر، ويجد له لذّةً وحالًا لا يعهدها في شيءٍ البتّةَ. وذلك رقيقةٌ  من حالِ أهل الجنّة في الجنّة. فيا له من غذاءٍ ما أصلَحَه وما أنفَعَه!",13,191,"/edition/71/section/17288#page-1578",3104,19],["«العبد لا يزال يرتكب الذنب، حتى يهون عليه، ويصغر في قلبه. وذلك علامة الهلاك، فإن الذنب كلما صغر في عين العبد عظم عند الله.\n\n- وقد ذكر البخاري في صحيحه عن ابن مسعود قال: إن المؤمن يرى ذنوبه كأنه في أصل جبل يخاف أن يقع عليه. وإن الفاجر يرى ذنوبه كذباب وقع على أنفه، فقال به هكذا، فطار».",0,58,"/edition/19/section/6256#page-51",34,19],["اشتدَّ نهي النبي - صلى الله عليه وسلم - للمصلِّي أن يَرفع بصره إلى السماء، وتوعَّدهم على ذلك بخطف أبصارهم؛ إذ هذا من كمال الأدب مع مَنِ المصلي واقفٌ بين يديه، بل ينبغي له أن يقف ناكس الرَّأس، مطرقًا إلى الأرض، ولولا أن رب العالمين سبحانه فوق سمواته على عرشه؛ لم يكن فرقٌ بين النظر إلى فوق أو إلى أسفل.",9,371,"/edition/57/section/12774#page-397",1,19],["للمعاصي أعظم تأثير في محق بركة العمر والرزق والعلم والعمل.\n\nفكلُّ وقتٍ عصيتَ الله فيه، أو مالٍ عُصِيَ اللهُ به، أو بدنٍ، أو جاهٍ، أو علمٍ، أو عملٍ، فهو على صاحبه، ليس له.\n\nفليس عمرُه وماله وقوته وجاهه وعلمه وعمله إلا ما أطاع اللهَ به.\n\nولهذا من الناس من يعيش في هذه الدار مائة سنة أو نحوها، ويكون عمره لا يبلغ عشر سنين أو نحوها؛ كما أنّ منهم من يملك القناطير المقنطرة من الذهب والفضة، ويكون ماله في الحقيقة لا يبلغ ألف درهم أو نحوها. وهكذا الجاه والعلم.",0,85,"/edition/19/section/6282#page-78",1088,19],["ليس كلُّ من تَحلَّى بالمعرفة والحكمة وانتحلها كان من أهلها، بل أهلُ المعرفة والحكمة الذين أَحيَوا قلوبَهم بقتل الهوى، وأما من قتل قلبه فأحيا الهوى؛ فالمعرفة والحكمة عاريَّةٌ على لسانه.",2,143,"/edition/37/section/9249#page-150",33,19],["لو عطَّل المحسن الطاعة لضاقت عليه نفسه، وضاقت عليه الأرض بما رحبت، وأحس من نفسه بأنه كالحوت إذا فارق الماء، حتى يعاودها، فتسكن نفسه، وتقر عينه.",0,139,"/edition/20/section/6401#page-205",16,18],["ففي رضا الله قرة العيون،\nوسرور النفوس، وحياة القلوب، ولذة الأرواح، وطيب الحياة، ولذة العيش، وأطيب النعيم، مما لو وُزِن منه مثقالُ ذرة بنعيم الدنيا لم يف به، بل إذا حصل للقلب من ذلك أيسر نصيب لم يرضَ بالدنيا وما فيها عوضًا منه.",0,196,"/edition/20/section/6429#page-262",1056,18],["قال بعض السلف:\nرأيتُ العبد مُلقًى بين الله سبحانه وبيّن الشيطان، فإن أعرض الله عنه تولّاه الشيطان، وإن تولّاه الله لم يقدر عليه الشيطان.",0,197,"/edition/20/section/6429#page-263",16,18],["كان بعض السلف يقول في خطبته:\nألا رُبّ مهينٍ لنفسه وهو يزعم أنه لها مكرم، ومُذِلٍّ لنفسه وهو يزعم أنه لها مُعِزّ، ومصغّرٍ لنفسه وهو يزعم أنه لها مكبّر، ومضيّعٍ لنفسه وهو يزعم أنه مراع لحقّها.",0,243,"/edition/20/section/6445#page-309",16,18],["إنما الكمال في امتلاء القلب والسرّ من الخواطر والإرادات والفِكَر في تحصيل مراضي الربّ تعالى من العبد ومن الناس، والفكر في طرُق ذلك والتوصّل إليه.\nفأكمل الناس أكثرهم خواطر وفِكَرًا صارادات لذلك، كما أنّ أنقصَ الناس أكثرُهم خواطر وفِكَرًا وإراداتٍ لحظوظه وهواه أين كانت.",0,362,"/edition/20/section/6493#page-428",49,18],["أعظمُ نعيم الآخرة ولذاتها: النظرُ إلى وجه الرب ﷻ، وسماعُ كلامه منه، والقربُ منه؛ كما ثبت في الصحيح في حديث الرؤية: «فو الله ما أعطاهم شيئًا أحب إليهم من النظر إليه».",0,542,"/edition/20/section/6545#page-608",2049,18],["أطيب ما في الدنيا معرفة الله ومحبتُه، وأنشد ما في الجنة رؤيتُه ومشاهدتُه.\nفمحبتُه ومعرفتُه قرة العيون، ولذة الأرواح، وبهجة القلوب، ونعيم الدنيا وسرورها.",0,543,"/edition/20/section/6546#page-609",3616,18],["القلب كلما اشتدت به الغفلة اشتدت به القسوة، فإذا ذكر الله تعالى ذابت تلك القسوة كما يذوب الرصاص في النار، فما أُذيبت قسوة القلوب بمثل ذكر الله عز وجل.",1,171,"/edition/42/section/9985#page-219",2208,18],["فعينُ اليقين نوعان:\nنوعٌ في الدُّنيا، ونوعٌ في الآخرة.\nفالحاصلُ في الدُّنيا نسبتُه إلى القلب كنسبةِ الشاهد إلى العين.\nوما أخبرتْ به الرسلُ من الغيب يُعايَنُ في الآخرة بالأبصار وفي الدنيا بالبصائر؛ فهو عينُ يقينٍ في المرتبتين.",2,5,"/edition/37/section/9135#page-12",2081,18],["من ترك المجاهدة بالكلية ضعف فيه باعث الدين وقوي فيه باعث الشهوة، ومن عوّد نفسه مخالفة الهوى غلبه متى أراد.",5,106,"/edition/67/section/16033#page-150",17,18],["القرآن مادة الهدى والعلم والخير في القلب، كما أن الماء مادة النبات، والشيطان نارٌ يحرق النبات أولًا فأولًا، فكلما أحسَّ بنبات الخير في القلب سعى في إفساده وإحراقه، فأُمر [العبد] أن يستعيذ بالله منه؛ لئلا يُفسِد عليه ما يحصل له بالقرآن.",7,158,"/edition/13/section/4214#page-199",304,18],["النفوس ثلاثة: نفس مطمئنة إلى ربها، وهي أشرف النفوس وأزكاها، ونفس مجاهدة صابرة، ونفس مفتونة بالشهوات والهوى، وهي النفس الشقية، التي حظها الألم والعذاب، والبعد عن الله تعالى والحجاب.",7,950,"/edition/13/section/4910#page-991",17,18],["في لذة ذكر الله، والإقبال عليه، والصلاة بالقلب والبدن من المنفعة الشريفة العظيمة، السالمة عن المفاسد الدافعة للمضار: غنى وعوض للإنسان\nــ الذي هو إنسان ــ عن تلك اللذة الناقصة القاصرة المانعة لما هو أكمل منها، الجالبة لألم أعظم منها.",9,230,"/edition/57/section/12695#page-256",1440,18],["يا خاطب الحُور الحسان وطالبًا ... لوصالهنَّ بجنَّة الحيوان\nلو كنت تدري من خطبت ومن طلبـ ... ـت بذلتَ ما تحوي من الأثمان\nأو كنت تدري أين مسكنها جعلـ ... ـت السَّعي منك لها على الأجفان\nأسرِعْ وحُثَّ السَّير جُهدك إنما ... مسراك هذا ساعةٌ لزمان\nفاعشق وحدّثْ بالوصال النفس وابْـ ... ذُلْ مهرَها ما دُمْت ذا إمكان\nواجعل صيامك دون لقياها ويو ... م الوَصْل يوم الفطر من رمضان\nواجعل نعوت جمالها الحادي وسِرْ ... نحو الحبيب ولست بالمُتواني",9,360,"/edition/57/section/12764#page-386",531,18],["أصل كل معصية إنما يحدث من جانب الفكرة؛ فإن الشيطان يصادف أرض القلب خالية فارغة، فيبذر فيها حب الأفكار الردية، فيتولد منه الإرادات والعزوم، فيتولد منها العمل. فإذا صادف أرض القلب مشغولة ببذر الأفكار النافعة فيما خلق له وفيما أمر به وفيما هياء له وأعد له من النعيم المقيم أو العذاب الأليم لم يجد لبذره موضعا.",11,527,"/edition/73/section/18079#page-627",1074,18],["الله سبحانه إذا أراد بعبده خيرا أنساه رؤية طاعاته، ورفعها من قلبه ولسانه، فإذا ابتلي بالذنب جعله نصب عينيه، ونسي طاعاته، وجعل همه كله بذنبه، فلا يزال ذنبه أمامه إن قام أو قعد أو غدا أو راح، فيكون هذا عين الرحمة في حقه.",11,842,"/edition/73/section/18202#page-942",34,18],["• اتِّباعُ الهوى وطولُ الأمل مادةُ كلِّ فسادٍ؛ فإنَّ اتِّباعَ الهوى يُعمِي عن الحقِّ معرفةً وقصدًا، وطول الأمل يُنسِي الآخرةَ ويصُدُّ عن الاستعداد لها.",2,99,"/edition/36/section/9046#page-95",2049,18],["من اشتغل بالله عن نفسه كفاهُ الله مؤونَة نفسِه، ومن اشتغل بالله عن الناس كفاه الله مؤونةَ الناس، ومن اشتغل بنفسه عن الله وَكَلهُ الله إلى نفسه، ومن اشتغل بالناس عن الله وَكَلهُ الله إليهم.",2,156,"/edition/37/section/9260#page-163",16,18],["المعونة من الله تَنزِلُ على العباد على قدر هممهم وثباتهم ورغبتهم ورهبتهم، والخِذلان يَنزِل عليهم على حسب ذلك.\nفالله سبحانه أحكم الحاكمين وأعلم العالمين، يضعُ التوفيقَ في مواضعه اللائقة به، والخذلانَ في مواضعه اللائقة به، وهو العليم الحكيم، وما أُتِيَ من أُتِيَ إلَّا من قبل إضاعة الشُّكر وإهمال الافتقار والدُّعاء، ولا ظَفِرَ من ظفر بمشيئة الله وعونه إلَّا بقيامه بالشُّكر وصدق الافتقار والدُّعاء.\n\nومِلاكُ ذلك الصبرُ؛ فإنه من الإيمان بمنزلة الرأس من الجسد..",2,141,"/edition/37/section/9247#page-148",200,18],["فالحياة في الحقيقة: حياة القلب، وعمر الإنسان مدة حياته، فليس عمره إلا أوقات حياته بالله، فتلك ساعات عمره.",0,138,"/edition/20/section/6400#page-204",96,17],["أن القلب يصدأ من المعصية، فإن زادت غلب الصدأ حتى يصير رانًا، ثم يغلب حتى يصير طبعًا وقفلًا وختمًا، فيصير القلب في غشاوة وغلاف.\nفإن حصل له ذلك بعد الهدى والبصيرة انتكس فصار أعلاه أسفله، فحينئذ يتولاه عدوه، ويسوقه حيث أراد.",0,149,"/edition/20/section/6410#page-215",34,17],["ومن عقوباتها: أنها تخون العبدَ أحوجَ ما يكون إلى نفسه.\nفإذا وقع في مكروه، واحتاج إلى التخلص منه، خانه قلبُه ونفسُه وجوارحُه، وكان بمنزلة رجل معه سيفٌ قد غشِيَه الجرَبُ، ولزم قِرابَه بحيث لا ينجذب مع صاحبه إذا جذبه، فعرض له عدو يريد قتلَه، فوضع يده على قائم سيفه، واجتهد ليخرجه، فلم يخرج معه، فدهمه العدوّ، وظفر به.",0,213,"/edition/20/section/6433#page-279",48,17],["وأعجب من ذلك أن النظرة تجرح القلبَ، فيتبعُها جرحًا على جرح، ثم لا يمنعه ألمُ الجراحة من استدعاء تكرارها.",0,353,"/edition/20/section/6493#page-419",161,17],["وأعلى الفِكَر وأجلّها وأنفعها ما كان لله والدار الآخرة.\nفما كان لله أنواع:\nأحدها: الفكرة في آياته المنزلة، وتعقّلها وفهم مراده منها.\nالثاني: الفكرة في آياته المشهودة، والاعتبار بها، والاستدلال بها على أسمائه وصفاته، وحكمته وإحسانه، وبرّه وجوده.\nالثالث: الفكرة في آلائه، وإحسانه، وإنعامه على خلقه بأصناف النعم، وسعة رحمته ومغفرته وحلمه.\nالرابع: الفكرة في عيوب النفس وآفاتها وفي عيوب العمل.\nالخامس: الفكرة في واجب الوقت ووظيفته، وجمع الهمّ كلّه عليه.",0,356,"/edition/20/section/6493#page-422",3152,17],["تشبيه للقلب والخواطر\n\nفالقلب لوح فارغ، والخواطر نقوش تُنْقَش فيه، فكيف يليق بالعاقل أن تكون نقوش لوحه ما بين كذب، وغرور، وخدع، وأماني باطلة، وسراب لا حقيقة له؟",0,361,"/edition/20/section/6493#page-427",48,17],["فإنْ لم يُفرِّغ القلبَ من الخواطر الرديّة لم يستقرّ فيه الخواطر النافعة، فإنّها لا تستقرّ إلا في محل فارغ.",0,361,"/edition/20/section/6493#page-427",48,17],["فإذا رأيت الرجل: ذوقَه وجدَه وطربَه ونشوتَه في سماع الأبيات دون سماع الآيات، وفي سماع الألحان دون سماع القرآن فهذا من أقوى الأدلة على فراغ قلبه من محبة الله وكلامه، وتعلقه بمحبة سماع الشيطان؛ والمغرور يعتقد أنه على شيء!",0,552,"/edition/20/section/6553#page-618",816,17],["الغفلة، واتباع الهوى؛ يطمسان نور القلب، ويعميان بصره.",1,92,"/edition/42/section/9936#page-140",33,17],["أعلى الهِمَم في باب الإرادة أنْ تكونَ الهِمَّةُ متعلقةً بمحبة الله والوقوفِ مع مرادِهِ الدينيِّ الأمريِّ، وأسفلُها أن تكون الهمَّةُ واقفةً مع مرادِ صاحِبها من الله؛ فهو إنما يعبدُهُ لمُرادِهِ منه لا لمرادِ الله منه؛ فالأولُ يريدُ اللهَ ويريدُ مرادَهُ، والثاني يريدُ من الله وهو فارغٌ عن إرادتِهِ.",2,85,"/edition/37/section/9210#page-92",1536,17],["من عوّد نفسه العمل للَّه لم يكن عليه أشق من العمل لغيره، ومن عوّد نفسه العمل لهواه وحظه لم يكن عليه أشقّ من الإخلاص والعمل للَّه.",5,107,"/edition/67/section/16033#page-151",17,17],["الفتن التي تُعرَض على القلوب هي أسباب مرضها، وهي فتن الشهوات وفتن الشبهات، وفتن الغي والضلال، وفتن المعاصي والبدع، وفتن الظلم والجهل؛ فالأولى توجب فساد القصد والإرادة، والثانية توجب فساد العلم والاعتقاد.",7,16,"/edition/13/section/4117#page-57",35,17],["الغيظ يؤلم القلب، ودواؤه في شفاء غيظه، فإن شَفاه بحق اشتفى، وإن شفاه بظلم وباطل زاده مرضًا من حيث ظن أنه يشفيه، وهو كمن شفى مرض العشق بالفجور بالمعشوق، فإن ذلك يزيد مرضه، ويوجب له أمراضًا أُخر أصعب من مرض العشق.",7,19,"/edition/12/section/4091#page-18",33,17],["قال الله تعالى: ﴿قُلْ لِلْمُؤْمِنِينَ يَغُضُّوا مِنْ أَبْصَارِهِمْ وَيَحْفَظُوا فُرُوجَهُمْ ذَلِكَ أَزْكَى لَهُمْ إِنَّ اللَّهَ خَبِيرٌ بِمَا يَصْنَعُونَ (٣٠) وَقُلْ لِلْمُؤْمِنَاتِ يَغْضُضْنَ مِنْ أَبْصَارِهِنَّ وَيَحْفَظْنَ فُرُوجَهُنَّ﴾ الآية [النور/٣٠ ــ ٣١]\nفلمَّا كان غضُّ البصر أصلًا لحفظ الفرج؛ بدأ بذكره، ولمَّا كان تحريمُه تحريمَ الوسائل، فيُباح للمصلحة الرَّاجحة، ويَحْرُمُ إذا خِيفَ منه الفسادُ، ولم يُعارضْه مصلحةٌ أرجحُ من تلك المفسدة؛ لم يأمر سبحانه بغَضِّه مطلقًا، بل أمر بالغضِّ منه، وأمَّا حفظ الفرج فواجبٌ بكلِّ حالٍ، لا يُباح إلا بحقِّه، فلذلك عمَّ الأمر بحفظه.",9,92,"/edition/56/section/12512#page-88",1,17],["أن لكل عبد بداية ونهاية، فمن كانت بدايته اتباع الهوى؛ كانت نهايته الذل، والصغار، والحرمان، والبلاء المتنوع بحسب ما اتبع من هواه، بل يصير له ذلك في نهايته عذابا يعذب به في قلبه.",9,483,"/edition/56/section/12536#page-474",33,17],["لو تأملت حال كل ذي حال سيئة زرية، لرأيت بدايته الذهاب مع هواه، وإيثاره على عقله، ومن كانت بدايته مخالفة هواه، وطاعة داعي رشده؛ كانت نهايته العز والشرف، والغنى، والجاه عند الله، وعند الناس.",9,646,"/edition/57/section/12911#page-672",1025,17],["ومن تدبر حكمته سبحانه، ولطفه وبره بعباده وأحبابه، في كسره لهم ثم جبره بعد الانكسار، كما يكسر العبد بالذنب ويذله به ثم يجبره بتوبته عليه ومغفرته له، وكما يكسره بأنواع المصائب والمحن ثم يجبره بالعافية والنعمة انفتح له باب عظيم من أبواب معرفته ومحبته، وعلم أنه أرحم بعباده من الوالدة بولدها، وأن ذلك الكسر هو نفس رحمته به وبره ولطفه، وهو أعلم بمصلحة عبده منه، ولكن العبد لضعف بصيرته ومعرفته بأسماء ربه وصفاته لا يكاد يشعر بذلك، ولا ينال رضا المحبوب وقربه والابتهاج والفرح بالدنو منه والزلفى لديه إلا على جسر من الذل والمسكنة، وعلى هذا قام أمر المحبة، فلا سبيل إلى الوصول إلى المحبوب إلا بذلك.",11,66,"/edition/73/section/17946#page-166",1542,17],["وكمال كل إنسان إنما يتم بهذين النوعين: همة ترقيه، وعلم يبصره ويهديه، فإن مراتب السعادة والفلاح إنما تفوت العبد من هاتين الجهتين، أو من إحداهما:\n- إما أن لا يكون له علم بها، فلا يتحرك في طلبها.\n- أو يكون عالما بها ولا تنهض همته إليها.\nفلا يزال في حضيض طبعه محبوسا، وقلبه عن كماله الذي خلق له مصدودا منكوسا، قد أسام نفسه مع الأنعام راعيا مع الهمل، واستطاب لقيمات الراحة والبطالة، واستلان فراش العجز والكسل، لا كمن رفع له علم فشمر إليه، وبورك له في تفرده في طريق طلبه فلزمه واستقام عليه، قد أبت غلبات شوقه إلا الهجرة إلى الله ورسوله، ومقتت نفسه الرفقاء إلا ابن سبيل يرافقه في سبيله.",11,46,"/edition/72/section/17746#page-44",1073,17],["اللذة بالمحبوب تضعف وتقوى بحسب قوة الحب وضعفه، فكلما كان الحب أقوى كانت اللذة أعظم.",11,240,"/edition/73/section/18026#page-340",1537,17],["القلب الغافل مأوى الشيطان؛ فإنه وسواس خناس، قد التقم قلب الغافل يقرأ عليه أنواع الوساوس والخيالات الباطلة، فإذا تذكر وذكر الله انجمع وانضم وخنس وتضاءل لذكر الله، فهو دائما بين الوسوسة والخنس.",11,311,"/edition/73/section/18036#page-411",176,17],["﴿قل أرأيتم إن جعل الله عليكم الليل سرمدا إلى يوم القيامة من إله غير الله يأتيكم بضياء أفلا تسمعون (٧١) قل أرأيتم إن جعل الله عليكم النهار سرمدا إلى يوم القيامة من إله غير الله يأتيكم بليل تسكنون فيه أفلا تبصرون﴾ [القصص: ٧١ - ٧٢].\nوخص سبحانه النهار بذكر البصر؛ لأنه محله، وفيه سلطان البصر وتصرفه.\nوخص الليل بذكر السمع لأن سلطان السمع يكون بالليل، وتسمع فيه الحيوانات ما لا تسمع في النهار؛ لأنه وقت هدوء الأصوات، وخمود الحركات، وقوة سلطان السمع، وضعف سلطان البصر.\nوالنهار بالعكس؛ فيه قوة سلطان البصر، وضعف سلطان السمع.",11,591,"/edition/73/section/18115#page-691",2049,17],["تأمل محاسن الوضوء بين يدي الصلاة، وما تضمنه من النظافة والنزاهة ومجانبة الأوساخ والمستقذرات.\nوتأمل كيف وضع على الأعضاء الأربعة التي هي آلة البطش والمشي، ومجمع الحواس التي أكثر تعلق الذنوب والخطايا بها.\nفلما كانت هذه الأعضاء هي أكثر الأعضاء مباشرة للمعاصي، كان وسخ الذنوب ألصق بها، وأعلق من غيرها؛ فشرع أحكم الحاكمين الوضوء عليها ليتضمن نظافتها وطهارتها من الأوساخ الحسية وأوساخ الذنوب والمعاصي.",11,915,"/edition/73/section/18219#page-1015",258,17],["\"انتظار روح الفرج يعني راحته، ونسيمه، ولذته؛ فإن انتظاره، ومطالعته، وترقبه يخفف حمل المشقة لا سيما عند قوة الرجاء، أو القطع بالفرج؛ فإنه يجد في حشو البلاء من رَوْح الفرج، ونسيمه، وراحته ما هو من خفي الألطاف، وما هو فرج معجل\".",13,166,"/edition/70/section/16418#page-659",1,17],["في القلب شعث، لا يلمه إلا الإقبال على الله. وفيه وحشة، لا يزيلها إلا الأنس به في خلوته ، وفيه حزن لا يذهبه إلا السرور بمعرفته وصدق معاملته ، وفيه قلق لا يسكنه إلا الاجتماع عليه، والفرار منه إليه ، وفيه نيران حسرات لا يطفئها إلا الرضى بأمره ونهيه وقضائه، ومعانقة الصبر على ذلك إلى وقت لقائه ، وفيه طلب شديد لا يقف دون أن يكون هو وحده مطلوبه ، وفيه فاقة لا يسدها إلا محبته، والإنابة إليه، ودوام ذكره، وصدق الإخلاص له ، ولو أعطي الدنيا وما فيها لم تسد تلك الفاقة منه أبدًا.",13,17,"/edition/71/section/17508#page-1986",1580,17],["قال تعالى: {وَالْعَصْرِ (١) إِنَّ الْإِنْسَانَ لَفِي خُسْرٍ (٢) إِلَّا الَّذِينَ آمَنُوا وَعَمِلُوا الصَّالِحَاتِ وَتَوَاصَوْا بِالْحَقِّ وَتَوَاصَوْا بِالصَّبْرِ} [سورة العصر]،\n\nفأقسم سبحانه أنَّ كلَّ أحدٍ خاسرٌ إلّا من كمَّل قوّتَه العلميّة بالإيمان، وقوّتَه العمليّة بالعمل الصّالح، وكمَّل غيره بالتّوصية له بالحقِّ والصّبر عليه؛ فالحقُّ هو الإيمان والعمل، ولا يتمُّ إلّا بالصَّبر عليه والتَّواصي به= كان حقيقًا بالإنسان أن ينفق ساعاتِ عمره بل أنفاسَه فيما ينال به المطالب العالية، ويخلص به من الخسران المبين. وليس ذلك إلّا بالإقبال على القرآن وتفهُّمه وتدبُّره واستخراج كنوزه، وإثارة دفائنه، وصرف العناية إليه، والعكوف بالهمّة عليه؛ فإنّه الكفيل بمصالح العباد في المعاش والمعاد، والمُوصِل لهم إلى سبيل الرّشاد. فالحقيقة، والطّريقة، والأذواق والمواجيد الصّحيحة= كلُّها لا تُقْتبَس إلّا من مشكاته، ولا تُسْتثمَر إلّا من شجراته.",13,30,"/edition/70/section/16792#page-3",1352,17],["القرآن مزيل للأمراض الموجِبَةِ للإرادات\nالفاسدة، فيصلح القلب، فتصلح إرادته، ويعود إلى فطرته التي فُطِر عليها، فتصلح أفعاله الاختيارية الكسبية، كما يعود البدن بصحته وصلاحه إلى الحال الطبيعي، فيصير بحيث لا يقبل إلا الحق، كما أن الطفل لا يقبل إلا اللبن .. فيتغذَّى القلب من الإيمان والقرآن بما يزكِّيه ويقوِّيه، ويؤيده ويفرحه، ويسرُّه وينشِّطه، ويثبِّت ملكه، كما يتغذّى  البدن بما ينمِّيه ويقويه، وكلٌ من القلب والبدن محتاج إلى أن يتربَّى ، فينمو ويزيد حتى يكمل ويصلح. فكما أن البدن محتاج إلى أن يُربَّى بالأغذية المصلحة له، والحِمْية عما يضره، فلا ينمو إلا بإعطاء ما ينفعه، ومنع ما يضره؛ فكذلك القلب لا يزكو ولا ينمو ولا يتم صلاحه إلا بذلك، ولا سبيل له إلى الوصول إلى ذلك إلا من القرآن.",7,46,"/edition/12/section/4095#page-46",288,17],["وعلّق سبحانه المزيد بالشكر ، والمزيد منه لا نهاية له، كما لا نهاية لشكره.\n\nوقد وقف سبحانه كثيرًا من الجزاء على المشيئة، كقوله: ﴿فَسَوْفَ يُغْنِيكُمُ اللَّهُ مِنْ فَضْلِهِ إِنْ شَاءَ﴾ [التوبة: ٢٨]، وقوله في الإجابة: ﴿فَيَكْشِفُ مَا تَدْعُونَ إِلَيْهِ إِنْ شَاءَ﴾ [الأنعام: ٤١]، [وقوله في الرزق: ﴿يَرْزُقُ مَنْ يَشَاءُ﴾]  [آل عمران: ٣٧]، والتوبة: ﴿وَيَتُوبُ اللَّهُ عَلَى مَنْ يَشَاءُ﴾ [التوبة: ١٥] وفي المغفرة: ﴿يَغْفِرُ لِمَنْ يَشَاءُ﴾ [آل عمران: ١٢٩].\n\nوأطلق جزاء الشكر إطلاقًا حيث ذُكر، كقوله: ﴿وَسَنَجْزِي الشَّاكِرِينَ (١٤٥)﴾ [آل عمران: ١٤٥]، ﴿وَسَيَجْزِي اللَّهُ الشَّاكِرِينَ (١٤٤)﴾ [آل عمران: ١٤٤].\n\nولما عَرف عدو اللَّه إبليس قَدْر مقام الشكر  وأنه أجلُّ المقامات وأعلاها، جعل غايته أن يسعى في قطع الناس عنه، فقال: ﴿ثُمَّ لَآتِيَنَّهُمْ مِنْ بَيْنِ أَيْدِيهِمْ وَمِنْ خَلْفِهِمْ وَعَنْ أَيْمَانِهِمْ وَعَنْ شَمَائِلِهِمْ وَلَا تَجِدُ أَكْثَرَهُمْ شَاكِرِينَ (١٧)﴾ [الأعراف: ١٧].",5,117,"/edition/66/section/15985#page-92",20,17],["وأعظم الخلق غرورًا من اغترّ بالدنيا وعاجلها، فآثرها على الآخرة، ورضي بها من الآخرة، حتّى يقولُ بعض هؤلاء: الدنيا نقد، والآخرة نسيئة، والنقد أنفع من النسيئة!\nويقول بعضهم: ذَرّة منقودة، ولا دُرّة موعودة!\nوهذا من أعظم تلبيس الشيطان وتسويله.\nوالبهائم العُجْم أعقل من هؤلاء، فإنّ البهيمة إذا خافت مضرةَ شيء لم تُقْدِم عليه، ولو ضُرِبَتْ، وهؤلاء يُقدِم أحدُهم على عطَبه، وهو بين مصدّق ومكذّب.",0,79,"/edition/20/section/6384#page-145",2064,16],["إن المؤمن قوته من قلبه، وكلما قوي قلبه قوي بدنه.\nوأما الفاجر، فإنه وإن كان قويَّ البدن، فهو أضعف شيء عند الحاجة، فتخونه قوته أحوجَ ما يكون إلى نفسه.\n\nوتأمَّلْ قوة أبدان فارس والروم، كيف خانتهم أحوجَ ما كانوا إليها؛ وقهرهم أهلُ الإيمان بقوة أبدانهم وقلوبهم؟",0,136,"/edition/20/section/6400#page-202",48,16],["العبد إذا عمل حسنة قالت أخرى إلى جانبها: اعملني أيضًا، فإذا عملها قالت الثانية كذلك، وهلم جرًّا، فتضاعف الربح، وتزايدت الحسنات.\nوكذلك جانب السيئات أيضًا،\nحتى تصير الطاعات والمعاصي هيئات راسخة وصفات لازمة وملكات ثابتة.",0,139,"/edition/20/section/6401#page-205",2,16],["ولا يزال العبد يعاني الطاعة، ويألفها، ويحبها، ويؤثرها حتى يرسل الله سبحانه برحمته عليه الملائكةَ تؤزُّه إليها أزًّا، وتحرضه عليها، وتزعجه عن فراشه ومجلسه إليها.\n\nولا يزال يألف المعاصي، ويحبها، ويؤثرها، حتى يرسل الله عليه الشياطين فتؤزّه إليها أزًّا.\n\nفالأول قوَّى جندَ الطاعة بالمدد، فصاروا من أكبر أعوانه.\nوهذا قوَّى جندَ المعصية بالمدد، فكانوا أعوانًا عليه.",0,140,"/edition/20/section/6401#page-206",2,16],["والبعد من الله مراتب بعضها أشد من بعض:\nفالغفلة تبعد العبد عن الله،\nوبعدُ المعصية أعظم من بعد الغفلة،\nوبعد البدعة أعظم من بعد المعصية،\nوبعد النفاق والشرك أعظم من ذلك كله.",0,191,"/edition/20/section/6425#page-257",2,16],["الملَكُ يُلقي في القلب الحقَّ، ويُلقيه على اللسان.\nوالشيطانُ يُلقي الباطل في القلب، ويُجريه على اللسان.",0,253,"/edition/20/section/6447#page-319",48,16],["وعقوبات الذنوب نوعان:\nشرعية وقدرية.\nفإذا أقيمت الشرعيةُ رفَعَتْ العقوباتِ القدريةَ أو خففتها.\nولا يكاد الرب تعالى يجمع على عبده بين العقوبتين، إلا إذا لم تفِ إحداهما برفع موجَب الذنب ولم تكفِ في زوال دائه.",0,260,"/edition/20/section/6450#page-326",2,16],["الذنوب ثلاثة أقسام:\n- قسمًا فيه الحدّ، فهذا لم يشرع فيه كفارة، اكتفاءَ بالحدّ.\n- وقسمًا لم يرتِّبْ عليه حدًّا، فشرع فيه الكفّارةَ؛ كالوطء في نهار رمضان.\n- وقسمًا لم يرتِّبْ عليه حدًّا ولا كفارة، وهو نوعان:\nأحدهما: ما كان الوازع عنه طبعيًّا؛ كأكل العَذِرة.\nوالثاني: ما كانت مفسدته أدنى من مفسدة ما رتب عليه الحد؛ كالنظر، والقُبْلة.",0,265,"/edition/20/section/6455#page-331",3,16],["﴿وَمَنْ تَقِ السَّيِّئَاتِ يَوْمَئِذٍ فَقَدْ رَحِمْتَهُ﴾\nوقاية السيئات نوعان: أحدهما: وقاية فعلها بالتوفيق فلا تصدر منه. والثاني: وقاية جزائها بالمغفرة فلا يعاقب عليها.",0,270,"/edition/20/section/6458#page-336",2,16],["وقد حمى النبي- ﷺ جانبَ التوحيد أعظم حماية، حتى نهى عن صلاة التطوع لله سبحانه عند طلوع الشمس وعند غروبها، لئلّا يكون ذريعةً إلى التشبّه بعُبّاد الشمس الذين يسجدون لها في هاتين الحالتين، وسدّ الذريعةَ بأن منع من الصلاة بعد العصر والصبح لاتصال هذين الوقتين بالوقتين اللذين يسجد المشركون فيهما للشمس.",0,309,"/edition/20/section/6478#page-375",320,16],["ومن العجب أن الإنسان يهون عليه التحفظ والاحتراز من أكل الحرام والظلم والزنا والسرقة وشرب الخمر ومن النظر المحرّم وغير ذلك، ويصعب عليه التحفظ من حركة لسانه، حتى ترى الرجلَ يشار إليه بالدين والزهد والعبادة، وهو يتكلّم بالكلمات من سخط الله، لا يُلقي لها بالًا، يزِلّ بالكلمة الواحدة منها أبعد مما بين المشرق والمغرب.",0,366,"/edition/20/section/6493#page-432",1,16],["حين بكى سفيان\n\nولقد بكى سفيان الثوري ليلةً إلى الصباح، فلما أصبح قيل له: كلُّ هذا خوفًا من الذنوب؟\nفأخذ تِبْنةً من الأرض، وقال: الذنوب أهون من هذا، وإنّما أبكي من خوف الخاتمة.",0,390,"/edition/20/section/6497#page-456",2,16],["ما أكثر ما يُقَدِّم العبد ما يحبه هو ويهواه، أو يحبه كبيره أو أميره أو شيخه أو أهله على ما يحبه الله تعالى، وسُنَّةُ الله تعالى فيمن هذا شأنه أن يُنَكِّدَ عليه مَحَابَّه، ويُنَغِّصها عليه، فلا ينال شيئًا منها إلا بنكدٍ وتنغيصٍ، جزاءً له على إيثاره هواه وهوى من يُعَظِّمُه من الخلق أو يُحِبُّه على محبة الله تعالى.",1,14,"/edition/42/section/9893#page-62",513,16],["كما أن [الصدقة] تُطْفِئُ غضب الرب تبارك وتعالى، فهي تُطْفِئُ الذنوب والخطايا كما يُطْفِئُ الماء النار.",1,70,"/edition/42/section/9927#page-118",2050,16],["المحبة هي روح الإسلام، وقطب رَحى الدين، ومدار السعادة والنجاة، وقد جعل الله لكل شيء سببًا، وجعل سبب المحبة دوام الذكر؛ فمن أراد أن ينال محبة الله عز وجل فَلْيَلْهَجْ بذكره، فإن الدرس والمذاكرة كما أنه باب العلم، فالذكر باب المحبة، وشارعها الأعظم، وصراطها الأقوم.",1,94,"/edition/42/section/9946#page-142",640,16],["إذا صار الذكر شِعار القلب، بحيث يكون هو الذاكر بطريق الأصالة، واللسان تَبَعٌ له، فهذا هو الذكر الذي يَسُدُّ الخَلَّة، ويُغْنِي الفاقة، فيكون صاحبه غنيًّا بلا مال، عزيزًا بلا عشيرة، مَهيبًا بلا سلطان.",1,155,"/edition/42/section/9978#page-203",160,16],["النفسُ إن لم تَشْغَلْها بالحق وإلا شَغَلَتْكَ بالباطل.\nوالقلب إنْ لم تَسْكُنه محبةُ الله عز وجل، سَكَنَتْهُ محبة المخلوقين.\nواللسان إنْ لم تشغله بالذكر شغلك باللغو.\nفاختر لنفسك إحدى الخُطَّتين، وأَنْزِلْها في إحدى المنزلتين.",1,198,"/edition/42/section/10011#page-246",688,16],["شروط الانتفاع بالقرآن\n\nإذا حصل المؤثِّرُ وهو القرآنُ، والمحلُّ القابلُ وهو القلبُ الحيُّ، ووُجِد الشرطُ وهو الإصغاءُ، وانتفى المانعُ وهو اشتغالُ القلبِ وذهولُه عن معنى الخطاب وانصرافُه عنه إلى شيءٍ آخر؛ حَصَل الأثرُ وهو الانتفاعُ والتذكُّرُ.",2,4,"/edition/37/section/9133#page-11",288,16],["الربُّ تعالى يدعو عباده في القرآنِ إلى معرفتِهِ من طريقين:\nأحدُهما: النظرُ في مفعولاتِهِ.\nوالثاني: التفكُّر في آياتِهِ وتدبُّرُها؛ فتلك آياتُهُ المشهودةُ، وهذه آياتُهُ المسموعةُ المعقولةُ.",2,28,"/edition/37/section/9153#page-35",385,16],["المعاصي سَدٌّ في باب الكسبِ، و«إنَّ العَبْدَ لَيُحْرَمُ الرِّزْقَ بالذَّنْب يُصيبُهُ».",2,69,"/edition/37/section/9190#page-76",2,16],["بين العبد وبين الله والجنةِ قنطرةٌ تُقْطَعُ بخُطوتين: خطوةٍ عن نفسه، وخُطوةٍ عن الخلقِ؛ فيُسْقِطُ نفسَهُ ويُلْغِيها فيما بينهُ وبين الناس، ويُسْقِطُ الناسَ ويُلْغِيهم فيما بينَهُ وبين الله؛ فلا يلتفِتُ إلَّا إلى من دَلَّهُ على الله وعلى الطريق الموصلة إلى الله.",2,76,"/edition/37/section/9200#page-83",2064,16],["جمع النبيُّ ﷺ في قوله: «فاتَّقوا الله وأجْمِلوا في الطَّلَبِ» بين مصالح الدُّنيا والآخرةِ، فنعيمُها ولَذَّتُها إنما يُنال بتقوى الله، وراحةُ القلب والبدنِ وتركُ الاهتمامِ والحِرْصِ الشَّديدِ والتَّعَب والعَناءِ والكدِّ والشَّقاءِ في طلبِ الدُّنيا إنَّما يُنالُ بالإجمال في الطَّلَبِ، فمنِ اتَّقى الله فازَ بلذَّةِ الآخرة ونعيمِها، ومن أجْمَلَ في الطَّلَب استراحَ من نَكَدِ الدُّنيا وهمومها.",2,82,"/edition/37/section/9206#page-89",3104,16],["أركان الكفر أربعةٌ:\nالكبرُ، والحسد، والغضب، والشهوة،\nفالكبر يمنعه الانقيادَ،\nوالحسد يمنعه قبولَ النصيحة وبذلها،\nوالغضبُ يمنعه العدلَ،\nوالشهوة تمنعه التفرُّغَ للعبادة.",2,231,"/edition/37/section/9319#page-238",1,16],["السَّنة شجرةٌ،\nوالشهور فروعها،\nوالأيام أغصانها،\nوالساعات أوراقها،\nوالأنفاس ثمرها،\nفمن كانت أنفاسه في طاعته فثمرة شجرته طيبةٌ،\nومن كانت في معصيةٍ فثمرته حنظلٌ،\nوإنما يكون الجَدَادُ يوم المعاد؛ فعند الجَدَاد يتبينُ حلو الثمار من مُرّها.",2,240,"/edition/37/section/9325#page-247",3,16],["الإخلاص والتوحيد شجرةٌ في القلب؛ فروعها الأعمال، وثمرها طيب الحياة في الدنيا والنعيم المقيم في الآخرة، وكما أن ثمار الجنة لا مقطوعةٌ ولا ممنوعةٌ؛ فثمرة التوحيد والإخلاص في الدُّنيا كذلك.",2,240,"/edition/37/section/9325#page-247",3104,16],["الجمال في الصورة واللباس والهيئة ثلاثة أنواع:\nمنه ما يُحمَد، ومنه ما يُذَمّ، ومنه ما لا يتعلق به مدحٌ ولا ذمٌّ:\nفالمحمود منه ما كان لله وأعان على طاعة الله وتنفيذ أوامره والاستجابة له، والمذموم منه ما كان للدنيا والرئاسة والفخر والخيلاء والتوسل إلى الشهوات، وأن يكون هو غاية العبد وأقصى مطلبه، وأما ما لا يُحمَد ولا يُذم فهو ما خلا عن هذين القصدين وتجرد عن الوصفين.",2,270,"/edition/37/section/9354#page-277",1,16],["[حقيقة الصبر]: هو خُلُق فاضل من أخلاق النفس، تمتنع به من فعل ما لا يحسن ولا يجمل، وهو قوة من قُوى النفس التي بها صَلاح شأنِها، وقوام أمرها.",5,16,"/edition/66/section/15991#page-258",24,16],["النفس مطيةُ العبد التي يسير عليها إلى الجنة أو النار، والصبر لها بمنزلة الخِطام والزمام للمطية، فإن لم يكن للمطية خطام ولا زمام شرَدَت في كل مذهب.",5,25,"/edition/67/section/16019#page-69",2072,16],["المرابطة كما أنها لزوم الثغر الذي يُخاف هجوم العدوّ منه في الظاهر، فهي لزوم ثغر القلب لئلا يدخل منه الهوى والشيطان فيزيله عن مملكته.",5,34,"/edition/67/section/16021#page-78",49,16],["الصبر باعتبار متعلقه ثلاثة أقسام:\nصبر على الأوامر والطاعات حتى يؤديها.\nوصبر عن المناهي والمخالفات حتى لا يقع فيها.\nوصبر على الأقدار والأقضية حتى لا يتسخطها.",5,28,"/edition/66/section/15991#page-266",8,16],["الصبر الواجب ثلاثة أنواع:\nأحدها: الصبر عن المحرمات.\nوالثاني: الصبر على أداء الواجبات.\nوالثالث: الصبر على المصائب التي لا صنع للعبد فيها كالأمراض والفقر وغيرهما.",5,31,"/edition/66/section/15991#page-268",8,16],["الصبر على الواجب واجب وعن الواجب حرام، والصبر عن الحرام واجب وعليه حرام، والصبر على المستحب مستحب وعنه مكروه، والصبر عن المكروه مستحب وعليه مكروه، والصبر عن المباح وعليه مباح.",5,58,"/edition/67/section/16025#page-102",8,16],["الصبر المتعلق بالتكليف -وهو: الأمر والنهي- أفضل من الصبر على مجرد القدر، وكل صبر في محله وموضعه أفضل؛ فالصبر عن الحرام في محله أفضل، والصبر على الطاعة في محلها أفضل.",5,64,"/edition/67/section/16027#page-108",8,16],["الصبر لله: ترك حظوظ النفس ومرادها لمراد اللَّه، وهذا أشق شيء على النفس وأصعبه.",5,90,"/edition/67/section/16029#page-134",24,16],["ليس الشأن في فعل المأمور بل الشأن كل الشأن أن لا ينسى الآمر حال الإتيان بأمره، بل يكون مستصحبًا لذكره في أمره. فهذه عبادة العبيد المخلصين، فهو محتاج إلى الصبر على توفية العبادة حقها بالقيام بأدائها وأركانها وواجباتها وسننها، وإلى الصبر على استصحاب ذكر المعبود فيها وأن لا يشتغل عنه بعبادته، فلا يعطله حضوره مع اللَّه بقلبه عن قيام جوارحه بعبوديته، ولا يعطله قيام الجوارح بالعبودية عن حضور قلبه بين يديه.",5,118,"/edition/67/section/16036#page-162",40,16],["مشقة الصبر بحسب قوة الداعي إلى الفعل وسهولته على العبد، فإذا اجتمع في الفعل هذان الأمران كان الصبر عنه أشق شيء على الصابر، وإن فُقدا معًا سهُل الصبر عنه، وإن وجد أحدهما وفُقِد الآخر سهُل الصبر من وجه وصعُب من وجه.",5,69,"/edition/66/section/15991#page-280",8,16],["العبد كماله في تكميل قوّتيه: قوة العلم وقوة العمل، وهما الإيمان والعمل الصالح. وكما هو محتاج إلى تكميل نفسه، فهو محتاج إلى تكميل غيره، وهو التواصي بالحق، والتواصي بالصبر، وآخية ذلك وقاعدته وساقه الذي يقوم عليه إنما هو الصبر.",5,135,"/edition/67/section/16038#page-179",24,16],["الرغبة في الدنيا تشتت القلب وتبدد الشمل، وتطيل الهم والغم والحزن، فهي عذاب حاضر يؤدي إلى عذاب منتظر أشد منه، وتفوت على العبد من النعم أضعاف ما يروم تحصيله بالرغبة في الدنيا.",5,512,"/edition/67/section/16055#page-556",1056,16],["الفرق بين الصبر والحلم: أن الصبر ثمرة الحلم وموجبه، فعلى قدر حلم العبد يكون صبره.",5,533,"/edition/67/section/16058#page-577",8,16],["خبث الملبس يُكسِبُ القلب هيئةً خبيثة، كما أن خبث المطعمِ يُكسِبه ذلك، ولذلك حَرُمَ لبس جلود النمور والسباع بنهي النبي ﷺ عن ذلك في عدة أحاديث صحاح لا معارض لها، لما يكتسب القلب من الهيئة المشابهة لتلك الحيوانات، فإن الملابسة الظاهرة تسري إلى الباطن، ولذلك حَرُم لبس الحرير والذهب على الذكور، لما يُكْسِبُ القلب من الهيئة التي تكون لمن ذلك لُبْسُهُ من النساء، وأهل الفخر والخُيَلاء.",7,92,"/edition/13/section/4168#page-133",1056,16],["نهى ﷺ عن التشدُّد في الدين، وذلك بالزيادة على المشروع، وأخبر أن تشديد العبد على نفسه هو السبب لتشديد الله عليه؛ إما بالقَدَر، وإما بالشرع.\nفالتشديد بالشرع: كما يشدد على نفسه بالنذر الثقيل، فيلزمه الوفاء به.\nوبالقَدر: كفعل أهل الوسواس، فإنهم شددوا على أنفسهم؛ فشدد عليهم القَدر، حتى استحكم ذلك، وصار صفة لازمة لهم.",7,229,"/edition/13/section/4247#page-270",16,16],["الغايات الحميدة في خبايا الأسباب المكروهة الشاقة، كما أن الغايات المكروهة المؤلمة في خبايا الأسباب المشتهاة المستلذة. وهذا من حين خلق الله سبحانه الجنة وحَفَّها بالمكاره، والنار وحَفَّها بالشهوات.",7,818,"/edition/13/section/4592#page-859",3073,16],["أن ما يصيب المؤمنين في الله تعالى مقرون بالرضا والاحتساب، فإن فاتهم الرضا فمعولهم على الصبر والاحتساب، وذلك يخفف عنهم ثقل البلاء ومؤونته، فإنهم كلما شاهدوا العوض هان عليهم تحمل المشاق والبلاء، والكفار لا رضا عندهم ولا احتساب، وإن صبروا فكصبر البهائم.",7,934,"/edition/13/section/4863#page-975",8,16],["أن البلاء الذي يصيب العبد في الله لا يخرج عن أربعة أقسام:\nفإنه إما أن يكون في نفسه،\nأو في ماله،\nأو في عرضه،\nأو في أهله ومن يحب،\nوالذي في نفسه قد يكون بتلفها تارة، وبتألمها بدون التلف.\nفهذا مجموع ما يبتلى به العبد في الله.\nوأشد هذه الأقسام: المصيبة في النفس.",7,941,"/edition/13/section/4885#page-982",16,16],["الفاسق يستمتع بالشيطان، بإعانته له على أسباب فسوقه، والشيطان يستمتع به في قبوله منه، وطاعته له، فيسره ذلك، ويفرح به منه.\nوالمشرك يستمتع به الشيطان، بشركه به، وعبادته له، ويستمتع هو بالشيطان في قضاء حوائجه، وإعانته له.\nومن لم يحط علما بهذا لم يعلم حقيقة الإيمان والشرك، وسر امتحان الرب سبحانه كلا من الثقلين بالآخر.",7,993,"/edition/13/section/5028#page-1034",16,16],["معرفة الله سبحانه نوعان:\nالأول: معرفة إقرار، وهي التي اشترك فيها الناس البر والفاجر، والمطيع والعاصي.\nوالثاني: معرفة توجب الحياء منه والمحبة له وتعلق القلب به والشوق إلى لقائه وخشيته والإنابة إليه والأنس به والفرار من الخلق إليه، وهذه هي المعرفة الخاصة.",2,248,"/edition/37/section/9333#page-255",548,16],["المسكنة التي يحبها اللَّه من عبده ليست مسكنة فقر المال، بل مسكنة القلب وهي انكساره وذله وخشوعه وتواضعه للَّه، وهذه المسكنة  لا تُنافي الغِنى ولا يُشترط لها الفقر، فإن انكسار القلب للَّه ومسكنته لعظمته وجلاله وكبريائه وأسمائه وصفاته أفضل وأعلى من مسكنة عدم المال، كما أن صبر القادر الواجد عن معاصي اللَّه طوعًا واختيارًا وخشية من اللَّه ومحبة له أعلى من صبر الفقير العاجز.\nوقد آتى اللَّه سبحانه جماعة من أنبيائه ورسله الغنى والملك، ولم يخرجهم ذلك عن المسكنة للَّه.",5,340,"/edition/67/section/16052#page-384",40,16],["للذكر من بين الأعمال لَذّةً لا يشبهها شيء، فلو لم يكن للعبد من ثوابه إلا اللذةُ الحاصلة للذاكر، والنعيمُ الذي يحصل لقلبه لكفى به..\n\nفليس شيء من الأعمال أخفُّ مؤونةً منه، ولا أعظم لذة، ولا أكثر فرحة وابتهاجًا للقلب.",1,196,"/edition/42/section/10008#page-244",1056,16],["كلُّ أحد لا بد أن يصبر على بعض ما يكره، إما اختيارًا وإما اضطرارًا.\n\nفالكريم يصبر اختيارًا لعلمه بحسن عاقبة الصبر، وأنه يُحمد عليه ويُذم على الجزع، وأنه إن لم يصبر لم يرُدَّ الجزعُ عليه فائتًا، ولم ينزع عنه مكروهًا، وأن المقدور لا حيلة في دفعه، وما لم يُقدَّر لا حيلة في تحصيله، فالجزع خوفٌ محض ضرُّه أقرب من نفعه.\n\nقال بعض العقلاء:\n«العاقل عند نزول المصيبة يفعل ما يفعلُه الأحمق بعد شهر».",5,52,"/edition/66/section/15991#page-274",8,16],["السخط باب الهمِّ والغمِّ والحزن، وشتات القلب، وكسف البال، وسوء الحال، والظنِّ بالله خلاف ما هو أهله. والرِّضا يخلِّصه من ذلك كلِّه ويفتح له باب جنَّة الدُّنيا قبل جنَّة الآخرة.",13,528,"/edition/71/section/17137#page-1258",3104,16],["إذا تأملتَ أخبار الأمم وأيام الله في أهل طاعته وأهل معصيته طابق ذلك ما علمتَه من القرآن والسنة، ورأيت تفاصيل ما أخبر الله به ووعد به، وعلمتَ من آياته في الآفاق ما يدلّك على أن القرآن حق، وأن الرسول حق، وأن الله ينجز وعده لا محالة.\nفالتاريخ تفصيل لجزئيات ما عرّفنا الله ورسوله ﷺ به من الأسباب الكلية للخير والشر.",0,35,"/edition/20/section/6377#page-101",258,15],["ومن عقوبات المعاصي: أنها تمحق بركة العمر، وبركة الرزق، وبركة العلم، وبركة العمل، وبركة الطاعة.\nوبالجملة، تمحق بركة الدين والدنيا.",0,199,"/edition/20/section/6430#page-265",66,15],["العقوبات القدرية نوعان:\nنوع على القلوب والنفوس، ونوع على الأبدان والأموال.\nوالتي على القلوب نوعان:\nأحدهما: آلام وجودية يُضرَب بها القلبُ.\nوالثاني: قطع المواد التي بها حياته وصلاحه عنه، وإذا قطعت عنه حصل له أضدادها.",0,267,"/edition/20/section/6457#page-333",32,15],["ومن آفات النظر:\nأنه يورث الحسرات والزفرات والحرقات، فيرى العبد ما ليس قادرًا عليه ولا صابرًا عنه.\nوهذا من أعظم العذاب أن ترى ما لا صبر لك عن بعضه، ولا قدرة لك على بعضه.",0,351,"/edition/20/section/6493#page-417",9,15],["قال يحيي بن معاذ:\nالقلوب كالقدور تغلي بما فيها، وألسنتها مغارفها.\nفانظر الرجل حين يتكلم، فإن لسانه يغترف لك مما في قلبه: حلو وحامض، وعذب وأجاج، وغير ذلك. ويبين لك طعم قلبه اغترافُ لسانه.",0,364,"/edition/20/section/6493#page-430",32,15],["من جُعِلَتْ قرة عينه في الصلاة، كيف تقر عينه بدونها، وكيف يطيق الصبر عنها؟! فصلاة هذا الحاضر بقلبه الذي قرة عينه في الصلاة، هي التي تصعد ولها نور وبرهان، حتى يُسْتَقْبَلَ بها الرحمن عز وجل فتقول: «حَفِظَكَ اللهُ تعالى كمَا حَفِظْتَني»، وأما صلاة المفرّط المضيّع لحقوقها وحدودها وخشوعها؛ فإنها تُلَفُّ كما يُلَفُّ الثوب الخَلِق، ويُضْرَب بها وجه صاحبها وتقول: «ضَيَّعَكَ اللهُ كما ضَيَّعْتَنِي».",1,47,"/edition/42/section/9913#page-95",296,15],["الفرق بين الشُّحِّ والبخل:\n\nأن الشُّحَّ: هو شدة الحرص على الشيء، والإحفاء في طلبه، والاستقصاء في تحصيله، وجَشَعُ النفس عليه.\n\nوالبخل: منعُ إنفاقه بعد حصوله، وحُبُّه وإمساكُه، فهو شحيحٌ قبل حصوله، بخيلٌ بعد حصوله.\n\nفالبخلُ ثمرة الشُّحِّ، والشُّحُّ يدعو إلى البخل، والشُّحُّ كامِنٌ في النفس، فمن بخل فقد أطاع شُحَّه، ومن لم يبخل فقد عصى شُحَّه، وَوُقِي شره، وذلك هو المفلح.",1,75,"/edition/42/section/9929#page-123",144,15],["الشيطان لا يُحْرِزُ العبادُ أنفسَهم منه إلا بذكر الله عز وجل.",1,206,"/edition/42/section/10013#page-254",144,15],["لما كانت الصلاة مشتملة على القراءة والذكر والدعاء، وهي جامعةٌ لأجزاء العبودية على أتم الوجوه، كانت أفضل من كُلٍّ من القراءة والذكر والدعاء بمفرده؛ لجمعها ذلك كلِّه مع عبوديةِ سائر الأعضاء.",1,234,"/edition/42/section/10018#page-282",384,15],["عن ابن عمر قال: قلَّما كان رسول الله ﷺ يقوم من مجلس حتى يدعو بهؤلاء الكلمات لأصحابه: «اللَّهُمَّ اقسم لنا من خشيتك ما تحول به بيننا وبين معصيتك، وَمِنْ طاعتك ما تُبَلِّغنا به جنتك، وَمِن اليقين ما تُهَوِّن به علينا مصائب الدنيا، اللَّهُمَّ متعنا بأسماعنا وأبصارنا وقوتنا ما أحييتنا، واجعله الوارث منا، واجعل ثأرنا على من ظلمنا، وانصرنا على من عادانا، ولا تجعل مصيبتنا في ديننا، ولا تجعل الدنيا أكبر همِّنا، ولا مبلغ علمنا، ولا تُسَلِّط علينا من لا يرحمنا».",1,361,"/edition/42/section/10066#page-407",131,15],["ارْجعْ إلى الله، واطلُبْهُ من عينك وسمعك وقلبك ولسانك، ولا تَشْرُدْ عنهُ من هذه الأربعة؛ فما رجع من رجع إليه بتوفيقه إلَّا منها، وما شرد من شرد عنه بخذلانِهِ إلَّا منها؛ فالمُوفَّقُ يَسمعُ ويُبصِرُ ويتكلَّمُ ويبطش بمولاه، والمخذول يصدُر منه ذلك بنفسه وهواه.",2,50,"/edition/37/section/9179#page-57",17,15],["ما أخذ العبدُ ما حُرِّم عليه إلا من جهتين:\nإحداهُما: سوءُ ظنِّهِ بربِّهِ، وأنَّه لو أطاعَهُ وآثَرَهُ لم يُعطِهِ خيرًا منه حلالًا.\nوالثانيةُ: أن يكون عالِمًا بذلك، وأنَّ مَنْ تركَ لله شيئًا أعاضَهُ خيرًا منه، ولكن تغلِبُ شهوتُهُ صبَرهُ وهواهُ عقلَهُ.\nفالأولُ مِن ضَعْفِ علمِهِ، والثاني من ضَعْفِ عقلِهِ وبصيرتِهِ.",2,63,"/edition/37/section/9189#page-70",9,15],["العابد الجاهلُ آفتُهُ من إعراضه عن العلم وأحكامه وغلبة خياله وذوقه ووَجْدِه وما تهواه نفسه.",2,149,"/edition/37/section/9254#page-156",17,15],["العارفُ يعمل العمل لوجه الله، مشاهدًا فيه منته وفضلهُ وتوفيقه، معتذرًا منه إليه، مستحييًا منه إذ لم يُوفِّه حقَّهُ. والجاهل يعمل العمل لحظِّه وهواهُ، ناظرًا فيه إلى نفسه، يمُنُّ به على ربِّه، راضيًا بعمله.",2,225,"/edition/37/section/9310#page-232",17,15],["الشهقةُ التي تَعرِض عند سماع القرآن أو غيره لها أسبابٌ:\nأحدُها: أن يَلُوح له عند السماع درجةٌ ليست له، فيرتاح إليها، فتَحدُث له الشهقةُ؛ فهذه شهقة شوق.\nوثانيها: أن يَلُوح له ذنبٌ ارتكبه، فيشهَق خوفًا وحزنًا على نفسه، وهذه شهقة خشية.\nوثالثها: أن يلوح له نقصٌ فيه لا يَقدِرُ على دفعه عنه، فيُحدِث له ذلك حزنًا، فيشهَق شهقة حزن.\nورابعها: أن يلوح له كمال محبوبه، ويرى الطريق إليه مسدودةً عنه، فيُحدِث ذلك شهقَة أسفٍ وحزنٍ.\nوخامسها: أن يكون قد توارى عنه محبوبُهُ، واشتغل بغيره، فذكَّره السماعُ محبوبَه، فلاح له جماله، ورأى الباب مفتوحًا والطريق ظاهرةً، فشهق فرحًا وسرورًا بما لاح له.",2,286,"/edition/37/section/9375#page-293",274,15],["اللَّذةُ من حيث هي مطلوبة للإنسان بل ولكلِّ حيٍّ؛ فلا تُذَمُّ من جهة كونها لذَّةً، وإنما تُذَمُّ ويكون تركها خيرًا من نيلها وأنفعَ إذا تضمنتْ فَواتَ لذَّةٍ أعظمَ منها وأكملَ، أو أعقَبتْ ألمًا حصوله أعظم من ألم فواتها.",2,291,"/edition/37/section/9383#page-298",1024,15],["أن [الله] سُبحانه وعدَ المؤمنين بالنصر والظفر، وهي كلمتُه التي سبقت لهم، وهي الكلمة الحسنى، وأخبر أنه إنما نالهم بالصبر، فقال تعالى: ﴿وَتَمَّتْ كَلِمَتُ رَبِّكَ الْحُسْنَى عَلَى بَنِي إِسْرَائِيلَ بِمَا صَبَرُوا﴾ [الأعراف: ١٣٧].",5,133,"/edition/67/section/16038#page-177",1032,15],["الدنيا في الحقيقة لا تذم وإنما يتوجه الذم إلى فعل العبد فيها، وهي قنطرة ومعبر إلى الجنة أو النار. ولكن لما غلبت عليها الشهوات والحظوظ والغفلة والإعراض عن اللَّه والدار الآخرة، فصار هذا هو الغالب على أهلها وما فيها، وهو الغالب على اسمها، صار لها اسم الذم عند الإطلاق، وإلا فهي مبنى الآخرة ومزرعتها، ومنها زاد الجنة وفيها اكتسبت النفوس الإيمان ومعرفة اللَّه ومحبته وذكره ابتغاء مرضاته، وخير عيش ناله أهل الجنة في الجنة إنما كان بما زرعوه فيها.",5,331,"/edition/67/section/16051#page-375",2561,15],["قال رسول اللَّه ﷺ: «خير الرزق ما يكفي وخير الذكر الخفي».\nوتأمل جمعه في هذا الحديث بين رزق القلب والبدن: رزق الدنيا والآخرة، وإخباره أن خير الرّزقين ما لم يتجاوز الحد فيكفي من الذكر إخفاؤه، فإذا زاد على الإخفاء خيف على صاحبه الرياء والتكثر به على الغافلين، وكذلك رزق البدن إذا زاد على الكفاية خيف عليه الطغيان والتكاثر.",5,384,"/edition/67/section/16053#page-428",2208,15],["الميت قد انقطع عمله، فهو محتاج إلى من يدعو له ويشفع له، ولهذا شرع في الصلاة عليه من الدعاء له وجوبًا واستحبابًا ما لم يشرع مثله في الدعاء للحي.",7,365,"/edition/13/section/4318#page-406",384,15],["ومن أسمائه الحسنى: الجميل، ومن أحق بالجمال ممن كل جمال في الوجود فهو من آثار صنعته، فله جمال الذات، وجمال الأوصاف، وجمال الأفعال، وجمال الأسماء، فأسماؤه كلها حسنى، وصفاته كلها كمال، وأفعاله كلها جميلة، ولا يستطيع بشر النظر إلى جلاله وجماله في هذه الدار، فإذا رأوه سبحانه في جنات عدن أنستهم رؤيته ما هم فيه من النعيم، فلا يلتفتون حينئذ إلى شيء غيره، ولولا حجاب النور على وجهه لأحرقت سبحات وجهه ــ تبارك وتعالى ــ ما انتهى إليه بصره من خلقه.",9,568,"/edition/57/section/12879#page-594",1025,15],["فإياك أن تظن بظنك الفاسد أن شيئا من أقضيته وأقداره عار عن الحكمة البالغة، بل جميع أقضيته تعالى وأقداره واقعة على أتم وجوه الحكمة والصواب، ولكن العقول الخفاشية محجوبة بضعفها عن إدراكها، كما أن الأبصار الخفاشية محجوبة بضعفها عن ضوء الشمس، وهذه العقول الصغار إذا صادفها الباطل جالت فيه وصالت، ونطقت وقالت، كما أن الخفاش إذا صادفه ظلام الليل طار وسار.",11,722,"/edition/73/section/18176#page-822",1,15],["إذا ابتلى الله العبد بالذنب عرف به نفسه ونقصها، رتب له على ذلك التعريف حكم ومصالح عديدة:\nمنها: أنه يأنف من نقصها، ويجتهد في كمالها.\nومنها: أنه يعلم فقرها دائما إلى من يتولاها ويحفظها.\nومنها: أنه يستريح ويريح العباد من الرعونات والحماقات التي ادعاها أهل الجهل في أنفسهم، من قدم، أو اتصال بالقديم واتحاد به، أو حلول أو غير ذلك من المحالات؛ فلولا أن هؤلاء غاب عنهم شهودهم لنقص أنفسهم وحقيقتها لم يقعوا فيما وقعوا فيه.",11,823,"/edition/73/section/18202#page-923",18,15],["فتوبة العبد محفوفة بتوبة قبلها عليه من الله إذنا وتوفيقا، وتوبة ثانية منه عليه قبولا ورضا؛ فله الفضل في التوبة والكرم أولا وآخرا، لا إله إلا هو.",11,825,"/edition/73/section/18202#page-925",4,15],["والتوكُّل تارةً يكونُ توكُّلَ اضطرارٍ وإلْجَاءٍ؛ بحيثُ لا يَجدُ العبدُ مَلجأ ولا وَزَرًا إلا التوكُّلَ؛ كما إذا ضاقتْ عليه الأسبابُ، وضاقتْ عليه نفسُهُ، وظَنَّ أنْ لا ملجأ من الله إلَّا إليه، وهذا لا يَتخلَّفُ عنه الفَرَجُ والتيسيرُ البتَّةَ.",2,125,"/edition/37/section/9235#page-132",17,15],["\"إذا انكشف الغطاء للناس يوم القيامة عن ثواب أعمالهم لم يروا عملاً أفضل ثوابًا من الذكـر ،\nفيتحسر عند ذلك أقوام فيقولون : ما كان شىء أيسر علينا من الذكر \"",1,78,"/edition/41/section/9802#page-72",3200,15],["لمّا كان البدن المريض يؤذيه ما لا يُؤذي الصحيح من يسير الحرّ والبرد والحركة ونحو ذلك، فكذلك القلب إذا كان فيه مرض آذاه أدنى شيءٍ من الشبهة أو الشهوة، حيث لا يقدِر على دفعهما إذا وردا عليه، والقلب الصحيح القوي يطرقه أضعاف ذلك وهو يدفعه بقوته وصحته.",7,24,"/edition/13/section/4121#page-65",33,15],["الحاسدَ تُعِينُهُ الشياطينُ بلا استدعاء منه للشيطان؛ لأن الحاسد شبيهٌ بإبليس وهو في الحقيقة من أتباعه؛ لأنه يطلبُ ما يحبه الشيطان من فساد الناس وزوال نعم الله عنهم, كما أن إبليس حسد آدم لشَرَفَه وفضله, وأبى أن يسجدَ له حَسَدًا, فالحاسد من جند إبليس.",15,758,"/edition/44/section/10418#page-847",144,15],["اللهُ سبحانه وتعالى المسئُول المرجوُّ الإجابة أن يتولاكم في الدنيا والآخرة، وأن يُسْبِغ عليكم نعمه ظاهرة وباطنةً ، وأن يجعلكم ممن إذا أنْعَم الله عليه شكر، وإذا ابْتُلِيَ صبر، وإذا أذنب استغفر؛ فإن هذه الأمور الثلاثة هي عُنوان سعادة العبد، وعلامة فلاحه في دنياه وأخراه، ولا يَنْفَكُّ عبدٌ عنها أبدًا، فإنّ العبد دائمًا يتقلَّبُ بين هذه الأطباق الثلاث.",1,5,"/edition/42/section/9887#page-53",2058,15],["قال اليزيدي : دخلتُ على هارون الرشيد، فوجدته مُكبًّا على ورقةٍ ينظرُ فيها مكتوبةٍ بالذهب، فلما رآني؛ تبسم، فقلت: فائدةٌ أصلح الله أمير المؤمنين؟! قال: نعم وجدتُ هذين البيتين في بعض خزائن بني أُمية فاستحسنتهما، وقد أضفت إليهما ثالثًا، ثُمَّ أنشدني:\nإذا سدَّ بابٌ عنك من دون حاجةٍ\nفدعه لأخرى ينفتح لك بابها\nفإن قُراب البطن يكفيك ملؤُهُ\nويكفيك سوءات الأمور اجتنابُها\nفلا تك مبذالًا لدينك واجتنب\nركوب المعاصي يجتنبك عقابها",9,396,"/edition/56/section/12533#page-391",1030,15],["دَغَل القلب من الصِّفات المذمومة، التي تُوجِب ضيقَه وعذابه، وتحول بينه وبين حصول البُرْءِ، فإن العبد إذا أتى بالأسباب التي تَشرح صدره، ولم يُخرِج  تلك الأوصاف المذمومة من قلبه، لم يَحْظَ من انشراحِ صدره بطائلٍ، وغايتُه أن تكون له مادَّتانِ تَعتَوِران على قلبه، وهو للمادة الغالبة عليه منهما.",14,32,"/edition/59/section/14193#page-860",1056,15],["أَنَّ دُورَ الجنّة تُبْنَى بالذكر، فإذا أَمْسَكَ الذاكرُ عن الذكر أَمْسَكتِ الملائكةُ عن البناء، فإذا أَخَذَ في الذكر أخذوا في البناء.",1,191,"/edition/42/section/10002#page-239",2176,15],["الجهل بالطريق وآفاتها والمقصودِ يُوجب التعبَ الكثير مع الفائدة القليلة؛ فإن صاحبه إما أن يجتهد في نافلة مع إضاعة الفرض، أو في عمل بالجوارح لم يواطئه عمل القلب، أو عمل بالباطن والظاهر لم يتقيد بالاقتداء، أو همةٍ إلى عمل لم ترق بصاحبها إلى ملاحظة المقصود، أو عمل لم يحترز من أفاته المفسدة له حال العمل وبعده، أو عملٍ غفلَ فيه عن مشاهدة المنة فلم يتجرَّد عن مشاركة النفس فيه، أو عمل لم يشهد تقصيرهُ فيه فيقوم بعده في مقام الاعتذار منه، أو عمل لم يُوفِّه حقَّه من النصح والإحسان وهو يظنُّ أنه وفَّاه؛ فهذا كله مما ينقص الثمرة مع كثرة التعب. والله الموفق.",2,251,"/edition/37/section/9339#page-258",112,15],["مما ينبغي أن يعلم أن الذنوب تضر ولابد، وأن ضررها في القلوب؛ كضرر السموم في الأبدان، على اختلاف درجاتها في الضرر.",0,98,"/edition/20/section/6393#page-164",34,14],["العلم نور يقذفه الله في القلب، والمعصية تطفئ ذلك النور.",0,132,"/edition/20/section/6396#page-198",34,14],["كان من دعاء بعض السلف:\nاللهم أعِزَّني بطاعتك، ولا تُذِلَّني بمعصيتك.",0,146,"/edition/20/section/6407#page-212",130,14],["ومن عقوبات الذنوب:\nأنها تطفئ من القلب نارَ الغيرة التي هي لحياته وصلاحه كالحرارة الغريزية لحياة جميع البدن.",0,163,"/edition/20/section/6413#page-229",34,14],["فالغيرة تُحمي القلبَ، فتحمَى له الجوارحُ، فتدفع السوء والفواحش.",0,167,"/edition/20/section/6413#page-233",33,14],["إذا اشتدَّ قربُ الملك من العبد تكلّم على لسانه، وألقى على لسانه القولَ السديدَ.\nوإذا بعُدَ منه، وقرُبَ منه الشيطان، تكلّم على لسانه، وألقى عليه قول الزور والفحش، حتى ترى الرجلَ يتكلّم على لسانه الملَكُ، والرجلَ يتكلم على لسانه الشيطانُ.",0,252,"/edition/20/section/6447#page-318",16,14],["القلبُ لا تتم حياتُه إلا بغذاءٍ من الإيمان والأعمال الصالحة يحفظ قوته، واستفراغ بالتوبة النصوح يستفرغ المواد الفاسدة والأخلاط الرديئة منه، وحميةٍ تُوجِب له حفظ الصحة وتجنّب ما يضادها، وهي عبارة عن ترك استعمال ما يضاد الصحة.",0,257,"/edition/20/section/6448#page-323",36,14],["العقوبة الشرعية شرعها الله سبحانه على قدر مفسدة الذنب وتقاضي الطبع له، وجعلها سبحانه ثلاثة أنواع: القتل، والقطع، والجلد.\nوجعل القتل بإزاء الكفر وما يليه ويقرب منه، وهو الزنا واللواط، فإنّ هذا يفسد الأديان، وهذا يفسد الإنساب ونوع الإنسان.\nوجعل سبحانه القطعَ بإزاء إفساد الأموال الذي لا يمكن الاحتراز منه.\nوجعل الجَلْدَ بإزاء إفساد العقول وتمزيق الأعراض بالقذف.\nفدارت عقوباته سبحانه الشرعية على هذه الأنواع الثلاثة، كما دارت الكفارات على ثلاثة أنواع: العتق وهو أعلاها، والإطعام، والصيام.",0,261,"/edition/20/section/6452#page-327",3,14],["قيل: من حفظ هذه الأربعة أحرز دينَه: اللحظات، والخطرات، واللفظات، والخطوات.\nفينبغي للعبد أن يكون بوّاب نفسه على هذه الأبواب الأربعة، ويلازم الرباط على ثغورها، فمنها يدخل عليه العدوّ، فيجوس خلال الديار، ويتبّر ما عَلا تتبيرًا!",0,347,"/edition/20/section/6491#page-413",16,14],["وأخسُّ الناس همّة وأوضعهم نفسًا من رضي من الحقائق بالأماني الكاذبة، واستجلبها لنفسه، وتحلَّى بها، وهي -لعمر الله- رؤوس أموال المفلسين، ومتاجر البطّالين.\nوهي قوت النفس الفارغة التي قد قنعت من الوصل بزَورة الخيال، ومن الحقائق بكواذب الآمال.",0,354,"/edition/20/section/6493#page-420",16,14],["وشرف النفس وزكاتها وطهارتها وعلوّها بأن ينفي عنها كلَّ خطرة لا حقيقة لها، ولا يرضى أن يخطرها بباله، ويأنف لنفسه منها.",0,355,"/edition/20/section/6493#page-421",16,14],["العارف ابن وقته، فإن أضاعه ضاعت عليه مصالحه كلُّها. فجميع المصالح إنما تنشأ من الوقت، وإن ضيّعه لم يستدركه أبدًا.",0,358,"/edition/20/section/6493#page-424",64,14],["فوقت الإنسان: هو عمره في الحقيقة، وهو يمرّ أسرع من مرّ السحاب.\nفما كان من وقته لله وبالله، فهو حياته وعمره.\nوغير ذلك ليس محسوبًا من حياته، وإن عاش فيه عيش البهائم.",0,359,"/edition/20/section/6493#page-425",64,14],["التعلّق بالصور يوجب فساد العقل، وعَمَه البصيرة، وسُكْر القلب.",0,418,"/edition/20/section/6506#page-484",33,14],["أصل الشر من ضعف الإدراك، وضعف النفس ودناءتها.\nوأصل الخير من كمال الإدراك، وقوة النفس وشرفها وشجاعتها.",0,448,"/edition/20/section/6518#page-514",16,14],["الختام، دعاء وابتهال\n\nنسأل الله العظيم ربَّ العرش العظيم أن يجعلنا ممن آثر حبه على هواه، وابتغى بذلك قربه ورضاه.",0,573,"/edition/20/section/6559#page-639",129,14],["أدعية صلاة الجنازة\n-  «اللَّهُمَّ اغفر له وارحمه، وعافِهِ واعْفُ عنه، وأكْرِمْ نُزُلَه، وَوَسِّع مُدْخَلَه، واغسله بالماء والثلج والبرد، وَنَقِّهِ من الذنوب والخطايا كما نَقَّيْتَ الثوب الأبيض من الدَّنسِ، وأبدله دارًا خيرًا من أهله، وزوجًا خيرًا من زوجه، وأدخله الجنة، وأَعِذْهُ من عذاب القبر».\n- «اللَّهُمَّ اغفر لحيِّنا وميِّتنا، وشاهدنا وغائبنا، وصغيرنا وكبيرنا، وذكرنا وأنثانا، اللَّهُمَّ من أحييته منا، فَأَحْيهِ على الإسلام، ومن توفَّيته منا فَتَوفَّهُ على الإيمان، اللَّهُمَّ لا تحرمنَا أجره، ولا تُضِلنا بعده».\n- «اللَّهُمَّ إن فلان ابن فلان في ذمتك وحَبْلِ جِوارِك، فَقِهِ من فتنة القبر وعذاب النار، وأنت أهْلُ الوفاء والحمد، اللَّهُمَّ فاغفر له وارحمه، إنك أنت الغفور الرحيم».\n- «اللَّهُمَّ أنت ربُّها، وأنت خلقتَها، وأنت هديتها للإسلام، وأنت قبضت روحها، وأنت أعلم بسرها وعلانيتها، جئنا شفعاء فاغفر له».",1,386,"/edition/42/section/10080#page-432",2050,14],["يا مستفْتِحًا بابَ المعاشِ بغيرِ إقليدِ التَّقوى! كيفَ تُوسِعُ طريقَ الخطايا وتَشْكو ضِيقَ الرِّزْقِ؟!",2,69,"/edition/37/section/9190#page-76",1026,14],["مَن عرفَ نفسَه اشتغلَ بإصلاحها عن عُيوبِ الناس، ومن عرفَ ربَّهُ اشتغل به عن هوى نفسه.",2,80,"/edition/37/section/9203#page-87",16,14],["أخسرُ الناسِ صفقةً من اشْتَغَلَ عن الله بنفسِهِ، بل أخسرُ منه من اشْتَغَلَ عن نفسِهِ بالناس.",2,81,"/edition/37/section/9204#page-88",16,14],["أصول السعادة\n\nالأصولُ التي انبنَى عليها سعادةُ العبد ثلاثةٌ،\nولكل واحد منها ضدٌّ؛ فمن فقدَ ذلك الأصلَ حصلَ على ضدِّه:\nالتوحيدُ وضدُّه الشركُ،\nوالسنة وضدُّها البدعة،\nوالطاعة وضدُّها المعصيةُ.\nولهذه الثلاثة ضدٌّ واحدٌ، وهو:\nخُلوُّ القلب من الرغبة في الله وفيما عنده ومن الرهبة منه وممَّا عنده.",2,157,"/edition/37/section/9262#page-164",34,14],["لله سبحانه على عبده أمرٌ أمرَهُ به وقضاءٌ يقضيه عليه ونعمةٌ يُنْعِمُ بها عليه؛ فلا ينفكُّ من هذه الثلاثة، والقضاءُ نوعان:\nإمَّا مصائبُ وإما معايبُ، وله عليه عبوديةٌ في هذه المراتب كلِّها،\nفعبوديتُهُ في الأمر: امتثالُه إخلاصًا واقتداءً برسول الله ﷺ،\nوفي النهي: اجتنابُهُ خوفًا منه وإجلالًا ومحبَّةً.\nوعبوديتُهُ في قضاء المصايب: الصبرُ عليها، ثم الرِّضَى بها وهو أعلى منه، ثم الشكر عليها وهو أعلى من الرِّضى.\nوعبوديته في قضاء المعايب: المبادرة إلى التوبة منها والتنصُّل والوقوف في مقام الاعتذار والانكسار، عالمًا بأنه لا يرفعُها عنه إلا هو، ولا يَقِيه شرَّها سواه.\nوعبودية النِّعم: فمعرفتها والاعتراف بها أولًا، ثم العياذُ به أن يقع في قلبه نسبتُها وإضافتُها إلى سواه وإن كان سببًا من الأسباب؛ فهو مسبّبه ومقيمه، ثم الثناء بها عليه ومحبتُه عليها وشكره بأن يستعملها في طاعته.",2,163,"/edition/37/section/9266#page-170",556,14],["لا أنفعَ للعبد من امتثال الأمر، وإن شقَّ عليه في الابتداء؛ لأنَّ عواقبه كلها خيراتٌ ومسراتٌ ولذاتٌ وأفراح، وإن كرهته نفسه؛ فهو خيرٌ لها وأنفع.\nوكذلك لا شيء أضرٌ عليه من ارتكاب النهي، وإن هَوِيتْه نفسه ومالت إليه؛ فإن عواقبه كلها آلامٌ وأحزانٌ وشرورٌ ومصائبُ.",2,199,"/edition/37/section/9290#page-206",16,14],["العزيمة والمحبة تُذهِب المشقة وتُطيِّب السيرَ، والتقدمُ والسبقُ إلى الله سبحانه إنما هو بالهمم وصدق الرغبة والعزيمة، فيتقدمُ صاحبُ الهمة مع سكونه صاحبَ العمل الكثير بمراحل؛ فإن ساواه في همته تقدم عليه بعمله.",2,207,"/edition/37/section/9298#page-214",1536,14],["الدراهم أربعةٌ:\nدرهمٌ اكتُسِبَ بطاعة الله وأُخرِج في حقِّ الله؛ فذاك خير الدراهم،\nودرهم اكتُسِب بمعصية الله وأُخرج في معصية الله؛ فذاك شر الدراهم،\nودرهم اكتُسِب بأذى مسلم وأخرج في أذى مسلم؛ فهو كذلك،\nودرهم اكتسب بمباح وأُنفق في شهوة مباحة؛ فذاك لا له ولا عليه.\nهذه أصول الدراهم، ويَتفرَّعُ عليها دراهمُ أُخر؛ منها:\nدرهم اكتُسِب بحق وأُنفِق في باطل.\nودرهم اكتُسِب بباطل وأنفق في حق؛ فإنفاقه كفارته.\nودرهم اكتُسِب من شبهة؛ فكفارته أن ينفق في طاعة.",2,249,"/edition/37/section/9335#page-256",2,14],["المواساةُ للمؤمنين أنواعٌ:\nمواساةٌ بالمال، ومواساةٌ بالجاه، ومواساةٌ بالبدن والخدمة، ومواساةٌ بالنصيحة والإرشاد، ومواساة بالدعاء والاستغفار لهم، ومواساةٌ بالتوجع لهم.\nوعلى قدر الإيمان تكون هذه المواساة؛ فكلما ضَعُفَ الإيمان ضعفت المواساةُ، وكلما قوي قويتْ.",2,250,"/edition/37/section/9337#page-257",132,14],["النعم ثلاثةٌ:\nنعمة حاصلة يعلم بها العبد، ونعمةٌ منتظرةٌ يرجوها، ونعمةٌ هو فيها لا يَشعُر بها.\nفإذا أراد الله إتمام نعمته على عبده عرَّفَه نعمتَه الحاضرة وأعطاه من شكره قيدًا يُقيِّدُها به حتى لا تَشرُد؛ فإنها تَشرد بالمعصية وتُقيَّدُ بالشكر.\nووفقه لعمل يستجلب به النعمة المنتظرة، وبصَّره بالطرق التي تسُدُّها وتقطع طريقها ووفَّقه لاجتنابها، وإذا بها قد وافتْ إليه على أتم الوجوه.\nوعرَّفه النعمَ التي هو فيها ولا يشعر بها.",2,252,"/edition/37/section/9341#page-259",3,14],["الهجرة هجرتان:\nهجرة بالجسم من بلد إلى بلد.\nوالهجرة الثانية هجرةٌ بالقلب إلى الله ورسوله، وهذه الهجرةُ هي الهجرة الحقيقية، وهي الأصل، وهجرة الجسدِ تابعةٌ لها، فيهاجرُ بقلبه من محبة غير الله إلى محبته.\nومن عبوديةِ غيره إلى عبوديته.\nومن خوفِ غيرِه ورجائِه والتوكلِ عليه إلى خوفِ الله ورجائِه والتوكلِ عليه.\nومن دعاء غيرِه وسؤالِه والخضوع له والذُّلِّ له والاستكانةِ له إلى دُعاءِ ربِّه وسؤالِه والخضوعِ له والذلِّ والاستكانةِ له، وهذا هو بعينه معنى الفرار إليه.",3,16,"/edition/23/section/6805#page-31",672,14],["الفرح والسرور، وطيب العيش، والنعيم، إنما هو في معرفة الله، وتوحيده والأُنْس به، والشوق إلى لقائه، واجتماع القلب والهمِّ عليه.",4,29,"/edition/52/section/12328#page-24",1056,14],["اللَّه تعالى له على عبده حكمان: حكم شرعي ديني، وحكم كوني قدري؛ فالشرعي متعلق بأمره، والكوني متعلق بخلقه، وحكمه الديني الطلبي نوعان بحسب المطلوب، فإنّ المطلوب إنْ كان محبوبًا له فالمطلوب فعله إما وجوبًا وإما استحبابًا، ولا يتم ذلك إلا بالصبر، وإن كان مبغوضًا له فالمطلوب تركه إما تحريمًا وإما كراهة، وذلك أيضًا موقوف على الصبر. وأما حكمه الكوني القدري فهو ما يقضيه ويقدِّره على العبد من المصائب التي لا صنع له فيها، ففرضه الصبر عليها.",5,28,"/edition/66/section/15991#page-266",8,14],["حقيقة الصبر مع اللَّه: هو ثبات القلب بالاستقامة معه، لا يروغ عنه روغان الثعالب هاهنا وهاهنا، فحقيقة هذا الاستقامة إليه وعكوف القلب عليه.",5,87,"/edition/67/section/16029#page-131",40,14],["البلاء في الحقيقة ليس إلا الذنوب وعواقبها، والعافية المطلقة هي الطاعات وعواقبها؛ فأهل البلاء هم أهل المعصية وإن عوفيت أبدانهم، وأهل العافية هم أهل الطاعة وإن مرضت أبدانهم.",5,105,"/edition/67/section/16033#page-149",2,14],["معاصي اللسان فاكهة الإنسان؛ كالنميمة، والغيبة، والكذب، والمراء، والثناء على النفس تعريضًا وتصريحًا، وحكاية كلام الناس، والطعن على من يبغضه، ومدح من يحبه ونحو ذلك، فتتفق قوة الداعي وتيسر حركة اللسان، فيضعف الصبر، ولهذا قال ﷺ لمعاذ: «أمسك عليك لسانك». فقال: وإنا لمؤاخذون بما نتكلم به؟ فقال: «وهل يكبّ الناس في النار على مناخرهم إلا حصائد ألسنتهم؟!».",5,126,"/edition/67/section/16037#page-170",2072,14],["ليس الصبر بالتجلد، وإنما هو حبس القلب عن التسخط على المقدور، واللسان عن الشكوى، فمن تجلد وقلبه ساخط على القدر، فليس بصابر.",5,184,"/edition/67/section/16040#page-228",40,14],["قال أبو العالية: «إني لأرجو أن لا يهلك عبد بين اثنتين: نعمة يحمد اللَّه عليها، وذنب يستغفر منه».",5,246,"/edition/67/section/16048#page-290",6,14],["جميع الأمم المكذبة لأنبيائهم إنما حملهم على كفرهم وهلاكهم حب الدنيا، فإن الرسل لما نهوهم عن الشرك والمعاصي التي كانوا يكتسبون بهما الدنيا، حملهم حبها على مخالفتهم وتكذيبهم، فكل خطيئة في العالم أصلها حب الدنيا.",5,425,"/edition/67/section/16053#page-469",2,14],["إذا لهى القلب عن ذكر الله سكنه الشيطان وصرفه حيث أراد.",5,426,"/edition/67/section/16053#page-470",176,14],["«قل: اللهم عالِمَ الغيب والشهادة! فاطر السماوات والأرض! ربَّ كل شيء ومليكَه! أشهد أن لا إله إلا أنت؛ أعوذ بك من شر نفسي، ومن شر الشيطان وشِرْكه، وأن أقترف على نفسي سوءًا، أو أجُرّه إلى مسلم. قله إذا أصبحت، وإذا أمسيت، وإذا أخذت مضجعك».\nفقد تضمن هذا الحديث الشريف الاستعاذة من الشر وأسبابه وغايته: فإن الشر كله إما أن يصدر من النفس أو من الشيطان، وغايته: إما أن تعود على العامل، أو على أخيه المسلم، فتضمن الحديث مصدري الشر اللذين يصدر عنهما، وغايتيه اللتين يصل إليهما.",7,156,"/edition/13/section/4213#page-197",16,14],["المعصية تُبدي السوأة الباطنة والظاهرة، ولهذا رأى النبي ﷺ في رؤياه الزناة والزواني عراةً باديةً سوآتُهم.\nوهكذا إذا رُئيَ الرجل أو المرأة في منامه مكشوف السوأة، فإنه يدل على فساد دينه.",7,195,"/edition/13/section/4227#page-236",3,14],["من خواص [الغناء]: أنه يلهي القلب ويصده عن فهم القرآن وتدبره، والعمل بما فيه؛ فإن القرآن والغناء لا يجتمعان في القلب أبدًا؛ لما بينهما من التضاد.",7,439,"/edition/13/section/4353#page-480",288,14],["الزُّهد خمسةُ أقسام: زهدٌ في الدُّنيا، وزهدٌ في النَّفس، وزهدٌ في الجاه والرِّئاسة، وزهدٌ فيما سوى المحبوب، وزهدٌ في كلِّ إرادةٍ تُخالف مُراد المحبوب، وهذا إنَّما يحصلُ بكمال المُتابعة لرسول الحبيب.",9,266,"/edition/56/section/12527#page-262",528,14],["محبُّ الله ورسوله يغار لله ورسوله على قدر محبَّته وإجلاله، وإذا خلا قلبُه من الغيرة لله ورسوله فهو من المحبة أخلى، وإن زعم أنَّه من المُحبِّين، فكذب من ادَّعى محبَّة محبوبٍ من الناس، وهو يرى غيره ينتهكُ حُرمة محبوبه، ويسعى في أذاه ومساخطه، ويستهين بحقِّه، ويستخفُّ بأمره، وهو لا يغار لذلك، بل قلبه باردٌ، فكيف يصحُّ لعبدٍ أن يدَّعي محبَّة الله؛ وهو لا يغارُ لمحارمه إذا انْتُهِكت، ولا لحقوقه إذا ضُيِّعت.",9,385,"/edition/57/section/12795#page-411",544,14],["العادة قد تقوى حتى تغلب حكم الطبيعة، ولهذا قيل: «هي طبيعة ثانية»؛ فيربى الرجل على المقالة وينشأ عليها صغيرا، فيتربى قلبه ونفسه عليها كما يتربى لحمه وعظمه على الغذاء المعتاد، ولا يعقل نفسه إلا عليها، ثم يأتيه العلم وهلة واحدة يريد إزالتها وإخراجها من قلبه وأن يسكن موضعها، فيعسر عليه الانتقال، ويصعب عليه الزوال.",11,98,"/edition/72/section/17746#page-96",48,14],["دلت الشريعة وحكم الله على أن من حبي بالإنعام، وخص بالفضل والإكرام، ثم أسام نفسه مع همل الشهوات، فأرتعها في مراتع الهلكات، وتجرأ على انتهاك الحرمات، واستخف بالتبعات والسيئات، أنه يقابل من الانتقام والعتب بما لا يقابل به من ليس في مرتبته.",11,503,"/edition/73/section/18075#page-603",19,14],["النعم ثلاثةٌ: نعمة حاصلة يعلم بها العبد، ونعمةٌ منتظرةٌ يرجوها، ونعمةٌ هو فيها  لا يَشعُر بها.\nفإذا أراد الله إتمام نعمته على عبده عرَّفَه نعمتَه الحاضرة وأعطاه من شكره قيدًا يُقيِّدُها به حتى لا تَشرُد؛ فإنها تَشرد بالمعصية وتُقيَّدُ بالشكر. ووفقه لعمل يستجلب به النعمة المنتظرة، وبصَّره بالطرق التي تسُدُّها وتقطع طريقها ووفَّقه لاجتنابها، وإذا بها قد وافتْ إليه على أتم الوجوه. وعرَّفه النعمَ التي هو فيها ولا يشعر بها.\nويُحكى أن أعرابيًّا دخل على الرشيد، فقال: أمير المؤمنين! ثبَّتَ الله عليك النعمَ التي أنت فيها بإدامة شكرها، وحقَّق لك النعمَ التي ترجوها بحسن الظن به ودوام طاعته، وعرَّفك النعمَ التي أنت فيها ولا تَعرِفها لتشكرها. فأعجبه ذلك منه وقال: ما أحسنَ تقسيمَه!",2,252,"/edition/37/section/9341#page-259",3,14],["* مَن علتْ هِمتهُ وخَشعتْ نَفسهُ .\nاتّصف بِكُل خلقٍ جميل .\n\n* وَمن دنت همته ، وطغت نَفسه .\nاتّصف بِكُل خلق رذيل .",2,210,"/edition/37/section/9302#page-217",16,14],["العجب ممن تَعرِضُ له حاجةٌ، فيَصْرِفُ رغبتَه وهمتَه فيها إلى الله ليقضيها له، ولا يَتصدَّى للسؤال لحياة قلبه من موت الجهل والإعراض، وشفائه من داء الشهوات والشبهات! ..",2,163,"/edition/37/section/9266#page-170",33,14],["الذكر شجرةٌ  تُثْمِر المعارف والأحوال التي شمَّر إليها السالكون، فلا سبيل إلى نيل ثمارها إلا من شجرة الذكر، وكلما عظمت تلك الشجرة ورسخ أصلها كان أعظم لثمرتها، فالذكر يثمر المقامات كلَّها، مِنَ اليقظة إلى التوحيد، وهو أصل كل مقام، وقاعدته التي ينبني ذلك المقام عليها، كما يُبْنَى الحائط على أُسِّه، وكما يقوم السقف على حائطه، وذلك أن العبد إن لم يستيقظ لم يُمْكِنْه قطع منازل السير، ولا يستيقظ إلا بالذكر كما تقدم، فالغفلة نومُ القلب أو موتُه.",1,157,"/edition/42/section/9981#page-205",160,14],["بحسب قيام العبد بالأمر تُدفع عنه جيوش الشهوة، كما قال تعالى: (إنَّ الصَّلاة تنهى عن الفحشاء والمنكر) [العنكبوت: 45]، وقال تعالى: (إنَّ الله يدافع عن الذِينَ آمنُوا) [الحج: 38]، وفي القراءة الأخرى (يدفَعُ)، فكمال الدفع والمدافعة بحسب قوة الإيمان وضعفه.",12,40,"/edition/64/section/15625#page-30",257,14],["القلوب المتعلقة بالشهوات محجوبة عن الله بقدر تعلقها بها .",2,142,"/edition/37/section/9249#page-149",33,14],["وكان من هديه - صلى الله عليه وسلم - في شهر رمضان الإكثارُ من أنواع العبادات،  وكان جبريل يدارسه القرآنَ في رمضان، وكان إذا لقيه جبريل أجودَ بالخير من الرِّيح المرسلة، وكان أجود النَّاس، وأجود ما يكون في رمضان ، يكثر فيه من الصَّدقة والإحسان وتلاوة القرآن والصَّلاة والذِّكر والاعتكاف.\nوكان يخصُّ رمضان من العبادة بما لا يخصُّ به غيره من الشُّهور..",14,37,"/edition/59/section/14196#page-865",385,14],["عن أبي الدرداء:\nاعبدوا الله كأنكم ترونه، وعُدُّوا أنفسَكم في الموتى، واعلموا أنّ قليلًا يُغنيكم خير من كثير يُلهيكم. واعلموا أن البِرَّ لا يبلى، وأن الإثم لا يُنسى.",0,131,"/edition/20/section/6395#page-197",2050,13],["ولا تزال الخطرات تتردّد على القلب حتى تصير مُنًى باطلة.",0,353,"/edition/20/section/6493#page-419",48,13],["أنواع المحبة\nأحدها: محبة الله. ولا تكفي وحدها في النجاة من عذابه والفوز بثوابه.\nالثاني: محبة ما يحبه الله. وهذه هي التي تُدخله في الإسلام، وتُخرجه من الكفر.\nالثالث: الحب لله وفيه. وهي من لوازم محبة ما يحب، ولا يستقيم محبة ما يحب إلا بالحب فيه وله.\nالرابع: المحبة مع الله. وهي المحبة الشركية، وكل من أحب شيئًا مع الله، لا لله ولا من أجله ولا فيه، فقد اتخذه ندًّا من دون الله، وهذه محبة المشركين.\nوقسم خامس: المحبة الطبعية، وهي ميل الإنسان إلى ما يلائم طبعه، كمحبة العطشان للماء، والجائع للطعام، ومحبة النوم والزوجة والولد. فتلك لا تُذَمّ إلا إذا ألهَتْ عن ذكر الله وشغلتْ عن محبته.",0,444,"/edition/20/section/6515#page-510",640,13],["وإذا كان كثير من المرضى يحميه الطبيب عما يضرّه، فتأبى عليه نفسه وشهوته إلا تناولَه، ويقدّم شهوته على عقله، وتسميه الأطباء «عديم المروءة»؛ فهكذا أكثر مرضى القلوب يؤثرون ما يزيد مرضَهم لقوة شهوتهم له.",0,448,"/edition/20/section/6518#page-514",48,13],["أنفع المحبة على الإطلاق وأوجَبها وأعلاها وأجلّها محبةُ مَن جُبلت القلوب على محبته، وفطرت الخليقة على تألّهه.",0,532,"/edition/20/section/6541#page-598",544,13],["العبد بُلِي بالغفلة والشهوة والغضب، ودخول الشيطان على العبد من هذه الأبواب الثلاثة.",1,8,"/edition/42/section/9879#page-3",17,13],["الذاكر المجاهد أفضل من الذاكر بلا جهادٍ والمجاهدِ الغافلِ، والذاكرُ بلا جهادٍ أفضلُ من المجاهد الغافل عن الله تعالى.\nفأفضل الذاكرين المجاهدون، وأفضل المجاهدين الذاكرون.",1,88,"/edition/42/section/9933#page-136",128,13],["القلب يصدأ كما يصدأ النحاس والفضة وغيرهما، وجلاؤه بالذكر، فإنه يجلوه حتى يدعه كالمرآة البيضاء؛ فإذا تُرِك الذكرُ صَدِئ؛ فإذا ذُكِر جلاه.",1,92,"/edition/42/section/9936#page-140",160,13],["فمحبةُ الله تعالى، ومعرفته، ودوام ذكره، والسكون إليه، والطمأنينة إليه، وإفراده بالحب، والخوف، والرجاء، والتوكل، والمعاملة، بحيث يكون هو وحده المستولي على هموم العبد وعزماته وإرادته = هو جَنَّةُ الدنيا، والنعيم الذي لا يشبهه نعيم، وهو قرة عين المُحِبّين، وحياة العارفين.",1,111,"/edition/42/section/9967#page-159",1536,13],["الذِّكر نورٌ للذاكر في الدنيا، ونورٌ له في قبره، ونورٌ له في معاده، يسعى بين يديه على الصراط، فما استنارت القلوب والقبور بمثل ذكر الله تعالى.",1,114,"/edition/42/section/9969#page-162",160,13],["الذكر أفضل من الدعاء؛ لأن الذكر ثناءٌ على الله عز وجل بجميل أوصافه وآلائه وأسمائه، والدعاءُ سؤال العبد حاجته.",1,222,"/edition/42/section/10015#page-270",128,13],["الدعاء الذي يَتَقدَّمه الذكر والثناء أفضل وأقرب إلى الإجابة من الدعاء المجرد، فإِن انضاف إلى ذلك إخبار العبد بحاله ومسكنته، وافتقاره واعترافه كان أبلغ في الإجابة وأفضل.",1,225,"/edition/42/section/10016#page-273",128,13],["خمسُ سُنَنٍ في الأذان:\n- إجابتُه.\n- وقولُ: رضيت بالله ربًّا، وبالإسلام دينًا، وبمحمد ﷺ رسولًا، حين يسمع التشهد.\n- وسؤالُ الله تعالى لرسوله ﷺ الوسيلة والفضيلة.\n- والصلاةُ عليه ﷺ.\n- والدعاءُ لنفسه ما شاء.",1,268,"/edition/42/section/10027#page-314",400,13],["جمعَ النبيُّ ﷺ بين تقوى الله وحُسْنِ الخُلُقِ؛ لأنَّ تقوى الله تُصلِحُ ما بين العبد وبين ربِّه، وحسنُ الخُلُقِ يُصْلِحُ ما بينه وبين خلقِهِ؛ فتقوى الله تُوجِبُ له محبةَ الله، وحُسْنُ الخُلُقِ يدعو الناس إلى محبَّتِهِ.",2,76,"/edition/37/section/9200#page-83",640,13],["دخل الناسُ النارَ من ثلاثة أبوابٍ: باب شبهةٍ أورثتْ شكًّا في دين الله، وباب شهوةٍ أورثتْ تقديمَ الهوى على طاعتِه ومرضاتِه وباب غضبٍ أورثت العدوان على خلقه.",2,80,"/edition/37/section/9203#page-87",2049,13],["لا يستقيم الزُّهدُ في الدُّنيا إلا بعد نظرين صحيحين:\nنظرٌ في الدُّنيا وسرعةِ زوالها وفنائها واضمحلالها ونقصها وخِسَّتها.\nالنظرُ الثاني في الآخرة، وإقبالِها ومجيئها ولا بُدَّ، ودوامِها وبقائها، وشرفِ ما فيها من الخيرات والمسرَّات، والتفاوت الذي بينه وبين ما ها هنا.",2,136,"/edition/37/section/9244#page-143",2049,13],["للقلب ستة مواطنَ يجولُ فيها لا سابعَ لها؛\nثلاثةٌ سافلة، وثلاثةٌ عاليةٌ. فالسافلةُ:\nدنيا تتزيَّنُ له، ونفسٌ تحدِّثُه، وعدوٌّ يوسوسُ له.\nفهذه مواطنُ الأرواح السافلة التي لا تزالُ تجولُ فيها.\nوالثلاثة العاليةُ:\nعلمٌ يتبيَّنُ له، وعقلٌ يرشدُه، وإلهٌ يعبدُه.\nوالقلوب جوَّالةٌ في هذه المواطن.",2,144,"/edition/37/section/9251#page-151",48,13],["الخطرات والوساوس تُؤدِّي متعلقاتُها إلى الفكر، فيأخذها الفكر فيؤدِّيها إلى التذكُّر، فيأخذها الذِّكر فيؤدِّيها إلى الإرادة، فتأخذها الإرادة فتؤدِّيها إلى الجوارح والعمل، فتستحكم فتصير عادة، فردُّها من مبادئها أسهلُ من قطعها بعد قوتها وتمامها.",2,254,"/edition/37/section/9341#page-261",144,13],["التعب بالطاعة ممزوج بالحسن، مثمرٌ للذَّة والراحة؛ فإذا ثقلتْ على النفس ففكِّرْ في انقطاع تعبها وبقاء حسنها ولذَّتها وسرورها، ووازِنْ بين الأمرين، وآثرِ الراجحَ على المرجوح.",2,279,"/edition/37/section/9368#page-286",1040,13],["الزهد في الدنيا ملك حاضر، والشيطان يحسد المؤمن عليه أعظم حسد، فيحرص كل الحرص على أن لا يصل إليه، فإن العبد إذا ملك شهوته وغضبه فانقادا معه لداعي الدين فهو الملك حقًّا؛ لأن صاحب هذا الملك حرٌّ، والمَلِك المنقاد لشهوته وغضبه عبد شهوته وغضبه، فهو مسخَّر مملوك في زي مالك، يقوده زمام الشهوة والغضب، كما يقاد البعير.",5,112,"/edition/67/section/16033#page-156",17,13],["مات ابن لبعض قضاة البصرة، فاجتمع إليه العلماء والفقهاء، فتذاكروا ما يتبين به جزع الرجل من صبره، فأجمعوا: أنه إذا ترك شيئا مما كان يصنعه فقد جزع.",5,528,"/edition/67/section/16057#page-572",9,13],["قال ابن مسعود رضي الله عنه: «الغناء ينبت النفاق في القلب كما ينبت الماء الزرع، والذكر ينبت الإيمان في القلب كما ينبت الماء الزرع».",7,437,"/edition/13/section/4353#page-478",160,13],["المحبة النافعة ثلاثة أنواع: محبة الله، ومحبة في الله، ومحبة ما يعين على طاعة الله تعالى واجتناب معصيته.",7,865,"/edition/13/section/4670#page-906",514,13],["فتنة الشبهات: تدفع باليقين، وفتنة الشهوات: تدفع بالصبر.",7,903,"/edition/13/section/4782#page-944",9,13],["سعادةُ العبد وكمالُ لذّته ونعيمه موقوفًا على هذه المقامات الخمسة: علمه بالنعيم المطلوب، ومَحبّته له، وعلمه بالطريق الموصل إليه، وعمله به، وصبره على ذلك.",7,923,"/edition/13/section/4829#page-964",1544,13],["أن المحبة كلما تمكنت في القلب ورسخت فيه كان أذى المحب في رضا محبوبه مستحلى غير مسخوط، والمحبون يفتخرون عند أحبابهم بذلك، فما الظن بمحبة المحبوب الأعلى، الذي ابتلاؤه لحبيبه رحمة منه له وإحسان إليه؟",7,934,"/edition/13/section/4863#page-975",544,13],["لمَّا سَمَتْ هِمَّةُ الصِّدَّيق إلى تكميل مراتب الإيمان، وطمعت نفسه أنْ يُدْعَى من تلك الأبواب كلَّها، فسأل رسول الله ﷺ هل يحصل ذلك لأحد من النَّاس، ليسعى في العمل الَّذي ينال به ذلك، فأخبره بحصوله وبشَّره بأنَّه من أهله، فكأنَّهُ قال: هل يكمل أحد هذه المراتب فيُدعى يوم القيامة من أبوابها كلها؟\nفلِلَّهِ ما أعلى هذه الهمَّة، وأكبر هذه النَّفس.",8,222,"/edition/51/section/12201#page-274",3088,13],["وداعي الحبِّ من المحبوب جمالُه، إمَّا الظاهرُ أو الباطنُ أو هما معًا، فمتى كان جميلَ الصُّورة، جميلَ الأخلاق والشِّيم والأوصاف؛ كان الدَّاعي منه أقوى.",9,143,"/edition/57/section/12660#page-169",513,13],["أقسام اللذات ثلاثة:\nلذة جثمانية، ولذة خيالية وهمية، ولذة عقلية روحانية.",9,245,"/edition/57/section/12709#page-271",1024,13],["الجمال ينقسمُ قسمين: ظاهر وباطن، والجمال هو المحبوب لذاته، وهو جمال العلم، والعقل، والجود، والعفَّة، والشجاعة، وهذا الجمال الباطن هو محل نظر الله من عبده وموضع محبته، كما في الحديث الصحيح: «إن الله لا ينظر إلى صوركم، وأموالكم، ولكن ينظر إلى قلوبكم وأعمالكم».",9,221,"/edition/56/section/12525#page-217",513,13],["الهوى ثلاثة أرباع الهوان، وهو شارع النار الأكبر، كما أن مخالفته شارع الجنة الأعظم.",9,549,"/edition/57/section/12867#page-575",2049,13],["مخالفة الهوى توجب شرف الدنيا، وشرف الآخرة، وعز الظاهر، وعز الباطن، ومتابعته تضع العبد في الدنيا والآخرة، وتذله في الظاهر وفي الباطن.",9,648,"/edition/57/section/12912#page-674",2049,13],["وللإقبالِ في الصلاة ثلاثُ منازلَ:\nإقبالٌ على قلبه، فيحفظه من الوساوس والخطراتِ المبطلةِ لثواب صلاته أو المُنقِصَة له.\nوإقبالٌ على الله بمراقبتِه حتى كأنه يراه.\nوإقبالٌ على معاني كلامه وتفاصيل عبوديةِ الصلاة ليُعطِيها حقَّها.\nفباستكمالِ هذه المراتب الثلاث تكون إقامةُ الصلاة حقًّا، ويكون إقبالُ الله على عبده بحسب ذلك.",10,146,"/edition/38/section/9517#page-207",304,13],["قال أبو عثمان النيسابوري: من أمَّر السنةَ على نفسه قولًا وفعلًا نطق بالحكمة، ومن أمَّر الهوى على نفسه قولًا وفعلًا نطق بالبدعة.",10,198,"/edition/38/section/9562#page-258",17,13],["لما كان طلب العلم والبحث عنه وكتابته والتفتيش عليه من عمل القلب والجوارح كان من أفضل الأعمال، ومنزلته من عمل الجوارح كمنزلة أعمال القلب من الإخلاص والتوكل والمحبة والإنابة والخشية والرضا ونحوها من الأعمال الظاهرة.",11,511,"/edition/73/section/18076#page-611",548,13],["العبد متى شهد صلاحه واستقامته شمخ بأنفه وتعاظمت إليه نفسه، وظن أنه ... وأنه ...، فإذا ابتلي بالذنب تصاغرت إليه نفسه، وذل وخضع، وتيقن أنه ... وأنه ... !",11,822,"/edition/73/section/18202#page-922",18,13],["وهل زالت عن أحدٍ قطُّ نعمةٌ إلا بشؤم معصيته, فإنَّ الله إذا أنعم على عبد بنعمة حفظها عليه, ولا يغيِّرُها عنه حتى يكونَ هو السَّاعيَ في تغييرها عن نفسه: {إِنَّ اللَّهَ لا يُغَيِّرُ مَا بِقَوْمٍ حَتَّى يُغَيِّرُوا مَا بِأَنْفُسِهِمْ وَإِذَا أَرَادَ اللَّهُ بِقَوْمٍ سُوءاً فَلا مَرَدَّ لَهُ وَمَا لَهُمْ مِنْ دُونِهِ مِنْ وَالٍ (١١)} [الرعد: ١١].",15,712,"/edition/44/section/10405#page-801",18,13],["\"فبكمال العقل والصبر تُدفع فتنة الشهوة، وبكمال البصيرة واليقين تُدفع فتنة الشبهة\".",7,905,"/edition/13/section/4784#page-946",9,13],["الذكر يعطي الذاكر قوة حتى إنه ليفعل مع الذكر ما لا يطيق فعله بدونه.",1,185,"/edition/42/section/9999#page-233",128,13],["من أعطي منشور الدعاء أعطي الإجابة ، فإنه لو لم يرد إجابته لما ألهمه دعاءه ... ولايستوحش من ظاهر الحال ، فإن الله يعامل عبده بمعاملة من ليس كمثله شيء في أفعاله ، كما أنه ليس كمثله شيء في صفاته ، فإنه ماحرمه إلا ليعطيه ، ولا أمرضه إلا ليشفيه ، ولا أفقره إلا ليغنيه .",5,109,"/edition/67/section/16033#page-153",1152,13],["وأما محبّة النِّسْوان فلا لوم على المحِبّ فيها، بل هي من كماله .\nوقد امتن الله سبحانه بها على عباده فقال: {وَمِنْ آيَاتِهِ أَنْ خَلَقَ لَكُمْ مِنْ أَنْفُسِكُمْ أَزْوَاجًا لِتَسْكُنُوا إِلَيْهَا وَجَعَلَ بَيْنَكُمْ مَوَدَّةً وَرَحْمَةً إِنَّ فِي ذَلِكَ لَآيَاتٍ لِقَوْمٍ يَتَفَكَّرُونَ (21)} [الروم: 21]. فجعل المرأة سكنًا للرجل يسكن قلبه إليها، وجعل بينهما خالص الحبّ، وهو المودة المقترنة بالرحمة.",0,552,"/edition/20/section/6553#page-618",544,13],["لا يجتمع الإخلاص في القلب ومحبَّة المدحَ والثناء والطمع فيما عند الناس إلَّا كما يجتمع الماء والنار، والضبُّ والحوت، فإذا حدَّثتك نفسك بطلب الإخلاص فأَقْبِلْ على الطمع أوَّلًا فاذبحه بسكِّين اليأس، وأَقْبِلْ على المدح والثناء فازهد فيهما زُهْدَ عُشَّاق الدنيا في الآخرة، فإذا استقام لك ذبحُ الطمع، والزهد في الثناء والمدح سَهُلَ عليك الإخلاص.",2,219,"/edition/37/section/9305#page-226",2080,13],[".\n\nوَالْقَلْبُ: خُلِقَ لِمَعْرِفَةِ فَاطِرِهِ وَمَحَبَّتِهِ وَتَوْحِيدِهِ وَالسُّرُورِ بِهِ، وَالِابْتِهَاجِ بِحُبِّهِ، وَالرِّضَى عَنْهُ، وَالتَّوَكُّلِ عَلَيْهِ، وَالْحُبِّ فِيهِ، وَالْبُغْضِ فِيهِ، وَالْمُوَالَاةِ فِيهِ، وَالْمُعَادَاةِ فِيهِ، وَدَوَامِ ذِكْرِهِ، وَأَنْ يَكُونَ أَحَبَّ إِلَيْهِ مِنْ كُلِّ مَا سِوَاهُ، وَأَرْجَى عِنْدَهُ مِنْ كُلِّ مَا سِوَاهُ، وَأَجَلَّ فِي قَلْبِهِ مِنْ كُلِّ مَا سِوَاهُ، وَلَا نَعِيمَ لَهُ وَلَا سُرُورَ وَلَا لَذَّةَ بَلْ وَلَا حَيَاةَ إِلَّا بِذَلِكَ، وَهَذَا لَهُ بِمَنْزِلَةِ الْغِذَاءِ، وَالصِّحَّةِ، وَالْحَيَاةِ، فَإِذَا فَقَدَ غِذَاءَهُ، وَصِحَّتَهُ، وَحَيَاتَهُ؛ فَالْهُمُومُ وَالْغُمُومُ وَالْأَحْزَانُ مُسَارِعَةٌ مِنْ كُلِّ صَوْبٍ إِلَيْهِ، وَرَهْنٌ مُقِيمٌ عَلَيْهِ.\n\n.",14,185,"/edition/58/section/13622#page-1695",1568,13],["ذكر الله عز وجل يُذْهِب عن القلب مَخَاوِفَه كلَّها، وله تأثير عجيب في حصول الأمن، فليس للخائف الذي قد اشتد خوفه أنفع من ذكر الله عز وجل، فإنّه بحسب ذكره يجد الأمن ويزول خوفه..",1,185,"/edition/42/section/9999#page-233",160,13],["فتنة الشبهات تدفع باليقين،\n\nوفتنة الشهوات تدفع بالصبر،\n\nولذلك جعل سبحانه إمامة الدين\nمنوطةً بهذين الأمرين.",7,903,"/edition/13/section/4782#page-944",9,13],["لا تحتقرْ دعاءَ المظلوم فشررُ قلبهِ محمولٌ بعجيج صوته إلى سقف بيتِكَ، ويْحَك نِبالْ أدعيتهَ مُصِيبة وإن تأخَّرَ الوقتُ، قوسُهُ قلبُهُ المقروحُ، ووَتَرهُ سوادُ اللَّيل، وأستاذُه صاحب: \"لأنصرنك ولو بعد حين\"، \"وقد رأيت ولكن لستَ تعتبِرُ\" .\n\nاحذر عداوة منِ ينام وطرفه باك، يقلِّب وجهه نحو السماء، يرمي سهاما ما لها غرض سوى الأحشاءِ منك..",15,242,"/edition/43/section/10153#page-737",224,13],["الشحّ والجبن أردأ صفتين في العبد، ولا سيما إذا كان شحه هالعًا، أي: مُلق له في الهلع، وجبنه خالعًا، أي: قد خلع قلبه من مكانه، فلا سماحة ولا شجاعة، لا نفع بماله ولا ببدنه، كما يُقال: لا طعنة ولا جفنة، ولا يطرد ولا يثرد، بل قد قمعه وصغّره وحقّره ودسّاه الشح والخوف والطمع والفزع.\n\nوإذا أردت معرفة الهلوع، فهو الذي إذا أصابه الجوع أظهر الاستجاعة وأسرع بها، وإذا أصابه الألم أسرع الشكاية، وإذا أصابه القهر أظهر الاستضامة والاستكانة وباء بها سريعًا.\n\nوإذا أصابه الوجع أسرع الانطراح على جنبه، وأظهر الشكاية. وإذا بدا له مأخذ طمع طار إليه سريعًا. وإذا ظفر به أحلّه من نفسه محل الروح فلا احتمال ولا إفضال.\n\nوهذا كله من صغر النفس ودناءتها، وتدسيتها في البدن وإخفائها وتحقيرها، واللَّه المستعان.",5,530,"/edition/67/section/16057#page-574",48,13],["أتى رجلٌ أبا مسلمٍ الخولاني فقال له: أوصني يا أبا مسلم، قال: اذْكُر الله تعالى تحت كل شجرةٍ  ومَدَرَةٍ، فقال: زدني، فقال: اذكر الله تعالى حتى يحسبك الناس من ذِكْر الله تعالى مَجْنُونًا.",1,171,"/edition/42/section/9985#page-219",128,13],["وقد رتّب الله سبحانه حصولَ الخيرات في الدنيا والآخرة، وحصولَ الشرور في الدنيا والآخرة في كتابه على الأعمال، ترتيب الجزاء على الشرط، والمعلول على العلة، والمسبّب على السبب، وهذا في القرآن يزيد على ألف موضع.",0,31,"/edition/20/section/6375#page-97",2304,12],["قال يحيى بن معاذ الرازي:\nعجبتُ من ذي عقل يقول في دعائه: اللهم لا تُشْمِتْ بي الأعداءَ، ثم هو يُشْمِتُ بنفسه كلَّ عدو له!\nقيل: وكيف ذلك؟\nقال: يعصي الله فيُشْمِتُ به في القيامة كلَّ عدو.",0,132,"/edition/20/section/6396#page-198",2064,12],["وإذا كان العبد، وهو في الصلاة، ليس له إلا ما عقل منها، فليس له من عمره إلا ما كان فيه بالله وله.",0,359,"/edition/20/section/6493#page-425",320,12],["وإذا أردت أن تستدل على ما في القلب، فاستدِلَّ عليه بحركة اللسان، فإنّه يُطلِعُ ما في القلب، شاء صاحبه أم أبى.",0,363,"/edition/20/section/6493#page-429",32,12],["فيا ناكحي الذُّكرانِ يهنيكم البشرى ...\nفيومَ معادِ الناس إنّ لكم أجرا\nكلوا واشربوا وازنُوا ولوطوا وأبشِروا ...\nفإنكمُ زَفًّا إلى الجنّة الحمرا\nفإخوانكم قد مهّدوا الدارَ قبلكم ...\nوقالوا: إلينا عجِّلوا لكم البشرى\nوها نحن أسلاف لكم في انتظاركم ...\nسيجمعنا الجبَّارُ في ناره الكبرى\nولا تحسَبوا أنّ الذين نكحتمُ ...\nيغيبون عنكم بل ترونهمُ جَهْرا\nويلعن كلٌّ منكمُ لخليله ...\nويشقَى به المحزونُ في الكرّة الأخرى\nيعذَّب كلٌّ منهمُ بشريكه ...\nكما اشتركا في لذّةٍ تُوجِب الوِزْرا",0,404,"/edition/20/section/6499#page-470",3200,12],["فمتى كان العبد بالله هانت عليه المشاق، وانقلبت المخاوف في حقِّه أمانًا.\nفبالله يهون كل صعب، ويسهل كل عسير، ويقرب كل بعيد.\nوبالله تزول الهموم والغموم والأحزان.\nفلا هم مع الله، ولا غم، ولا حزن.",0,436,"/edition/20/section/6509#page-502",1024,12],["أعقَلُ الناسِ من آثر لذته وراحته الآجلة الدائمة على العاجلة المنقضية الزائلة، وأسفهُ الخلقِ من باع نعيم الأبد وطيب الحياة الدائمة واللذة العظمى التي لا تنغيص فيها ولا نقص بوجهٍ ما، بلذّة منغَّصة مشوبة بالآلام والمخاوف، وهي سريعة الزوال وشيكة الانقضاء.",0,450,"/edition/20/section/6519#page-516",1024,12],["إذا أراد الله بعبده خيرًا فتح له بابًا من أبواب التوبة، والندم، والانكسار، والذل، والافتقار، والاستغاثة به، وصِدْقِ اللَّجأ إليه، ودوام التضرع، والدعاء، والتقرب إليه بما أمكن من الحسنات = ما تكون تلك السيئة به سبب رحمته، حتى يقول عدو الله: يا ليتني تركته ولم أُوقِعْهُ.",1,9,"/edition/42/section/9890#page-57",132,12],["المؤمن قلبه مضيء يكاد يعرف الحق بفطرته وعقله، ولكنْ لا مادة له من  نفسه، فجاءت مادة الوحي فباشرت قلبه، وخالطت بشاشته، فازداد نورًا بالوحي على نوره الذي فطره الله تعالى عليه، فاجتمع له نور الوحي إلى نور الفطرة، نورٌ على نور، فيكاد ينطق بالحق وإن لم يسمع فيه أثرًا، ثم يسمع الأثر مطابقًا لما شهدت به فطرته، فيكون نورًا على نور، فهذا شأن المؤمن يدرك الحق بفطرته مجملًا، ثم يسمع الأثر جاء به مفصلًا، فينشأ إيمانه عن شهادة الوحي والفطرة.",1,123,"/edition/42/section/9970#page-171",48,12],["قال أبو خلاد البصري:\nمن دخل في الإسلام دخل في حِصْن، ومن دخل المسجد فقد دخل في حِصْنَيْن، ومن جلس في حلقة يذكر الله عز وجل فيها فقد دخل في ثلاثة حصون.",1,207,"/edition/42/section/10013#page-255",129,12],["كان ذو البِجادَين يتيمًا في الصِّغَرِ، فكَفَلَهُ عمُّه، فنازعتْه نفسُه إلى اتباع الرسولِ، فهَمَّ بالنُّهوضِ؛ فإذا بقيةُ المرض مانعةٌ، فقعد ينتظرُ العمَّ، فلما تكاملتْ صحَّتُهُ؛ نَفِدَ الصبرُ، فناداه ضميرُ الوجدِ، فقال: يا عمُّ! طال انتظاري لإسلامِكَ، وما أرى منكَ نشاطًا!! فقال: والله؛ لئنْ أسلمتَ لأنتزِعَنَّ كلَّ ما أعطيتُكَ. فصاح لسانُ الشوقِ: نظرةٌ من محمدٍ أحبُّ إليَّ من الدُّنيا وما فيها، فلمَّا تجرَّدَ للسير إلى الرسول؛ جرَّدَهُ عمُّه من الثياب، فناولتْهُ الأمُّ بِجادًا، فقطعَهُ لسفرِ الوصل نصفين؛ اتَّزرَ بأحدِهِما وارتدى بالآخر، فلما نَادى صائحُ الجهاد؛ قنِعَ أن يكون في ساقةِ الأحباب، والمحبُّ لا يرى طولَ الطريق؛ لأنَّ المقصودَ يُعينُهُ. فلما قضى نَحْبَهُ نزل الرسولُ يُمهِّدُ له لَحْدَهُ، وجعل يقولُ: «اللهمَّ! إنِّي أمْسَيتُ عنهُ راضيًا؛ فارْضَ عنْهُ». فصاحَ ابنُ مسعودٍ: يا ليتني كنتُ صاحبَ القبرِ.",2,60,"/edition/37/section/9185#page-67",2584,12],["جعل الله بحكمتِهِ كلَّ جزءٍ من أجزاءِ ابن آدم -ظاهرةً وباطنةً- آلةً لشيءٍ؛ إذا استُعملَ فيه فهو كمالُهُ: فالعينُ آلةٌ للنظرِ، والأذُن آلةٌ للسَّماع، والأنفُ آلةٌ للشمِّ، واللسانُ للنُّطقِ، والفرجُ للنِّكاح، واليدُ للبطش، والرِّجْلُ للمشي، والقلبُ للتوحيد والمعرفة، والرُّوحُ للمحبَّةِ، والعقلُ آلةٌ للتفكُّرِ والتدبُّر لعواقبِ الأمور الدينيَّةِ والدنيويَّةِ وإيثارِ ما ينبغي إيثارُه وإهمالِ ما ينبغي إهمالُه.",2,81,"/edition/37/section/9204#page-88",33,12],["سبحان الله! في النفس: كِبْرُ إبليسُ، وحسدُ قابيل، وعُتُوُّ عادٍ، وطغيانُ ثمودَ، وجرأةُ نمرود، واستطالةُ فرعون، وبَغْيُ قارون، وقِحَةُ هامان، وهَوَى بَلْعام، وحِيَلُ أصحابِ السبت، وتمرُّدُ الوليد، وجهل أبي جهل.\nوفيها من أخلاق البهائم: حِرصُ الغُراب، وشَرَهُ الكلب، ورُعونة الطاووس، ودناءة الجُعَل، وعقوق الضبِّ، وحِقدُ الجمل، ووثوبُ الفهد، وصَولةُ الأسد، وفِسقُ الفأرة، وخُبثُ الحية، وعَبَثُ القرد، وجمعُ النملة، ومكر الثعلب، وخِفَّةُ الفَراش، ونوم الضَّبُع.\nغير أنَّ الرياضة والمجاهدة تُذْهِبُ ذلك.",2,106,"/edition/37/section/9223#page-113",16,12],["سرُّ التوكُّل وحقيقتهُ هو اعتمادُ القلب على الله وحدَه: فلا يَضُرُّهُ مباشرةُ الأسباب؛ مع خلوِّ القلب من الاعتماد عليها والركونِ إليها، كما لا ينفعه قوله: توكَّلْتُ على الله؛ مع اعتمادِه على غيره ورُكونِه إليه وثقتِه به.",2,126,"/edition/37/section/9236#page-133",32,12],["كلُّ أحدٍ مطبوعٌ على أن لا يتركَ النفعَ العاجلَ واللَّذَّةَ الحاضرةَ إلى النفع الآجل واللَّذَّة الغائبة المنتظرة إلا إذا تبيَّنَ له فَضْلُ الآجلِ على العاجلِ وقوِيَتْ رغبتُهُ في الأعلى الأفضل.\nفإذا آثرَ الفانيَ الناقصَ كان ذلك إما لعدم تبيُّنِ الفضل له، وإما لعدم رغبتهِ في الأفضل؛ وكلُّ واحدٍ من الأمرين يدُلُّ على ضعفِ الإيمان وضعف العقل والبصيرة.",2,137,"/edition/37/section/9244#page-144",1024,12],["إذا غُذِيَ القلبُ بالتذكُّر، وسُقِي بالتفكُر، ونُقِّيَ من الدَّغل؛ رأى العجائبَ وأُلهِمَ الحكمةَ.",2,143,"/edition/37/section/9249#page-150",1056,12],["خَرابُ القلبِ من الأمن والغفلة، وعِمارتُهُ من الخشية والذِّكْرِ.",2,143,"/edition/37/section/9249#page-150",160,12],["مدارُ الشأن على همة العبد ونيَّته، وهما مطلوبُهُ وطريقُهُ، ولا يتمُّ له إلا بتركِ ثلاثة أشياء:\nالأول: العوائد والرسوم والأوضاع التي أحدثَها الناس.\nالثاني: هجرُ العوائق التي تعوقه عن إفراد مطلوبه وطريقه وقطعها.\nالثالث: قطع علائق القلب التي تحول بينه وبين تجريد التعلق بالمطلوب.\nوالفرق بينهما: أن العوائق هي الحوادث الخارجية، والعلائق هي التعلُّقات القلبية بالمباحات ونحوها.",2,211,"/edition/37/section/9303#page-218",32,12],["إذا فارقت الروحُ البدنَ التحقتْ برفيقها الأعلى أو الأدنى؛ فعند الرفيق الأعلى كلُّ قرةِ عين وكلُّ نعيم وسرور وبهجة ولذة وحياة طيبة، وعند الرفيق الأسفل كلُّ همّ وغمّ وضيق وحزن وحياة نكِدةٍ ومعيشة ضَنْكٍ.",2,246,"/edition/37/section/9330#page-253",1024,12],["العارف يدعو الناسَ إلى الله من دنياهم فتسهُلُ عليهم الإجابة،\n\nوالزاهد يدعوهم إلى الله بترك الدنيا فتشُقُّ عليهم الإجابة.",2,247,"/edition/37/section/9331#page-254",128,12],["الصبر آخيّة المؤمن التي يجول ثم يرجع إليها، وساقُ إيمانه التي لا اعتماد له إلا عليها، فلا إيمان لمن لا صبر له، وإن كان فإيمانٌ قليلٌ في غاية الضعف.",5,9,"/edition/67/section/16013#page-53",8,12],["النفس فيها قوّتان: قوة الإقدام، وقوة الإحجام، فحقيقة الصبر أن يجعل قوة الإقدام مصروفة إلى ما ينفعه، وقوة الإحجام إمساكًا عما يضره.",5,26,"/edition/67/section/16019#page-70",24,12],["أن [الله] سبحانه رتّب المغفرة والأجر الكبير على الصبر والعمل الصالح، فقال: ﴿إِلَّا الَّذِينَ صَبَرُوا وَعَمِلُوا الصَّالِحَاتِ أُولَئِكَ لَهُمْ مَغْفِرَةٌ وَأَجْرٌ كَبِيرٌ (١١)﴾ [هود: ١١].",5,132,"/edition/67/section/16038#page-176",8,12],["قال سليمان بن القاسم: «كل عمل يعرف ثوابه إلا الصبر، قال اللَّه تعالى: ﴿إِنَّمَا يُوَفَّى الصَّابِرُونَ أَجْرَهُمْ بِغَيْرِ حِسَابٍ (١٠)﴾ [الزمر: ١٠].",5,177,"/edition/67/section/16040#page-221",8,12],["قال الحسن البصري: «إن الله ليمتع بالنعمة ما شاء، فإذا لم يُشكر عليها قلَبَها عذابًا».",5,120,"/edition/66/section/15985#page-95",33,12],["الشكر يتعلق بالقلب واللسان والجوارح: فالقلب للمعرفة والمحبة، واللسان للثناء والحمد، والجوارح لاستعمالها في طاعة المشكور وكفها عن معاصيه.",5,293,"/edition/67/section/16050#page-337",544,12],["المأمور لا يؤدّى إلا بصبر وشكر، والمحظور لا يُترك إلا بصبر وشكر.",5,296,"/edition/67/section/16050#page-340",8,12],["للنفس قوتان: قوة الصبر والكف وإمساك النفس، وقوة البذل وفعل الخير والإقدام على فعل ما تكمل به. وكمالها باجتماع هاتين القوتين فيها.",5,337,"/edition/67/section/16051#page-381",24,12],["شهوات الدنيا في القلب كشهوات الأطعمة في المعدة، وسوف يجد العبد عند الموت لشهوات الدنيا في قلبه من الكراهة والنتن والقبح ما يجده للأطعمة اللذيذة إذا انتهت في المعدة غايتها.",5,445,"/edition/67/section/16054#page-489",2080,12],["امتداد المال كامتداد العمر والجاه، فخير الناس من طال عمره وحسن عمله، فهكذا من امتد ماله وكثر خيره، فنعم المرء وماله وجاهه: إما أن يرفعه درجات، وإما أن يضعه درجات.",5,513,"/edition/67/section/16055#page-557",64,12],["مما يقدح في الصبر: إظهار المصيبة والتحدث بها، وكتمانها رأس الصبر.",5,529,"/edition/67/section/16057#page-573",8,12],["الصلاة على النبي ﷺ للدعاء بمنزلة الفاتحة من الصلاة، فمفتاح الدعاء الصلاة على النبي ﷺ، كما أن مفتاح الصلاة الطهور، فصلى الله عليه وعلى آله وسلم تسليمًا.",6,377,"/edition/48/section/11909#page-347",384,12],["القلب إذا كان فيه مرضٌ؛ آذاه أدنى شيء من الشبهة أو الشهوة، حيث لا يقدر على دفعهما إذا وردا عليه.",7,18,"/edition/12/section/4091#page-16",33,12],["النفس النجسة الخبيثة يقوى خبثُها ونجاستها حتى يبدوَ على الجسد، والنفسُ الطيبة بضدها، فإذا تجردت وخرجت من البدن وُجِدَ لهذه كأطيب نَفْحَة مسكٍ وُجِدتْ على وجه الأرض، ولتلك كأنتن ريح جِيفةٍ وُجدتْ على وجه الأرض.",7,101,"/edition/13/section/4182#page-142",16,12],["نجاسة الزنا واللواط أغلظ من غيرهما من النجاسات، من جهة أنها تُفسِد القلب، وتُضعِف توحيده جدًّا، ولهذا أحظى الناس بهذه النجاسة أكثرهم شركًا؛ فكلما كان الشرك في العبد أغلب كانت هذه النجاسة والخبائث فيه أكثر، وكلما كان أعظم إخلاصًا كان منها أبعد.",7,106,"/edition/13/section/4185#page-147",33,12],["كلما صح القلب من مرضه ترحل إلى الآخرة، وقرب منها، حتى يصير من أهلها، وكلما مرض القلب واعتلَّ آثر الدنيا واستوطنها، حتى يصير من أهلها.",7,118,"/edition/13/section/4191#page-159",2080,12],["النفس قد تكون تارة أمّارةً، وتارة لوامةً، وتارة مطمئنةً، بل في اليوم الواحد والساعة الواحدة يحصل فيها  هذا وهذا وهذا، والحكم للغالب عليها من أحوالها، فكونها مطمئنةً وصفُ مدحٍ لها، وكونها أمّارةً بالسوء وصفُ ذمٍّ لها، وكونها لوامةً ينقسم إلى المدح والذم، بحسب ما تلوم عليه.",7,131,"/edition/13/section/4200#page-172",80,12],["كل نَفَسٍ من أنفاس العمر جوهرة نفيسة لا خَطَرَ لها، يمكن أن يُشترى به كنز من الكنوز لا يتناهى نعيمه أبدَ الآباد، فإضاعة هذه الأنفاس، أو اشتراء صاحبها بها ما يَجلِب هلاكَه: خسران عظيم، لا يَسمح بمثله إلا أجهلُ الناس وأحمقهم وأقلهم عقلًا، وإنما يظهر له حقيقة هذا الخسران يوم التغابن.",7,137,"/edition/13/section/4202#page-178",64,12],["الشيطان أحرصُ ما يكون على الإنسان عندما يهُمُّ بالخير، أو يدخل فيه، فهو يشتد عليه حينئذٍ ليقطعه عنه، وكلما كان الفعل أنفع للعبد وأحب إلى الله، كان اعتراض الشيطان له أكثر، فأمر سبحانه العبد أن يحارب عدُوَّه الذي يقطع عليه الطريق، ويستعيذ بالله منه أولًا، ثم يأخذ في السير، كما أن المسافر إذا عرض له قاطع طريق اشتغل بدفعه، ثم اندفع في سيره.",7,160,"/edition/13/section/4214#page-201",16,12],["وما أحسنَ ما قال أبو أحمد الشيرازي: «كان الصوفية يَسْخَرون من الشيطان، والآن الشيطان يسخر منهم».",7,217,"/edition/13/section/4242#page-258",16,12],["ولو كانت الوسوسة فضيلة لما ادخرها الله عن رسوله وصحابته، وهم خير الخلق وأفضلهم، ولو أدرك رسول الله ﷺ الموسوسين لمقتهم، ولو أدركهم عمر لضربهم وأدبهم، ولو أدركهم الصحابة لبدعوهم.",7,237,"/edition/13/section/4253#page-278",16,12],["أمر النبي ﷺ بتكذيب الشيطان فيما يحتمل صدقه فيه، فكيف إذا كان كذبه معلومًا متيقنًا، كقوله للموسوس: لم تفعل كذا، وقد فعله!",7,251,"/edition/13/section/4261#page-292",16,12],["كل من امتنع أن يذل لله، أو يبذل ماله في مرضاته، أو يتعب نفسه في طاعته، لابد أن يذل لمن لا يسوى، ويبذل له ماله، ويتعب نفسه وبدنه في طاعته ومرضاته عقوبة له.",7,943,"/edition/13/section/4890#page-984",16,12],["ليس في الجنَّة لذَّةٌ أعظمُ من النظر إلى وجه الرَّبِّ تعالى، وسماعِ كلامه منه، ولا يُعْطَى أهل الجنَّة شيئًا أحبَّ إليهم من ذلك.",8,554,"/edition/51/section/12239#page-604",3073,12],["تذاكر العلم في الجنة\n\nوإذا تذاكروا ما كان بينهم، فتذاكرهم فيما كان يُشْكِلُ عليهم في الدنيا من مسائل العلم، وفهم القرآن والسنة، وصِحَّة الأحاديث أولى وأحرى، فإن المذاكرة في الدنيا في ذلك ألذُّ من الطعام والشراب والجماع، فتذاكر ذلك في الجنَّة أعظم لذَّة، وهذه لذَّة يختص بها أهل العلم، ويتميزون بها على من عداهم. واللَّه المستعان.",8,820,"/edition/51/section/12320#page-871",3328,12],["حدَّثني شيخنا [ابن تيمية] قال: ابتدأ بي مرضٌ، فقال لي الطبيب: إنَّ مطالعتَك، وكلامَك في العلم يزيدُ المرضَ.\nفقلت له: لا أصبرُ عن ذلك، وأنا أُحاكمك إلى علمك: أليستِ النفسُ إذا فرحتْ وسُرّت قويت الطبيعةُ، فدفعتِ المرض؟\nفقال: بلى!\nفقلت له: فإنَّ نفسي تُسَرُّ بالعلم، فتقوى به الطبيعة، فأجدُ راحةً.\nفقال: هذا خارجٌ عن علاجنا، أو كما قال.",9,109,"/edition/57/section/12640#page-135",24,12],["قال بعض السلف: من كان له واعظ من قلبه؛ زاده الله ــ عز وجل ــ عزا، والذل في طاعة الله أقرب من العز في معصيته.",9,397,"/edition/56/section/12533#page-392",34,12],["الهوى رق في القلب، وغل في العنق، وقيد في الرجل، ومتابعه أسير لكل سيئ الملكة، فمن خالفه عتق من رقه، وصار حرا، وخلع الغل من عنقه، والقيد من رجله، وصار بمنزلة رجل سلم لرجل، بعد أن كان رجلا فيه شركاء متشاكسون.",9,646,"/edition/57/section/12911#page-672",33,12],["ما دعا إليه الرسول - ﷺ - هو حياة القلوب، ونجاة النفوس، ونور البصائر، وما يدعو إليه مخالفوه فهو موت القلوب، وهلاك النفوس، وعمى البصائر. قال الله تعالى: ﴿ياأيها الذين آمنوا استجيبوا لله وللرسول إذا دعاكم لما يحييكم واعلموا أن الله يحول بين المرء وقلبه وأنه إليه تحشرون﴾ [الأنفال: ٢٤].",10,16,"/edition/38/section/9413#page-77",160,12],["الصوم ثمرته تطهيرُ النفس، وثمرة الزكاة تطهير المال، وثمرة الحج وجوب المغفرة، وثمرة الجهاد تسليم النفس التي اشتراها سبحانه من العباد وجعلَ الجنة ثمنَها، فالصلاة ثمرتها الإقبال على الله، وإقبال الله سبحانه على العبد، وفي الإقبال جميع ما ذُكِرَ من ثمراتِ الأعمال.",10,149,"/edition/38/section/9520#page-210",2320,12],["الناس أربعة أقسام:\nأحدها: من يشتغل بسماع القرآن عن سماع الشيطان.\nوالثاني: عكسه.\nوالثالث: من له نصيب من هذا وهذا.\nوالرابع: من ليس له نصيب لا من هذا ولا من هذا.\nفالاشتغال بالسماع القرآني الرحماني حال السابقين الأولين وأتباعهم ومن سلك سبيلهم.\nوالثاني: حال المشركين والمنافقين والفُجَّار والفُسَّاق والمبطلين ومن سلك سبيلهم.\nوالثالث: حالُ مؤمنٍ له مادتان، مادة من القرآن ومادة من الشيطان، وهو للغالب عليه منهما.\nوالرابع: حال الفارغ من ذوق هذا وهذا، فهو في شأنٍ وأولئك في شأنٍ.",10,310,"/edition/38/section/9660#page-370",272,12],["وقبيح بالسالك الصادق أن يؤثر حظ نفسه وإرادتها على حق ربه ومراده منه، حتى يفنى بحظه عن الحق الذي عليه، بل يبلغ به تلبيس النفس والشيطان إلى أن يصير محض حظه وقوت نفسه هو الطريق إلى الله، ويجعله طريق الخواص، وطريقة الأمر واتباع الرسول عنده طريقة العوام.",10,414,"/edition/38/section/9710#page-474",16,12],["الكمال أن يكون الشخص كاملا في نفسه، مكملا لغيره، وكماله بإصلاح قوتيه العلمية والعملية، فصلاح القوة العلمية بالإيمان، وصلاح القوة العملية بعمل الصالحات، وتكميله غيره بتعليمه إياه، وصبره عليه، وتوصيته بالصبر على العلم والعمل.",11,153,"/edition/73/section/17991#page-253",24,12],["أشرف ما في الإنسان محل العلم منه، وهو قلبه وسمعه وبصره.\nولما كان القلب هو محل العلم، والسمع رسوله الذي يأتيه به، والعين طليعته؛ كان ملكا على سائر الأعضاء، يأمرها فتأتمر لأمره، ويصرفها فتنقاد له طائعة، بما خص به من العلم دونها، فلذلك كان ملكها والمطاع فيها.\nوهكذا العالم في الناس كالقلب في الأعضاء.\nولما كان صلاح الأعضاء بصلاح ملكها ومطاعها، وفسادها بفساده؛ كانت هذه حال الناس مع علمائهم وملوكهم، كما قال بعض السلف: «صنفان إذا صلحا صلح الناس، وإذا فسدا فسد الناس: العلماء والأمراء».",11,104,"/edition/72/section/17746#page-102",33,12],["وإذا أحب الله عبدا اصطنعه لنَفسِهِ، واجتباه لمحبته، واستخلصه لعبادته، فشغل همه بِهِ، وَلسَانه بِذكرِهِ، وجوارحه بخدمته .",2,143,"/edition/37/section/9249#page-150",528,12],["الحزن يضعف القلب ، ويوهن العزم ، ويضر الإرادة،ولا شيء أحب إلى الشيطان من حزن المؤمن.",12,279,"/edition/64/section/15640#page-255",1072,12],["الذكر يُنَوِّر القلب والوجه والأعضاء، وهو نور العبد في دنياه، وفي البرزخ، وفي يوم القيامة.\nوعلى حسب نور الإيمان في قلب العبد تَخْرُجُ أعماله وأقواله ولها نورٌ وبرهان، حتى إن من المؤمنين من يكون نور أعماله إذا صعدت إلى الله تبارك وتعالى كَنُورِ الشمس، وهكذا نور روحه إذا قَدِم بها على الله عز وجل، وهكذا يكون نورهُ السّاعي بين يديه على الصراط، وهكذا يكون نور وجهه في يوم القيامة، والله تعالى المستعان وعليه التكلان.",1,155,"/edition/42/section/9978#page-203",2208,12],["وههنا لطيفة يجب التنبه لها، وهي أن المحبّة المجرّدة لا توجب هذا الأثَر ما لم تقترن بإجلال المحبوب وتعظيمه، فإذا قارنها الإجلالُ والتعظيمُ أوجبت هذا الحياءَ والطاعة، وإلّا فالمحبة الخالية عنهما إنّما توجب نوعَ أُنس وانبساط وتذكّر واشتياق. ولهذا يتخلّف عنها أثرها وموجَبها ، ويفتّش العبد قلبَه فيرى نوع محبّة للَّه، ولكن لا تحمله على ترك معاصيه، وسبب ذلك تجرّدها عن الإجلال والتعظيم. فما عمر القلبَ شيءٌ كالمحبّة المقترنة بإجلال اللَّه وتعظيمه، وتلك من أفضل مواهب اللَّه لعبده أو أفضلها، وذلك فضل اللَّه يؤتيه من يشاء.",12,590,"/edition/65/section/15854#page-675",544,12],["مَن أُلهِمَ الدعاءَ فقد أريد به الإجابة، فإنّ الله سبحانه يقول: {ادْعُونِي أَسْتَجِبْ لَكُمْ} [غافر: ٦٠] وقال: {وَإِذَا سَأَلَكَ عِبَادِي عَنِّي فَإِنِّي قَرِيبٌ أُجِيبُ دَعْوَةَ الدَّاعِ إِذَا دَعَانِ} [البقرة: ١٨٦].",0,30,"/edition/20/section/6374#page-96",1152,12],["قاعدة قد أشرنا إليها مرارًا، وهي: أن مِن دعاءِ الله بأسمائه الحسنى أن يسأل في كل مطلوب، ويتوسل إليه بالاسم المقتضي لذلك المطلوب المناسب لحصوله، حتى إن الداعي متشفع إلى الله متوسل إليه به، فإذا قال: \"ربِّ اغفر لي وتُبْ عليَّ إِنك أنت التواب الغفور\"، فقد سأله أمرين، وتوسَّل إليه باسمين من أسمائه مقتضيين لحصول مطلوبه، وكذلك قول النبي - صلى الله عليه وسلم - لعائشة -رضي الله عنها- وقد سألته ما تدعو به إن وأفقت ليلة القدر؛ \"قولي: اللهم إنَّك عَفُوٌّ تحبُّ العفوَ فاعفُ عني\" ، وكذلك قوله للصديق -رضي الله عنه- وقد سأله أن يعلِّمه دعاءً يدعو به: \"اللهمَّ إني ظلمتُ نفسي ظُلمًا كثيرًا وإنه لا يغفرُ الذنوبَ إلا أنتَ فاغفرْ لى مغفرةً من عندكَ وارحمني إنَّك أنتَ الغفورُ الرَّحيم\" ..",15,615,"/edition/44/section/10375#page-704",130,12],["القلب لا يطمئنُّ إلّا بالإيمان واليقين، ولا سبيلَ إلى حصول الإيمان واليقين إلّا من القرآن، فإنّ سكون القلب وطمأنينته من يقينه ، واضطرابه وقلقَه من شكِّه. والقرآن هو المحصِّل لليقين، الدّافع للشُّكوك والظُّنون والأوهام، فلا تطمئنُّ  قلوب المؤمنين إلّا به.",13,348,"/edition/71/section/17363#page-1735",288,12],["قال أبو الدرداءِ رضي الله عنه: يا حبَّذا نومُ الأكياس وفِطْرُهم؛ كيف يغبنون به قيام الحمقى وصومهم؛ والذرةُ من صاحب تقوى أفضلُ من أمثال الجبال عبادةً من المُغترِّين ؟!\n\nوهذا من جواهر الكلام وأدلِّه على كمال فقه الصحابة وتقدمهم على من بعدهم في كل خير رضي الله عنهم.\n\nفاعلمْ أن العبد إنما يَقطع منازلَ السير إلى الله بقلبه وهمته لا ببدنِه، والتقوى في الحقيقة تقوى القلوب لا تقوى الجوارح.",2,206,"/edition/37/section/9297#page-213",32,12],["من كان مشغولًا باللَّه وبذكره ومحبته في حال حياته وجد ذلك أحوجَ ما هو إليه عند خروج روحه إلى اللَّه. ومن كان مشغولًا بغيره في حال حياته وصحّته فيعسر عليه اشتغاله باللَّه وحضوره معه عند الموت، ما لم تدركه عناية من ربّه. ولأجل هذا كان جديرًا بالعاقل أن يُلزِم قلبَه ولسانه ذكرَ اللَّه حيثما كان، لأجل تلك اللحظة التي إن فاتته شقي شقاوة الأبد. فنسأل اللَّه أن يعيننا على ذكره وشكره وحسن عبادته.",12,308,"/edition/64/section/15640#page-284",2720,12]]};
